update public.iq_questions set slug = 'baserunning-3-18' where slug is null and track = 'baserunning' and level = 3 and scenario = 'One out, runner on second. You hit a blooper to shallow left, the left fielder drops it, and the ball rolls a few feet away. You''ve rounded first.';
