update public.iq_questions set slug = 'baserunning-3-22' where slug is null and track = 'baserunning' and level = 3 and scenario = 'One out, you''re on first. The batter hits a ball into the right-center gap. As you approach third, the third baseman has already caught the relay throw and is standing in front of the bag, waiting to tag you.';
update public.iq_questions set slug = 'baserunning-3-23' where slug is null and track = 'baserunning' and level = 3 and scenario = 'One out, runner on third, and the squeeze is on. You''re the batter, and the pitch comes in high and a little outside.';
