-- 2. Add new questions and update existing ones. A question a coach has hidden stays hidden.
insert into public.iq_questions
  (slug, topic, position, track, level, section, scenario, question, choices, correct_index, explanation, hint, difficulty, diagram, playbook_ref)
values
  ('defense-1-01', 'general', null, 'defense', 1, null, 'Nobody on, one out. The batter drops a bunt toward the pitcher. You''re the second baseman.', 'Where do you go?', array['Cover second base', 'Cover first base', 'Charge in toward the bunt', 'Back up the pitcher'], 1, 'The first baseman charges the bunt, so first base is empty. You slide over to cover first and take the throw while the shortstop takes second.', 'Think about which bag empties out when the corners charge.', 1, '{"runners":[],"outs":1,"you":"2B","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.3 · No runners, <2 outs: bunt coverage at 1B'),
  ('defense-1-02', 'general', null, 'defense', 1, null, 'Nobody on, nobody out. The batter bunts down the third-base side, and both you and the pitcher can get to it. You''re the third baseman.', 'Who should field it?', array['You, the third baseman', 'The pitcher', 'The catcher', 'The shortstop'], 0, 'When a corner can reach a bunt, she takes it away from the pitcher. The third baseman is the best choice because she''s already moving toward first as she picks it up. Call for it loudly.', 'Which fielder can pick it up and throw without turning her body around?', 1, '{"runners":[],"outs":0,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.3 · No runners, <2 outs: who fields the bunt'),
  ('defense-1-03', 'general', null, 'defense', 1, null, 'Nobody on, one out. Routine ground ball to the shortstop, who throws to first. You''re the catcher.', 'What''s your job on this play?', array['Stay at home plate', 'Cover third base', 'Trail the batter toward first, staying in foul ground', 'Walk out toward the mound'], 2, 'With nobody on there''s no play at the plate, so you follow the batter toward first, staying in foul ground. If the throw gets past the first baseman, you''re there to stop the batter from taking an extra base.', 'With nobody on, there''s no play at home. Where could a bad throw end up?', 1, '{"runners":[],"outs":1,"you":"C","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.6 · No runners, <2 outs: catcher backup on a ground ball'),
  ('defense-1-04', 'general', null, 'defense', 1, null, 'Nobody on, nobody out. A ground ball gets through the left side into left field for a single. You''re the left fielder.', 'Where do you throw?', array['First base', 'Third base', 'Home plate', 'Second base'], 3, 'The only runner is the batter. Get the ball to second, using the shortstop as your cut, so she can''t stretch the hit into a double.', 'Which base is the batter trying to reach next?', 1, '{"runners":[],"outs":0,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.7 · No runners, <2 outs: ground-ball single to left'),
  ('defense-1-05', 'general', null, 'defense', 1, null, 'Runner on second, nobody out. Fly ball to left field, and the runner is tagging up to try for third. You''re the shortstop going out to be the cut.', 'Where do you line up?', array['Between the left fielder and second base', 'Between the left fielder and home plate', 'Between the left fielder and third base', 'On top of third base'], 2, 'The throw is headed to third to stop the tag-up, so the cut sets up in a straight line between the left fielder and third base. Peek at the bag to check your line, and listen for teammates telling you to shift left or right.', 'A cut stands on a straight line. What are the two ends of that line?', 1, '{"runners":["second"],"outs":0,"you":"SS","ball":{"at":"LF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.27 · Runner at 2B, <2 outs: lining up as the cut on a fly to left'),
  ('defense-1-06', 'general', null, 'defense', 1, null, 'Runner on first, nobody out. A hard ground ball comes right back to you on the mound.', 'Where do you throw?', array['First base', 'Second base', 'Third base', 'Nowhere yet, look the runner back first'], 1, 'A hard-hit ball gives you time to get the lead runner at second, and the shortstop may be able to turn two. On a slow roller you''d take the sure out at first instead.', 'A hard-hit ball buys you time. Which runner can you go after?', 1, '{"runners":["first"],"outs":0,"you":"P","ball":{"at":"P","type":"ground"}}'::jsonb, 'Defensive Playbook p.13 · Runner at 1B, <2 outs: hard comebacker to the pitcher'),
  ('defense-1-07', 'general', null, 'defense', 1, null, 'Runner on first, one out. Hard grounder to the shortstop, who throws to you covering second. You''re the second baseman.', 'What do you need to do to get the runner coming from first?', array['Catch it and tag the runner as she slides in', 'Catch it and throw to first without touching the base', 'Catch it and chase the runner back toward first', 'Catch it and touch second base'], 3, 'Because the batter is running, the runner from first is forced to second. On a force out you only need the ball and a foot on the bag, and then you can turn and throw to first for the double play.', 'Is the runner from first forced to leave her base?', 1, '{"runners":["first"],"outs":1,"you":"2B","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.15 · Runner at 1B, <2 outs: force out at second'),
  ('defense-1-08', 'general', null, 'defense', 1, null, 'Nobody on, one out. The batter hits a ground-ball single to left and heads for first. You''re the first baseman covering the bag, and you don''t have the ball.', 'If you''re standing in her path and she has to run around you, what can the umpire call?', array['Obstruction on you', 'Interference on the runner', 'Nothing, the base belongs to the fielder', 'An automatic out on the runner'], 0, 'Obstruction is a defensive player without the ball getting in a runner''s way. Cover the base, but leave the runner a clear path to and around it.', 'Think about whether you had the ball when she ran into your path.', 1, '{"runners":[],"outs":1,"you":"1B","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · No runners, <2 outs: obstruction at first base'),
  ('defense-1-09', 'general', null, 'defense', 1, null, 'Nobody on, two outs. A hard ground ball comes straight at you in right field.', 'Where do you throw?', array['Through the cut to second base', 'Third base', 'First base', 'Run it back in to the infield'], 2, 'A ball hit hard right at you gives you a shot at throwing the batter out at first, which ends the inning with two outs. On a normal single you''d throw through the cut to second instead.', 'How quickly did the ball reach you compared with the batter''s run?', 1, '{"runners":[],"outs":2,"you":"RF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.73 · No runners, 2 outs: hard grounder right at the right fielder'),
  ('defense-1-10', 'general', null, 'defense', 1, null, 'Runner on first, two outs. A ground ball single goes into left field, and the runner is running hard. You''re the left fielder.', 'Where does your throw go?', array['Through the cut to third base', 'Through the cut to second base', 'First base', 'Home plate'], 0, 'With two outs the runner on first is going on contact and will try to go first to third. Throw through the shortstop cut to third to keep her from getting there.', 'With two outs she was running on contact. How far is she trying to go?', 1, '{"runners":["first"],"outs":2,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.77 · Runner at 1B, 2 outs: ground-ball single to left'),
  ('defense-1-11', 'general', null, 'defense', 1, null, 'Nobody on, nobody out. The batter bunts to the pitcher, who turns to throw to the second baseman covering first. You''re the right fielder.', 'Where should you be?', array['Backing up first base', 'Backing up second base', 'Charging in toward the infield grass', 'Staying deep in right field'], 0, 'Every throw to first on a bunt needs someone behind it. Sprint in behind the bag so a wild throw doesn''t send the batter to second or third.', 'Follow the throw. Who is standing behind the target?', 1, '{"runners":[],"outs":0,"you":"RF","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.3 · No runners, <2 outs: right fielder on a bunt'),
  ('defense-1-12', 'general', null, 'defense', 1, null, 'Runner on second, one out. Ground ball back to the pitcher, and the runner breaks for third. The pitcher throws to you at third base.', 'What do you need to do to get the runner out?', array['Just touch third base', 'Tag the runner', 'Throw to first for the out', 'Step on third, then throw home'], 1, 'First base was open behind her, so the runner from second was never forced to run. That makes it a tag play: you have to put the ball on her before she reaches the bag.', 'Was anyone behind her forcing her to leave second?', 1, '{"runners":["second"],"outs":1,"you":"3B","ball":{"at":"P","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.22 · Runner at 2B, <2 outs: tag play at third'),
  ('defense-1-13', 'general', null, 'defense', 1, null, 'Runner on third, nobody out. The batter bunts it right back to the pitcher. You''re the catcher.', 'What''s your job?', array['Charge out and field it yourself', 'Follow the batter toward first', 'Stay at home and tell the pitcher where to throw', 'Cover third base'], 2, 'With a runner on third, the plate can''t be left empty. Stay home, watch whether the runner goes, and tell the pitcher to throw home or to first.', 'If you leave your spot, who guards the plate?', 1, '{"runners":["third"],"outs":0,"you":"C","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.28 · Runner at 3B, <2 outs: catcher on a bunt to the pitcher'),
  ('defense-1-14', 'general', null, 'defense', 1, null, 'Runner on third, one out. Fly ball to left field, and the runner tags up to try to score. You''re the pitcher.', 'Where do you go?', array['Back up third base', 'Cover home plate', 'Stay on the mound', 'Back up home plate'], 3, 'The throw is coming to the plate through the cut, and the catcher is taking it. Get behind home, in line with the throw, so a ball that gets away doesn''t roll to the backstop.', 'Where is the throw going, and who is behind that spot?', 1, '{"runners":["third"],"outs":1,"you":"P","ball":{"at":"LF","type":"fly"}}'::jsonb, 'Defensive Playbook p.35 · Runner at 3B, <2 outs: pitcher''s backup on a fly to left'),
  ('defense-1-15', 'general', null, 'defense', 1, null, 'Runner on third, one out. As the pitch is released, the runner sprints for home and the batter squares around to bunt. You''re the catcher.', 'What is the offense running?', array['A squeeze', 'A hit-and-run', 'A delayed steal', 'A fake bunt and slash'], 0, 'On a squeeze, the runner leaves third with the pitch and the batter has to get the bunt down wherever it''s thrown. Everyone near the plate should expect the throw to go home.', 'Why would the runner leave before the ball is even bunted?', 1, '{"runners":["third"],"outs":1,"you":"C","arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: the squeeze'),
  ('defense-1-16', 'general', null, 'defense', 1, null, 'Runners on first and second, nobody out. Before the pitch, your coach yells, "Look for the lead runner!" You''re the third baseman.', 'Which runner is she talking about?', array['The runner on first', 'The runner on second', 'The batter', 'Whichever runner is fastest'], 1, 'The lead runner is the one farthest along, with no runner ahead of her. Here that''s the runner on second, the one closest to scoring.', 'Which runner has nobody in front of her?', 1, '{"runners":["first","second"],"outs":0,"you":"3B"}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: the lead runner'),
  ('defense-1-17', 'general', null, 'defense', 1, null, 'Nobody on, two outs. The batter bunts down the third-base line and the third baseman charges in and fields it. You''re the pitcher, and you charged too.', 'Now that she has the ball, where do you go?', array['Cover first base', 'Back up home', 'Cover third base', 'Stay where you are'], 2, 'When the third baseman comes in for the bunt, her base is empty. Peel off and cover it so a bad throw doesn''t hand the batter an easy extra base.', 'Which bag did the fielder leave behind?', 1, '{"runners":[],"outs":2,"you":"P","ball":{"at":"bunt-3B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.71 · No runners, 2 outs: covering third on a bunt to third'),
  ('defense-1-18', 'general', null, 'defense', 1, null, 'Nobody on, two outs. Ground ball single up the middle into center field. You''re the pitcher.', 'Where do you go?', array['Back up first base', 'Back up third base', 'Cover home', 'Back up second base'], 3, 'The center fielder''s throw is going to second to hold the batter at first. Get in line behind second so an overthrow doesn''t give her another base.', 'Follow the throw: where will the center fielder send it?', 1, '{"runners":[],"outs":2,"you":"P","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.73 · No runners, 2 outs: pitcher''s backup on a single to center'),
  ('defense-1-19', 'general', null, 'defense', 1, null, 'Nobody on, two outs. A ground ball rolls through the right side for a single, not hit hard enough for a play at first. You''re the second baseman.', 'What''s your job once the ball is past you?', array['Go out and be the cut for a throw to second', 'Cover first base', 'Cover second base', 'Back up the right fielder'], 0, 'You go out toward the ball and line up as the cut to second. The shortstop takes the bag and receives the throw.', 'Which infielder is closest to the line between right field and second?', 1, '{"runners":[],"outs":2,"you":"2B","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.73 · No runners, 2 outs: cut on a single to right'),
  ('defense-1-20', 'general', null, 'defense', 1, null, 'Nobody on, two outs. A ground ball splits the left-center gap and the batter is rounding first. The shortstop is running out to be the cut. You''re the third baseman.', 'What''s your job?', array['Run out as a second cut', 'Cover third and help call where the throw should go', 'Cover second base', 'Back up the left fielder'], 1, 'The shortstop is the cut, so you hold your bag in case the batter tries to stretch it. Use your voice to help the outfielder and cut pick the right base.', 'Someone has to guard the farthest base the batter might try for.', 1, '{"runners":[],"outs":2,"you":"3B","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.74 · No runners, 2 outs: third baseman on a ball in the left-center gap'),
  ('defense-1-21', 'general', null, 'defense', 1, null, 'Nobody on, two outs. The batter drops a bunt a few feet in front of the plate. You charge in from third, but the catcher calls you off and picks it up.', 'What do you do next?', array['Keep running to back up the catcher', 'Cover first base', 'Get back and cover third base', 'Cover second base'], 2, 'Once you''re called off, your base is empty and you''re the closest player to it. Hustle back so a bad throw doesn''t let the batter run all the way around.', 'You left a bag empty when you charged.', 1, '{"runners":[],"outs":2,"you":"3B","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.71 · No runners, 2 outs: third baseman on a bunt the catcher fields'),
  ('defense-1-22', 'general', null, 'defense', 1, null, 'Runner on first, two outs. Ground ball single to right field, and the runner from first is heading for third. You''re the left fielder.', 'Where do you go?', array['Back up second base', 'Stay in left field', 'Back up the right fielder', 'Back up third base'], 3, 'The right fielder''s throw is going to third through the cut. You''re the player in line behind that bag, so get there before the throw does.', 'Which base is the throw headed to, and who is behind it?', 1, '{"runners":["first"],"outs":2,"you":"LF","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.78 · Runner at 1B, 2 outs: left fielder''s backup on a single to right'),
  ('defense-1-23', 'general', null, 'defense', 1, null, 'Runner on first, two outs. A hard ground ball single comes straight at you in center field, and you field it quickly.', 'Where do you throw?', array['Second base', 'Third base', 'Home plate', 'First base'], 0, 'How hard the ball is hit decides this one. A hard ball right at you is in your glove fast, so the throw goes to second; if you''d had to charge a slow ball, you''d go through the cut to third instead.', 'How quickly did the ball reach you?', 1, '{"runners":["first"],"outs":2,"you":"CF","ball":{"at":"CF","type":"ground"}}'::jsonb, 'Defensive Playbook p.77 · Runner at 1B, 2 outs: hard single right at the center fielder'),
  ('defense-1-24', 'general', null, 'defense', 1, null, 'Runner on second, two outs. Ground ball single to left field, and the throw is going home. You''re the right fielder.', 'Where do you go?', array['Back up first base', 'Back up second base', 'Back up home plate', 'Stay in right field'], 1, 'While everyone watches the play at the plate, the batter will try to take second on the throw. Get behind second so a cut-off throw or a bad relay there doesn''t get away.', 'Where will the batter-runner try to go while everyone watches home?', 1, '{"runners":["second"],"outs":2,"you":"RF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.81 · Runner at 2B, 2 outs: right fielder''s backup on a single to left'),
  ('defense-1-25', 'general', null, 'defense', 1, null, 'Runner on second, two outs. Ground ball to the third baseman. You''re the shortstop.', 'What''s your job?', array['Cover second base', 'Cover first base', 'Back up the third baseman', 'Cover home plate'], 2, 'The third baseman is making the play to first and the second baseman has second. Get behind her in case the ball skips through, so a misplay doesn''t turn into extra bases.', 'If the ball gets by the fielder, who''s there to stop it?', 1, '{"runners":["second"],"outs":2,"you":"SS","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.81 · Runner at 2B, 2 outs: shortstop on a ground ball to third'),
  ('defense-1-26', 'general', null, 'defense', 1, null, 'Runner on third, two outs. A ground ball single goes into left field, and the runner from third scores easily. You''re the left fielder.', 'Where do you throw?', array['Home plate', 'Third base', 'First base', 'Second base'], 3, 'That run is in no matter what you do. Get the ball to second through your cut so the batter stays at first and out of scoring position.', 'You can''t stop the run. Which runner can you still control?', 1, '{"runners":["third"],"outs":2,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.85 · Runner at 3B, 2 outs: single to left with a run scoring'),
  ('defense-1-27', 'general', null, 'defense', 1, null, 'Runner on third, two outs. Ground ball right back to the pitcher. You''re the second baseman.', 'What''s your job?', array['Back up the pitcher in case the ball gets by her', 'Cover first base', 'Cover second base', 'Cover home'], 0, 'The first baseman has first and the shortstop has second, so you back up the ball. If it deflects off the pitcher, you''re there to keep it in the infield.', 'If the ball deflects off the pitcher, who is behind her?', 1, '{"runners":["third"],"outs":2,"you":"2B","ball":{"at":"P","type":"ground"}}'::jsonb, 'Defensive Playbook p.84 · Runner at 3B, 2 outs: second baseman on a comebacker'),
  ('defense-1-28', 'general', null, 'defense', 1, null, 'Runner on third, two outs. A ground ball single goes into right field, and the second baseman runs out to be the cut. You''re the shortstop.', 'Where do you go?', array['Cover third base', 'Cover second base', 'Go out as a second cut', 'Back up the right fielder'], 1, 'With the second baseman out as the cut, second base is yours. Get to the bag and be ready for the throw so the batter stays at first.', 'Which bag did the second baseman just leave?', 1, '{"runners":["third"],"outs":2,"you":"SS","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.86 · Runner at 3B, 2 outs: covering second on a single to right'),
  ('defense-1-29', 'general', null, 'defense', 1, null, 'Runners on second and third, two outs. Ground ball to you at shortstop, and your teammates start calling out where the throw should go.', 'Who should NOT be calling out where to throw?', array['The catcher', 'The third baseman', 'You, the fielder making the play', 'The pitcher'], 2, 'Everyone else talks so the fielder can focus on the catch and the throw. Your job is to field it cleanly and listen to the call.', 'Whose eyes need to stay locked on the ball?', 1, '{"runners":["second","third"],"outs":2,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.5 · Communication: who stays quiet on a ground ball'),
  ('defense-1-30', 'general', null, 'defense', 1, null, 'Bases loaded, two outs. Before the pitch, your coach asks you to name your options on a ground ball. You''re the shortstop.', 'Which bases have a force play?', array['Only home plate', 'Only first and second', 'None, every runner has to be tagged', 'Every base, including home'], 3, 'With the bases loaded, every runner has someone behind her, so all of them must run on a ground ball. You can get a force by touching any base with the ball, home included.', 'Does every runner have someone behind her pushing her to the next base?', 1, '{"runners":["first","second","third"],"outs":2,"you":"SS"}'::jsonb, 'Defensive Playbook p.2 · Bases loaded, 2 outs: where the force plays are'),
  ('defense-2-01', 'general', null, 'defense', 2, null, 'Runner on second, one out. Ground ball to you at shortstop.', 'What''s your play?', array['Throw to third right away to get the lead runner', 'Look the runner back to second, then throw to first', 'Throw to first without looking at the runner', 'Run the ball over to second base'], 1, 'The runner at second isn''t forced, so a throw to third would need a tag. Freeze her with a look, then take the out at first; if she commits toward third, go after her instead.', 'Before you throw, what could the runner on second do behind your back?', 2, '{"runners":["second"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.23 · Runner at 2B, <2 outs: check the runner before throwing to 1B'),
  ('defense-2-02', 'general', null, 'defense', 2, null, 'Runner on second, nobody out. The batter bunts to the pitcher. The shortstop runs to cover third and the second baseman covers first. You''re the center fielder.', 'What''s your job?', array['Back up third base', 'Back up first base', 'Stay deep in center', 'Run in and cover second base'], 3, 'With the shortstop at third and the second baseman at first, no infielder is left for second. The center fielder runs in and takes the bag, while the left and right fielders back up third and first.', 'Count the infielders who just left. Who is left to cover the middle?', 2, '{"runners":["second"],"outs":0,"you":"CF","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.20 · Runner at 2B, <2 outs: who covers second on a bunt'),
  ('defense-2-03', 'general', null, 'defense', 2, null, 'Runner on first, one out. A hard grounder is hit to the first baseman right next to the bag. She steps on first for the out, then throws to you covering second. You''re the shortstop.', 'What do you have to do to get the runner from first?', array['Touch second base', 'Tag the runner', 'Throw back to first base', 'Nothing, she''s already out'], 1, 'Once the batter is out at first, the runner from first is no longer forced, so the force at second is gone. Now it''s a tag play, and the first baseman should tell you that.', 'Once the batter is out, is the runner from first still forced?', 2, '{"runners":["first"],"outs":1,"you":"SS","ball":{"at":"1B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.14 · Runner at 1B, <2 outs: force removed after the out at first'),
  ('defense-2-04', 'general', null, 'defense', 2, null, 'Runner on first, one out. A ground ball splits the right-center gap, and the second baseman races out to be the first cut. You''re the first baseman.', 'What''s your job?', array['Stay on first base', 'Cover second base', 'Set up as a second cut lined up toward home', 'Back up home plate'], 2, 'On a gap ball the runner from first may try to score, so the throw may need two relays. You become the second (double) cut in line with home, the catcher stays at the plate, and the pitcher backs her up.', 'On a long throw home, the relay may need more than one link.', 2, '{"runners":["first"],"outs":1,"you":"1B","ball":{"at":"RCF-gap","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.18 · Runner at 1B, <2 outs: double cut on a gap ball'),
  ('defense-2-05', 'general', null, 'defense', 2, null, 'Runner on third, one out. A slow ground ball is hit to you at first base, a few steps in front of the bag.', 'What''s the best play?', array['Move toward the batter-runner and tag her, keeping the runner at third in sight', 'Turn and run to first base to step on it', 'Throw home right away', 'Throw to second base'], 0, 'Going toward the batter to tag her keeps the runner at third in front of you. If you turn your back to run to the bag, she can break for home without you seeing it.', 'Where does your back face if you turn and run to the bag?', 2, '{"runners":["third"],"outs":1,"you":"1B","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.31 · Runner at 3B, <2 outs: slow roller to the first baseman'),
  ('defense-2-06', 'general', null, 'defense', 2, null, 'Runner on second, two outs. Routine ground ball to you at shortstop, and the runner is running on contact.', 'Where do you throw?', array['Third base to tag the runner', 'Home plate', 'First base', 'Second base'], 2, 'With two outs, the out at first ends the inning and the runner''s advance doesn''t matter. Don''t trade an easy out at first for a hard tag play at third.', 'With two outs, which out is the surest?', 2, '{"runners":["second"],"outs":2,"you":"SS","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.80 · Runner at 2B, 2 outs: take the out at first'),
  ('defense-2-07', 'general', null, 'defense', 2, null, 'Runner on third, two outs. The batter bunts toward you at third, and the runner breaks for home.', 'Where do you throw?', array['Home plate to stop the run', 'Second base', 'Hold the ball', 'First base'], 3, 'With two outs, getting the batter at first ends the inning, and the run can''t count when the third out is the batter retired before she reaches first. The catcher stays home and calls for the throw to first.', 'If the third out comes before the batter reaches first, does the run count?', 2, '{"runners":["third"],"outs":2,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.83 · Runner at 3B, 2 outs: bunt to the third baseman'),
  ('defense-2-08', 'general', null, 'defense', 2, null, 'Runner on second, one out. The runner wanders too far off the bag and gets caught between second and third. You''re the third baseman with the ball, and the shortstop is at second.', 'How should you and the shortstop line up so you can throw back and forth?', array['Both on the same side of the base path', 'Directly on the base line with the runner between you', 'On opposite sides of the base path', 'It doesn''t matter as long as you throw hard'], 0, 'If the runner is directly between you, a throw can hit her. Both fielders step to the same side of the base path so the ball has a clear lane.', 'You don''t want your throw to hit the runner.', 2, '{"runners":["second"],"outs":1,"you":"3B","arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · Runner at 2B, <2 outs: rundown throwing lane'),
  ('defense-2-09', 'general', null, 'defense', 2, null, 'Runner on first, two outs. Ground ball to you at second base, and the runner from first runs into you while you''re fielding it.', 'What''s the call?', array['Obstruction on you', 'No call, the base path belongs to the runner', 'No pitch, everyone goes back', 'Interference on the runner'], 3, 'A fielder making a play on a batted ball has the right to that spot. When a runner runs into her, that''s interference on the offense, so you don''t have to get out of her way to field the ball.', 'Who has the right of way when a fielder is playing the ball?', 2, '{"runners":["first"],"outs":2,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · Runner at 1B, 2 outs: interference on a ground ball to 2B'),
  ('defense-2-10', 'general', null, 'defense', 2, null, 'Runner on first, nobody out. A soft bunt dies on the grass and you have to charge hard to get it. You''re the third baseman.', 'Where do you throw?', array['Second base to get the lead runner', 'First base', 'Hold the ball', 'Home plate'], 1, 'On a slow bunt there''s usually no time to beat the lead runner to second, so take the sure out at first, where the second baseman is covering. On a hard bunt you''d look to get the lead runner instead.', 'After charging a slow bunt, do you have time for the lead runner?', 2, '{"runners":["first"],"outs":0,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.13 · Runner at 1B, <2 outs: slow bunt, take the sure out'),
  ('defense-2-11', 'general', null, 'defense', 2, null, 'Runner on third, two outs. Routine ground ball to you at second base, and the runner on third takes off for home on contact.', 'Where do you throw?', array['First base', 'Home to the catcher', 'Third base', 'Hold the ball'], 0, 'With two outs, the out at first ends the inning and the run doesn''t count if the batter is retired before she reaches the bag. The runner had to go on contact, so ignore her and take the sure out.', 'Does the run count if the third out is the batter at first?', 2, '{"runners":["third"],"outs":2,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.84 · Runner at 3B, 2 outs: runner breaks on a grounder to second'),
  ('defense-2-12', 'general', null, 'defense', 2, null, 'Runner on second, two outs. The batter bunts toward first. You charge out from behind the plate, but the first baseman calls you off and fields it.', 'Where do you go now?', array['Follow the play down the first-base line', 'Get back and cover home', 'Cover third base', 'Stay where you are'], 1, 'With a runner on second, home can''t sit empty. Once you''re called off, get back to the plate in case she tries to score while the throw goes to first.', 'Which base is the runner on second ultimately trying to reach?', 2, '{"runners":["second"],"outs":2,"you":"C","ball":{"at":"bunt-1B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.79 · Runner at 2B, 2 outs: catcher on a bunt to first'),
  ('defense-2-13', 'general', null, 'defense', 2, null, 'Runner on first, two outs. A ground ball splits the right-center gap, and the runner from first is flying around second. You''re the pitcher.', 'Where do you go?', array['Back up second base', 'Cover first base', 'Back up home plate', 'Stay on the mound'], 2, 'With two outs she was running on contact, and a gap ball gives her a real shot at scoring. Get behind the plate so a bad relay doesn''t cost you a run or extra bases.', 'On a ball in the gap, how far could the lead runner try to go?', 2, '{"runners":["first"],"outs":2,"you":"P","ball":{"at":"RCF-gap","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.78 · Runner at 1B, 2 outs: pitcher''s backup on a gap ball'),
  ('defense-2-14', 'general', null, 'defense', 2, null, 'Runner on first, nobody out. The batter bunts it firmly, and it rolls right to you in front of the plate. You''re the catcher.', 'Where do you throw?', array['First base', 'Third base', 'Hold it', 'Second base'], 3, 'A bunt that comes straight to you gives you time to get the lead runner, so throw to the shortstop covering second. If you have to chase the ball, take the sure out at first instead.', 'When the ball comes right to you, which runner can you go after?', 2, '{"runners":["first"],"outs":0,"you":"C","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.12 · Runner at 1B, <2 outs: bunt right at the catcher'),
  ('defense-2-15', 'general', null, 'defense', 2, null, 'Runner on third, one out. Fly ball to right field, and the runner on third tags up to score. You''re the first baseman.', 'What''s your job?', array['Line up as the cut between the right fielder and home', 'Stay on first base', 'Cover second base', 'Back up the catcher'], 0, 'The batter is out on the catch, so first base doesn''t need you. Get in line between the right fielder and the plate so the catcher can have you cut the throw or let it go through.', 'With the batter already out, where are you most useful?', 2, '{"runners":["third"],"outs":1,"you":"1B","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Defensive Playbook p.36 · Runner at 3B, <2 outs: first baseman on a fly to right'),
  ('defense-2-16', 'general', null, 'defense', 2, null, 'Runner on third, nobody out. The batter bunts toward the pitcher, and both corners charge. You''re the shortstop.', 'What''s your job?', array['Cover second base', 'Cover third and yell if the runner breaks or strays too far', 'Cover first base', 'Charge in behind the pitcher'], 1, 'With the third baseman charging, her bag is empty. Get there and be the eyes on that runner, so the fielder knows right away if she should throw home.', 'Once the third baseman leaves, who can see the runner on third best?', 2, '{"runners":["third"],"outs":0,"you":"SS","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.28 · Runner at 3B, <2 outs: shortstop on a bunt'),
  ('defense-2-17', 'general', null, 'defense', 2, null, 'Runners on first and third, one out. Ground ball back to you on the mound, and the runner on third stays close to her bag.', 'What''s your play?', array['Throw home right away', 'Throw to third', 'Look the runner back to third, then throw to first', 'Run at the runner on third'], 2, 'Freeze the runner with a look so she can''t score on your throw, then take the out at first. If she breaks for the plate, the throw goes to the catcher instead.', 'What keeps the runner on third from scoring while you throw?', 2, '{"runners":["first","third"],"outs":1,"you":"P","ball":{"at":"P","type":"ground"}}'::jsonb, 'Defensive Playbook p.56 · Runners at 1B & 3B, <2 outs: comebacker with the runner holding'),
  ('defense-2-18', 'general', null, 'defense', 2, null, 'Runners on second and third, nobody out. The batter bunts to the pitcher, the runners hold, and the pitcher throws to you covering first for the out. You''re the second baseman.', 'What should you do right after the catch?', array['Throw the ball back to the pitcher right away', 'Throw to second base', 'Roll the ball back to the mound', 'Check the lead runner before doing anything else'], 3, 'Runners love to take off when a fielder relaxes after an out. Look at the lead runner right away so she can''t sneak home or grab an extra base.', 'The out is made, but are the runners finished?', 2, '{"runners":["second","third"],"outs":0,"you":"2B","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.62 · Runners at 2B & 3B, <2 outs: after the out at first on a bunt'),
  ('defense-2-19', 'general', null, 'defense', 2, null, 'Runner on second, two outs. Single to left, and the runner is heading home. The shortstop goes out as the cut but drifts a few steps off the line between the left fielder and the plate. You''re the catcher.', 'What do you do?', array['Call her left or right until she''s in line', 'Leave home to go get the throw', 'Tell the left fielder to throw to second instead', 'Say nothing and let her find it'], 0, 'From the plate you can see the whole throwing line, so you steer the cut. Tell her which way to move so the throw comes straight through to you.', 'Who has the best view of the line from the ball to the plate?', 2, '{"runners":["second"],"outs":2,"you":"C","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.5 · Runner at 2B, 2 outs: lining up the cut from home'),
  ('defense-2-20', 'general', null, 'defense', 2, null, 'Runner on third, two outs. A ground ball rolls into the right-center gap and the batter rounds first, headed for second. You''re the shortstop covering second, and the throw hasn''t arrived yet.', 'What do you need to be careful about?', array['Standing in the base path so she has to go around you', 'Staying out of her path until you have the ball', 'Faking a tag to slow her down', 'Blocking the bag with your foot'], 1, 'A fielder without the ball can''t get in the runner''s way. If she has to go around you or stop, the umpire can call obstruction on you.', 'What''s the rule for a fielder who doesn''t have the ball yet?', 2, '{"runners":["third"],"outs":2,"you":"SS","ball":{"at":"RCF-gap","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.86 · Runner at 3B, 2 outs: covering second without the ball'),
  ('defense-2-21', 'general', null, 'defense', 2, null, 'Runners on first and second, two outs. The batter bunts it hard right back to you on the mound.', 'Where do you throw?', array['Third base', 'Second base', 'First base', 'Home plate'], 2, 'With two outs, any out ends the inning, so take the surest one: first base. With fewer than two outs, a hard bunt like this would go to third for the lead runner.', 'How many outs do you need to end the inning?', 2, '{"runners":["first","second"],"outs":2,"you":"P","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.87 · Runners at 1B & 2B, 2 outs: bunt back to the pitcher'),
  ('defense-2-22', 'general', null, 'defense', 2, null, 'Runners on first and second, two outs. You''re the second baseman, and a ground ball takes you toward the second-base bag as you field it.', 'What''s the best play?', array['Spin and throw to first', 'Throw to third', 'Run it to first yourself', 'Get the ball to the shortstop covering second'], 3, 'When the ball pulls you toward second, the force there is the shortest, easiest out. Feed it to the shortstop on the bag to end the inning.', 'Which out is closest to where your momentum is taking you?', 2, '{"runners":["first","second"],"outs":2,"you":"2B","ball":{"at":"2B","type":"ground"}}'::jsonb, 'Defensive Playbook p.88 · Runners at 1B & 2B, 2 outs: grounder that carries you toward second'),
  ('defense-2-23', 'general', null, 'defense', 2, null, 'Bases loaded, two outs. A ground ball splits the left-center gap and all three runners are moving. You''re the shortstop.', 'Where do you line up?', array['As the cut to home', 'As the cut to second', 'As the cut to third', 'Cover second base'], 0, 'With everyone running on contact, the play that matters is at the plate. Go out and line up between the outfielder and home; the first baseman sets up as a second cut behind you.', 'Which runner is the most dangerous on this hit?', 2, '{"runners":["first","second","third"],"outs":2,"you":"SS","ball":{"at":"LCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.95 · Bases loaded, 2 outs: shortstop on a ball in the left-center gap'),
  ('defense-2-24', 'general', null, 'defense', 2, null, 'Runners on first and third, two outs. The batter bunts to the pitcher. You''re the shortstop.', 'Where do you go?', array['Cover third base', 'Cover second base', 'Cover first base', 'Back up the pitcher'], 1, 'With no one on second, the third baseman returns to her own bag after charging. Your base is second, where the runner from first is headed.', 'Which base is empty, and which runner is heading there?', 2, '{"runners":["first","third"],"outs":2,"you":"SS","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.97 · Runners at 1B & 3B, 2 outs: shortstop on a bunt'),
  ('defense-2-25', 'general', null, 'defense', 2, null, 'Runners on first and third, two outs. Ground ball single into right field. The runner from third will score, and the runner from first is trying for third. You''re the second baseman.', 'What''s your job?', array['Fill in at first base', 'Cover second base', 'Go out and be the cut to third', 'Back up the right fielder'], 2, 'The runner you can still stop is the one going from first to third. Get out between the right fielder and third so her throw has a target.', 'Which runner can you still get, and where is she going?', 2, '{"runners":["first","third"],"outs":2,"you":"2B","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.100 · Runners at 1B & 3B, 2 outs: second baseman on a single to right'),
  ('defense-2-26', 'general', null, 'defense', 2, null, 'Runners on second and third, two outs. Single to right field. You''re the left fielder and you''ve run behind third to back it up, but both runners score and there''s no play at third.', 'What should you do next?', array['Stay behind third base', 'Run in to cover home', 'Jog back to left field', 'Shift over to back up second base'], 3, 'Backing up third comes first, but don''t stop there. If nothing happens at third, slide over behind second in case the batter tries to take it on a throw.', 'Once one base is settled, where could the batter-runner still go?', 2, '{"runners":["second","third"],"outs":2,"you":"LF","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.105 · Runners at 2B & 3B, 2 outs: left fielder''s backup after the play at third'),
  ('defense-2-27', 'general', null, 'defense', 2, null, 'Runners on second and third, two outs. Single to left, and you''re the shortstop going out as the cut to home.', 'What should decide how far out you go?', array['Your left fielder''s arm strength', 'Always stop at the edge of the infield dirt', 'How fast the runner is', 'Wherever the catcher points'], 0, 'A cut is there to shorten the throw. Know your outfielder''s arm: go farther out for a weaker arm and stay closer for a strong one.', 'The cut exists to make a long throw shorter for someone.', 2, '{"runners":["second","third"],"outs":2,"you":"SS","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · Cuts: how far out to go'),
  ('defense-2-28', 'general', null, 'defense', 2, null, 'Runner on first, two outs. A ground ball splits the right-center gap. You''re the second baseman.', 'What''s your job?', array['Cover second base', 'Go out as the first cut', 'Cover first base', 'Back up the center fielder'], 1, 'The ball is hit to your half of the outfield, so you go out as the lead cut toward third or home. The shortstop takes second and the first baseman sets up as a second cut to the plate.', 'Which infielder is closest to that gap?', 2, '{"runners":["first"],"outs":2,"you":"2B","ball":{"at":"RCF-gap","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.78 · Runner at 1B, 2 outs: second baseman on a ball in the right-center gap'),
  ('defense-2-29', 'general', null, 'defense', 2, null, 'Runners on first and third, two outs. The batter bunts a few feet in front of the plate. You charge from first, but the catcher calls you off and fields it.', 'What should you do?', array['Run back to cover first', 'Cover home plate', 'Call out where she should throw', 'Back up the catcher'], 2, 'When the catcher makes the play, the corners help her by calling the base, loud and early. The second baseman is already covering first.', 'When someone else fields it, what can you still give her?', 2, '{"runners":["first","third"],"outs":2,"you":"1B","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.3 · Runners at 1B & 3B, 2 outs: helping the catcher on a bunt'),
  ('defense-2-30', 'general', null, 'defense', 2, null, 'Runner on second, two outs. A ground ball single goes into left field, and the runner, who was running on contact, is rounding third. You''re the left fielder.', 'Where does your throw go?', array['Second base', 'Third base', 'First base', 'Through the cut to home'], 3, 'With two outs the runner was going on contact, so the play is at the plate. Hit your cut in line with home and let the catcher make the call.', 'Which runner can score, and where do you stop her?', 2, '{"runners":["second"],"outs":2,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.81 · Runner at 2B, 2 outs: single to left, throw home'),
  ('defense-3-01', 'general', null, 'defense', 3, null, 'Runners on first and second, nobody out. The batter bunts it hard right back to you on the mound.', 'Where do you throw?', array['First base for the sure out', 'Second base', 'Third base', 'Home plate'], 2, 'Both runners are forced, and a hard bunt gives you time to get the lead runner at third, where the shortstop is covering. On a slow bunt you''d take the out at first.', 'A hard bunt gets to you fast. Which forced runner is closest to scoring?', 3, '{"runners":["first","second"],"outs":0,"you":"P","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.37 · Runners at 1B & 2B, <2 outs: hard bunt to the pitcher'),
  ('defense-3-02', 'general', null, 'defense', 3, null, 'Bases loaded, one out, infield playing in. Ground ball to you at shortstop.', 'Where do you throw?', array['Home to the catcher', 'First base for the sure out', 'Third base', 'Hold it and look the runners back'], 0, 'With the infield in and less than two outs, the job is to stop the run. Every runner is forced, so the catcher just touches home, and then she can look to first or third for a second out.', 'With the infield in, which runner are you trying to stop?', 3, '{"runners":["first","second","third"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.49 · Bases loaded, <2 outs: ground ball with the infield in'),
  ('defense-3-03', 'general', null, 'defense', 3, null, 'Bases loaded, one out. A fly ball to left field is caught and the runner on third tags up. The throw could go home or to third.', 'Who decides where the throw goes?', array['The left fielder', 'The shortstop, as the cut', 'The third baseman', 'The catcher'], 3, 'The catcher is facing the whole play and leads the communication. She makes the call, home or third, based on the score and how fast the runner on third is.', 'Who can see the whole field and every runner from her spot?', 3, '{"runners":["first","second","third"],"outs":1,"you":"C","ball":{"at":"LF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.52 · Bases loaded, <2 outs: who calls the throw on a fly ball'),
  ('defense-3-04', 'general', null, 'defense', 3, null, 'Runners on first and third, one out, infield playing in. Ground ball to you at shortstop, and the runner on third breaks for home.', 'Where do you throw?', array['First base for the sure out', 'Home to the catcher', 'Third base, behind the runner', 'Hold the ball and run at her'], 1, 'Always check the runner at third first. If she''s going, throw home to cut down the run; if she holds, look her back and take the out at first.', 'Which runner is about to score?', 3, '{"runners":["first","third"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.57 · Runners at 1B & 3B, <2 outs: runner breaks home on a grounder'),
  ('defense-3-05', 'general', null, 'defense', 3, null, 'Runners on second and third, one out. The runner on third breaks with the pitch and the batter squares to bunt: it''s a squeeze. The bunt comes to you at third base.', 'Where do you throw?', array['First base for the sure out', 'Third base', 'Home to the catcher', 'Hold the ball'], 2, 'On a squeeze the runner from third is already going, so field it and throw home, where the catcher has stayed to take the throw. Only take the out at first when the runner isn''t trying to score.', 'On a squeeze, where is the runner from third already headed?', 3, '{"runners":["second","third"],"outs":1,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.64 · Runners at 2B & 3B, <2 outs: squeeze bunt to third'),
  ('defense-3-06', 'general', null, 'defense', 3, null, 'Runners on second and third, nobody out. The batter bunts a few feet in front of the plate, and the charging pitcher can get to it too. You''re the catcher.', 'What should you do?', array['Let the pitcher field it and stay home for a throw', 'Pounce on it yourself and throw to first', 'Run to cover third base', 'Back up first base'], 0, 'With a runner on third, home plate can''t be left empty. If another fielder can make the play, let her have it and stay at the plate so you can take a throw if the runner tries to score.', 'If you leave the plate, who protects it?', 3, '{"runners":["second","third"],"outs":0,"you":"C","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.63 · Runners at 2B & 3B, <2 outs: catcher on a bunt in front of the plate'),
  ('defense-3-07', 'general', null, 'defense', 3, null, 'Runners on first and second, two outs. A hard ground ball is hit right at you at third base, near the bag.', 'What''s your play?', array['Step on third base', 'Throw to first', 'Tag the runner coming from second', 'Throw to second'], 0, 'The runner from second is forced to third, so on a hard ball right at you, just step on the bag for the third out; no tag needed. If the ball pulls you forward or is hit slowly, throw to first instead.', 'With two outs, what''s the quickest out from where you''re standing?', 3, '{"runners":["first","second"],"outs":2,"you":"3B","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.89 · Runners at 1B & 2B, 2 outs: hard grounder at third'),
  ('defense-3-08', 'general', null, 'defense', 3, null, 'Bases loaded, two outs. The batter bunts it right in front of the plate and you pick it up. You''re the catcher.', 'Do you need to tag the runner coming home from third?', array['Yes, plays at the plate are always tag plays', 'No, just touch home plate with the ball', 'Only if she slides', 'Yes, the runner on third is never forced'], 1, 'With the bases loaded, every runner is forced, including the one coming home. Step on the plate with the ball for the third out; a throw to first works too.', 'With the bases loaded, is the runner from third forced?', 3, '{"runners":["first","second","third"],"outs":2,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.92 · Bases loaded, 2 outs: force at home on a bunt'),
  ('defense-3-09', 'general', null, 'defense', 3, null, 'Runners on first and third, two outs. A ground ball single goes into left field. You''re the pitcher.', 'Where do you go?', array['Back up home plate', 'Cover first base', 'Back up third base', 'Back up second base'], 2, 'The runner from third scores on a two-out single, so the left fielder throws through the shortstop cut to third to stop the runner coming from first. The pitcher backs up third in case that throw gets away.', 'Where will the left fielder''s throw go if the runner from first tries for third?', 3, '{"runners":["first","third"],"outs":2,"you":"P","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Defensive Playbook p.99 · Runners at 1B & 3B, 2 outs: pitcher''s backup on a single to left'),
  ('defense-3-10', 'general', null, 'defense', 3, null, 'Runners on second and third, two outs. A ground ball gets past you into right field for a single. You''re the second baseman.', 'Once the ball is by you, where do you go?', array['Cover second base', 'Become the cut to home', 'Back up the right fielder', 'Fill in at first base'], 3, 'The first baseman usually becomes the cut to home on this play, which leaves first open. You fill in at first so there''s still a play on the batter-runner; the shortstop has second and the center fielder backs up right.', 'Which bag did the first baseman leave behind?', 3, '{"runners":["second","third"],"outs":2,"you":"2B","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.105 · Runners at 2B & 3B, 2 outs: filling in at first on a single to right'),
  ('defense-3-11', 'general', null, 'defense', 3, null, 'Runner on second, one out. Fly ball to center field, and the runner tags to go to third. You''re the first baseman.', 'Where do you go?', array['Back up second base', 'Stay on first base', 'Go out as the cut to third', 'Cover home plate'], 0, 'The batter is out on the catch, so nothing is happening at first. Get behind second in case a throw there gets loose while the play goes to third.', 'The batter''s already out. Which bag could still see a stray throw?', 3, '{"runners":["second"],"outs":1,"you":"1B","ball":{"at":"CF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.27 · Runner at 2B, <2 outs: first baseman on a fly to center'),
  ('defense-3-12', 'general', null, 'defense', 3, null, 'Runners on first and second, one out. A hard ground ball single comes right at you in left field, and you get to it fast.', 'Where do you throw?', array['Through the cut to home', 'Third base', 'Second base', 'First base'], 1, 'A hard ball right at you is in your glove before the lead runner can think about scoring, so throw to third and stop her there. On a slower ball you have to charge, the throw would go through the cut to home.', 'How fast did the ball get to you, and how far can the lead runner get?', 3, '{"runners":["first","second"],"outs":1,"you":"LF","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Defensive Playbook p.41 · Runners at 1B & 2B, <2 outs: hard single right at the left fielder'),
  ('defense-3-13', 'general', null, 'defense', 3, null, 'Runners on first and second, one out. A hard ground ball is hit right at you at shortstop.', 'Where do you throw?', array['First base', 'Home plate', 'Third base', 'Run at the runner from second'], 2, 'A hard-hit ball gives you time to get the lead runner, and she''s forced. Throw to the third baseman for the force on the runner from second.', 'Which forced runner is closest to scoring?', 3, '{"runners":["first","second"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.40 · Runners at 1B & 2B, <2 outs: hard grounder to short'),
  ('defense-3-14', 'general', null, 'defense', 3, null, 'Runners on first and second, nobody out. A slow, chopping ground ball comes toward you on the mound, and you have to charge hard to get it.', 'Where do you throw?', array['Third base', 'Second base', 'Home plate', 'First base'], 3, 'A slow ball eats up the time you''d need to beat the lead runner. Take the sure out at first, and save the throw to third for a ball hit hard back to you.', 'Did the slow ball leave you enough time for the lead runner?', 3, '{"runners":["first","second"],"outs":0,"you":"P","ball":{"at":"P","type":"ground"}}'::jsonb, 'Defensive Playbook p.39 · Runners at 1B & 2B, <2 outs: slow roller to the pitcher'),
  ('defense-3-15', 'general', null, 'defense', 3, null, 'Bases loaded, one out, infield in. Ground ball to the third baseman, who fields it and throws home. You''re the shortstop.', 'What''s your job on this play?', array['Back her up, then cover third for a possible throw from the catcher', 'Cover second base', 'Run toward home to back up the catcher', 'Cover first base'], 0, 'Start by backing up the ground ball. Once the third baseman throws home, her bag is empty, so get there: the catcher may come back to third for a second out.', 'After the third baseman throws, which bag has nobody on it?', 3, '{"runners":["first","second","third"],"outs":1,"you":"SS","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.49 · Bases loaded, <2 outs: shortstop on a grounder to third'),
  ('defense-3-16', 'general', null, 'defense', 3, null, 'Bases loaded, one out, infield in. Ground ball to you at first base, a step off the bag.', 'Where''s your play?', array['Step on first', 'Throw home to the catcher', 'Throw to second', 'Throw to third'], 1, 'Stepping on first gets an out but lets the run score. With fewer than two outs, cut the run down at the plate; it''s a force, so the catcher only has to touch home.', 'Which out also keeps a run off the board?', 3, '{"runners":["first","second","third"],"outs":1,"you":"1B","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.48 · Bases loaded, <2 outs: grounder to the first baseman'),
  ('defense-3-17', 'general', null, 'defense', 3, null, 'Bases loaded, nobody out. Comebacker to the pitcher, who throws to you at home. You catch it with your foot on the plate for the force.', 'What should you do next?', array['Hold the ball and call time', 'Tag the runner who just slid in', 'Look for a second out at first or third', 'Chase the runner back toward third'], 2, 'The force at home is the first out, not the end of the play. Set your feet and look to throw to first or third for a second one.', 'One out is good. Is there another one available?', 3, '{"runners":["first","second","third"],"outs":0,"you":"C","ball":{"at":"P","type":"ground"}}'::jsonb, 'Defensive Playbook p.47 · Bases loaded, <2 outs: catcher after the force at home'),
  ('defense-3-18', 'general', null, 'defense', 3, null, 'Runners on first and third, one out. The shortstop fields a ground ball up the middle near second base, and the runner on third holds. You''re the second baseman covering second.', 'What''s your job?', array['Let her make the throw to first', 'Run to back up first base', 'Cover third base', 'Call for the ball at second, then throw to first'], 3, 'When the ball takes the shortstop toward the bag, the play at second is right in front of her. Demand the ball, take the force, and finish with a throw to first.', 'When the ball pulls her toward your bag, what''s the shortest throw?', 3, '{"runners":["first","third"],"outs":1,"you":"2B","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.57 · Runners at 1B & 3B, <2 outs: ball up the middle to the shortstop'),
  ('defense-3-19', 'general', null, 'defense', 3, null, 'Runners on first and third, nobody out. The batter bunts to the pitcher. You''re the center fielder.', 'What''s your job?', array['Back up second base', 'Run in and cover second base', 'Back up third base', 'Stay in center'], 0, 'With runners on first and third, the shortstop covers second on a bunt, so the bag is taken. Your job is to get behind it in case a throw there gets away.', 'Someone in the infield already has the bag. What''s left for you?', 3, '{"runners":["first","third"],"outs":0,"you":"CF","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.54 · Runners at 1B & 3B, <2 outs: center fielder on a bunt'),
  ('defense-3-20', 'general', null, 'defense', 3, null, 'Runners on first and third, one out. Bunt in front of the plate that only you can reach. As you pick it up, you see the runner on third has wandered way off her bag.', 'What should you do?', array['Throw to first like always', 'Go after the runner off third', 'Throw to second', 'Hold the ball and step on home'], 1, 'Normally you''d take the out at first, but a lead runner caught far off third is the bigger prize. Go after her before she can get back.', 'Which runner is in the most trouble right now?', 3, '{"runners":["first","third"],"outs":1,"you":"C","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.54 · Runners at 1B & 3B, <2 outs: catcher on a bunt with the runner off third'),
  ('defense-3-21', 'general', null, 'defense', 3, null, 'Runners on second and third, nobody out. The batter bunts a few feet in front of the plate, and only the catcher can get to it. You charged in from third, but she calls you off.', 'Where do you go?', array['Back to third base', 'Cover first base', 'Cover home plate', 'Back up the catcher'], 2, 'The catcher left the plate to field the ball, so home is empty with a runner on third. You''re the closest player, so take the plate; the shortstop is already covering third.', 'Which base is empty and also the most important to protect?', 3, '{"runners":["second","third"],"outs":0,"you":"3B","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.63 · Runners at 2B & 3B, <2 outs: third baseman when the catcher fields a bunt'),
  ('defense-3-22', 'general', null, 'defense', 3, null, 'Runners on second and third, nobody out. The batter bunts it hard right to you at first, and both runners stay put. The batter-runner is coming straight up the line at you.', 'What''s your best play?', array['Throw to the second baseman covering first', 'Throw home', 'Throw to third', 'Tag the batter-runner yourself'], 3, 'A hard bunt reaches you quickly, so the batter is still close. Tag her yourself; you stay facing the runners on base instead of turning away to throw.', 'Is the batter-runner close enough that you don''t need to throw?', 3, '{"runners":["second","third"],"outs":0,"you":"1B","ball":{"at":"bunt-1B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.63 · Runners at 2B & 3B, <2 outs: hard bunt to first'),
  ('defense-3-23', 'general', null, 'defense', 3, null, 'Runners on second and third, one out. Ground ball to you at second base, and the runner on third breaks for home as you field it.', 'Where do you throw?', array['Home to the catcher', 'First base', 'Third base', 'Second base'], 0, 'With fewer than two outs, stopping the run matters more than the out at first. She has committed, so get the ball to the catcher and save the run.', 'Which runner has already committed, and where is she going?', 3, '{"runners":["second","third"],"outs":1,"you":"2B","ball":{"at":"2B","type":"ground"}}'::jsonb, 'Defensive Playbook p.65 · Runners at 2B & 3B, <2 outs: runner breaks on a grounder to second'),
  ('defense-3-24', 'general', null, 'defense', 3, null, 'Runners on first and second, two outs. A ground ball takes you to your right, deep in the hole toward third. You''re the shortstop.', 'Where''s your best play?', array['Long throw to first', 'Third base', 'Second base', 'Home plate'], 1, 'Moving toward third, the force there is your shortest throw, and any out ends the inning. Don''t make the long throw across the diamond when an easy force is right in front of you.', 'Which bag is the shortest throw from where you fielded it?', 3, '{"runners":["first","second"],"outs":2,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.89 · Runners at 1B & 2B, 2 outs: grounder in the hole at short'),
  ('defense-3-25', 'general', null, 'defense', 3, null, 'Runners on first and second, two outs. Ground ball single to left field, and the runner from second is heading home. You''re the first baseman.', 'What''s your job?', array['Go out as the cut to home', 'Back up home plate', 'Cover first base and help call where the throw goes', 'Cover second base'], 2, 'On a ball to left, the cut to home comes from the left side of the infield, not from you. Stay at first, ready if the batter rounds too far, and help the outfield with your voice.', 'Who is closer to the line between left field and home?', 3, '{"runners":["first","second"],"outs":2,"you":"1B","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.89 · Runners at 1B & 2B, 2 outs: first baseman on a single to left'),
  ('defense-3-26', 'general', null, 'defense', 3, null, 'Bases loaded, two outs. Ground ball to you at first base, a step from the bag.', 'What''s your play?', array['Throw home', 'Throw to second', 'Throw to third', 'Step on first base'], 3, 'With two outs, the closest out ends the inning and no runs count. Take the bag yourself; with fewer than two outs, you''d be throwing home instead.', 'How many outs do you need, and which one is closest?', 3, '{"runners":["first","second","third"],"outs":2,"you":"1B","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.93 · Bases loaded, 2 outs: grounder to the first baseman'),
  ('defense-3-27', 'general', null, 'defense', 3, null, 'Bases loaded, two outs. Ground ball single up the middle into center, and the runner from second is coming around third. You''re the first baseman.', 'What''s your job?', array['Line up as the cut between center field and home', 'Stay on first base', 'Cover second base', 'Back up the catcher'], 0, 'On a ball to center with a run on the line, you''re the cut to the plate. Line up on the throw from the center fielder to home so the catcher can have you cut it or let it through.', 'With the throw headed to the plate, which infielder has an open path to help?', 3, '{"runners":["first","second","third"],"outs":2,"you":"1B","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.95 · Bases loaded, 2 outs: first baseman on a single to center'),
  ('defense-3-28', 'general', null, 'defense', 3, null, 'Runners on first and third, two outs. The batter bunts toward the mound. You charge in from third, but the pitcher fields it.', 'Where do you go?', array['Keep coming to back up the pitcher', 'Get back to third base', 'Cover home plate', 'Cover second base'], 1, 'With runners on first and third, the shortstop goes to second on a bunt, not third. Nobody else is heading to your bag, so get back there once the pitcher has the ball.', 'Check where the shortstop goes with runners on first and third.', 3, '{"runners":["first","third"],"outs":2,"you":"3B","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.97 · Runners at 1B & 3B, 2 outs: third baseman after charging a bunt'),
  ('defense-3-29', 'general', null, 'defense', 3, null, 'Runners on second and third, two outs. Ground ball into the left-center gap. You run to back up home, but both runners score easily and there''s no play at the plate. You''re the pitcher.', 'What should you do now?', array['Stay behind home plate', 'Go back to the mound', 'Move over to back up third base', 'Cover first base'], 2, 'Backing up home is your first job, but once there''s no play there, the next throw is likely headed to third as the batter tries to stretch the hit. Slide over behind third.', 'With the runs in, where will the batter-runner try to go?', 3, '{"runners":["second","third"],"outs":2,"you":"P","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.105 · Runners at 2B & 3B, 2 outs: pitcher''s backup when there''s no play at home'),
  ('defense-3-30', 'general', null, 'defense', 3, null, 'Runners on second and third, two outs. Single to left field. On this play your team uses the third baseman as the cut to home. You''re the shortstop.', 'Where do you go?', array['Go out as a second cut', 'Cover second base', 'Back up home', 'Fill in at third base'], 3, 'If the third baseman becomes the cut, her bag is left open. Slide over and take third so nobody gets that base for free.', 'When a player leaves her base to be the cut, who takes her spot?', 3, '{"runners":["second","third"],"outs":2,"you":"SS","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.104 · Runners at 2B & 3B, 2 outs: when the third baseman is the cut'),
  ('baserunning-1-01', 'general', null, 'baserunning', 1, null, 'Nobody on, no outs. You hit a routine ground ball to the shortstop.', 'How do you run it out?', array['Sprint hard straight through first base', 'Round first and look for second in case of a bad throw', 'Slide headfirst into first to beat the throw', 'Ease up and stop right on the bag so you don''t overrun it'], 0, 'On an infield grounder the only play is at first, so run through the bag at full speed and break down past it. Stopping on the base or sliding into it only slows you down.', 'Where is the only play the defense can make on this ball?', 1, '{"runners":[],"outs":0,"you":"batter","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.3 · No runners, <2 outs: ground ball to SS'),
  ('baserunning-1-02', 'general', null, 'baserunning', 1, null, 'Two outs, nobody on. You hit a clean single on the ground through the left side into left field.', 'What do you do at first base?', array['Run straight through first, like on an infield grounder', 'Make a hard turn at first and put pressure on the left fielder', 'Stop on first so you don''t take chances with two outs', 'Head straight for second no matter what'], 1, 'A hard, aggressive turn makes the left fielder hurry. If she bobbles it or lobs it back in, you''re already in position to take second; running straight through gives that chance away.', 'What could a bobble or a lazy throw back to the infield give you?', 1, '{"runners":[],"outs":2,"you":"batter","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Baserunning Playbook p.16 · No runners, 2 outs: single to LF'),
  ('baserunning-1-03', 'general', null, 'baserunning', 1, null, 'One out, you''re on first. The batter hits a ground ball to the third baseman.', 'What do you do?', array['Hold at first until you see where the throw goes', 'Run halfway to second and stop to avoid a double play', 'Run hard to second and slide', 'Run to second standing up and round the bag toward third'], 2, 'You''re forced to move on any ground ball, so get to second fast. Slide in, because the defense may go for the lead out at second.', 'Does the batter running behind you leave you a choice?', 1, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: ground ball to the infield'),
  ('baserunning-1-04', 'general', null, 'baserunning', 1, null, 'No outs, you''re on second and the other bases are empty. The batter hits a ground ball to the shortstop.', 'What''s your move?', array['Run straight to third as soon as the ball is hit', 'Stay glued to second no matter where the throw goes', 'Head for third only after the batter is called safe at first', 'Get a good jump, then take third once she throws to first'], 3, 'A ball hit in front of you on the left side puts the shortstop in easy throwing range of third. Get off the bag ready to go, let her commit her throw to first, then take third. On a grounder to the right side you''d simply run.', 'Is the ball in front of you or behind you?', 1, '{"runners":["second"],"outs":0,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.5 · Runner at 2B, <2 outs: ground ball to SS'),
  ('baserunning-1-05', 'general', null, 'baserunning', 1, null, 'One out, you''re on third. The batter hits a fly ball to medium-deep center field.', 'What do you do?', array['Go halfway down the line and wait to see if it''s caught', 'Run home as soon as the ball is hit', 'Tag up and sprint home the moment it''s caught', 'Stay on third so you don''t risk the run with one out'], 2, 'With fewer than two outs, a fly ball to the outfield is a tag-up. Get on the bag, leave on the catch, and score; the exception is a short fly that pulls the fielder way in.', 'When a fly is caught, when are you allowed to leave third?', 1, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"CF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: fly ball to CF'),
  ('baserunning-1-06', 'general', null, 'baserunning', 1, null, 'Two outs, you''re on third. The batter pops the ball up to the shortstop.', 'What do you do?', array['Run straight home as soon as it''s hit', 'Stay close to third in case she drops it', 'Tag up and go home on the catch', 'Go halfway home and read the catch'], 0, 'With two outs, a catch ends the inning, so there''s nothing to protect by staying. Run on contact; if she drops it, you''re already most of the way home.', 'With two outs, what does a catch do to the inning?', 1, '{"runners":["third"],"outs":2,"you":"runner-third","ball":{"at":"SS","type":"popup"}}'::jsonb, 'Baserunning Playbook p.20 · Runner at 3B, 2 outs: pop-up to the infield'),
  ('baserunning-1-07', 'general', null, 'baserunning', 1, null, 'Two outs, you''re on first. The batter hits a fly ball to center field.', 'What do you do?', array['Go halfway to second and wait to see if it''s caught', 'Tag up at first and go on the catch', 'Stay on first until the ball is caught or drops', 'Run on contact, round second, and be ready to take third if it''s dropped'], 3, 'With two outs, a catch ends the inning, so you run on contact. Rounding second puts you in position to take third if the center fielder drops it; going halfway is the play with fewer than two outs.', 'With two outs, does it matter where you are if she catches it?', 1, '{"runners":["first"],"outs":2,"you":"runner-first","ball":{"at":"CF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.17 · Runner at 1B, 2 outs: fly ball to CF'),
  ('baserunning-1-08', 'general', null, 'baserunning', 1, null, 'One out, you''re on first. The batter hits a ground ball to the shortstop, who throws to the second baseman covering second.', 'What does the second baseman need to do to get you out?', array['Tag you with the ball before you reach the bag', 'Have the ball and touch second before you get there', 'Tag you and touch the bag at the same time', 'Catch the ball while standing anywhere near second'], 1, 'You''re forced to run because the batter is coming behind you, so it''s a force play: the fielder only needs the ball and a foot on the base before you arrive. A tag is needed when a runner isn''t forced.', 'When the ball is hit on the ground, are you allowed to stay on first?', 1, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"SS","to":"second","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.2 · Rules: force out vs. tag out'),
  ('baserunning-1-09', 'general', null, 'baserunning', 1, null, 'No outs, you''re on first. You want a good lead without leaving early.', 'When do you start moving off the bag?', array['As soon as the pitcher steps onto the rubber', 'When the pitcher begins her windup', 'When her arm hits the peak of her pitching motion, so your foot comes off the base on the release', 'After the ball crosses home plate'], 2, 'Start moving at the peak of her motion so you come off the base right as she lets the ball go. Too early and you can be called for leaving early; too late and your lead is wasted.', 'Where is the pitcher''s arm a split second before she lets go?', 1, '{"runners":["first"],"outs":0,"you":"runner-first"}'::jsonb, 'Baserunning Playbook p.30 · Leads: timing off the bag'),
  ('baserunning-1-10', 'general', null, 'baserunning', 1, null, 'No outs, you''re on first. The batter rips a line drive right at the shortstop.', 'What''s your first reaction?', array['Freeze, then react once you see if it''s caught or gets through', 'Run hard to second because you''re forced on a batted ball', 'Go halfway to second, like on a fly ball to the outfield', 'Take a big lead to try to draw a throw'], 0, 'A line drive is either caught or past the infielder in a split second. If you''re already running and it''s caught, you get doubled off, so freeze first and react to what happens.', 'How long does a line drive take to be caught or get through?', 1, '{"runners":["first"],"outs":0,"you":"runner-first","ball":{"at":"SS","type":"line"}}'::jsonb, 'Baserunning Playbook p.29 · Line drive in the infield: freeze'),
  ('baserunning-1-11', 'general', null, 'baserunning', 1, null, 'Nobody on, one out. You hit a ground-ball single through the right side into right field.', 'How do you run to first?', array['Make a big, aggressive turn to pressure the right fielder', 'Run hard straight through first base', 'Slide into first to be safe', 'Take a wide turn and head for second'], 1, 'The right fielder plays close to first and can throw behind a runner who turns too far. On a single to right, run hard through the bag and don''t give her that chance.', 'Which outfielder is closest to first base?', 1, '{"runners":[],"outs":1,"you":"batter","ball":{"at":"RF","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.3 · No runners, <2 outs: single to RF'),
  ('baserunning-1-12', 'general', null, 'baserunning', 1, null, 'Nobody on, no outs. You hit a high fly ball to medium center field.', 'How do you run it out?', array['Jog to first, since it''s probably going to be caught', 'Run through first and walk back to the bag', 'Stop halfway to first and watch', 'Round first hard so you''re ready to take second if it''s dropped'], 3, 'Never assume the catch. A hard turn at first means a dropped fly turns into a double instead of a single.', 'If the fielder drops it, where do you want to already be?', 1, '{"runners":[],"outs":0,"you":"batter","ball":{"at":"CF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.3 · No runners, <2 outs: fly ball to CF'),
  ('baserunning-1-13', 'general', null, 'baserunning', 1, null, 'No outs, you''re on first. The batter rips a ground ball through the right side that rolls all the way into the right-center gap.', 'What''s your plan?', array['Stop at second and wait to see where the ball is', 'Round second and be ready to keep going to third', 'Go halfway to second until the ball is fielded', 'Run to second and slide'], 1, 'A ball in the gap gives the outfielders a long chase, so think two bases from the start. Make a good turn at second and be ready to keep running to third.', 'How long will it take an outfielder to run down a ball in the gap?', 1, '{"runners":["first"],"outs":0,"you":"runner-first","ball":{"at":"RCF-gap","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: gap hit to RCF'),
  ('baserunning-1-14', 'general', null, 'baserunning', 1, null, 'One out, you''re on first. The batter hits a fly ball to medium left field.', 'What do you do?', array['Go about halfway to second, ready to go back or keep running', 'Tag up and run to second on the catch', 'Run hard to second on contact', 'Stay on first base'], 0, 'With fewer than two outs, a catch sends you back to first and a drop means you need second. Getting a third to halfway down the line lets you do either one.', 'If it''s caught you need first; if it drops you need second.', 1, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"LF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: fly ball to LF'),
  ('baserunning-1-15', 'general', null, 'baserunning', 1, null, 'One out, you''re on second and the other bases are empty. The batter hits a ground ball to the second baseman.', 'What''s your move?', array['Hold at second until she throws to first', 'Freeze, then go back to second', 'Run straight to third', 'Wait to see if the batter beats the throw'], 2, 'A ball to the right side is behind you, and the second baseman''s natural throw is to first, not third. Go right away; the wait-for-the-throw read is for grounders to short or third.', 'How hard is it for the second baseman to throw you out at third?', 1, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"2B","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.5 · Runner at 2B, <2 outs: ground ball to the right side'),
  ('baserunning-1-16', 'general', null, 'baserunning', 1, null, 'No outs, you''re on third and the other bases are empty. The batter pops the ball up to the second baseman.', 'What do you do?', array['Tag up and race home on the catch', 'Run home as soon as it''s hit', 'Stay close to third, and go only if she drops it and it rolls away', 'Go halfway home and wait'], 2, 'An infielder catches a pop-up close to the plate with a short throw home, so tagging up won''t score you. Stay near the bag and only break if the ball hits the ground and rolls away.', 'How short is the throw home from the infield?', 1, '{"runners":["third"],"outs":0,"you":"runner-third","ball":{"at":"2B","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: pop-up to the infield'),
  ('baserunning-1-17', 'general', null, 'baserunning', 1, null, 'Two outs, you''re on second. The batter hits a fly ball to left field.', 'What do you do?', array['Tag up at second and go on the catch', 'Go halfway to third and read it', 'Stay on second until it comes down', 'Run on contact, round third, and be ready to score if it''s dropped'], 3, 'With two outs a catch ends the inning, so there''s nothing to tag up for. Run when it''s hit, and if she drops it you''re already around third and headed home.', 'With two outs, what are you protecting by staying close to second?', 1, '{"runners":["second"],"outs":2,"you":"runner-second","ball":{"at":"LF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.19 · Runner at 2B, 2 outs: fly ball to LF'),
  ('baserunning-1-18', 'general', null, 'baserunning', 1, null, 'One out, runners on first and second. You''re on second, and the batter hits a ground ball to the shortstop.', 'What do you do?', array['Get a jump, then wait for her throw to first before going', 'Run hard to third and slide', 'Hold at second because the ball is in front of you', 'Jog to third, since the play will be at first'], 1, 'The runner behind you has to take second, so you''re forced and can''t wait on the throw. Run hard and slide, because the defense may try to get the lead runner at third.', 'With a teammate on first, can you stay at second?', 1, '{"runners":["first","second"],"outs":1,"you":"runner-second","ball":{"at":"SS","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.8 · Runners at 1B & 2B, <2 outs: ground ball (runner at 2B)'),
  ('baserunning-1-19', 'general', null, 'baserunning', 1, null, 'One out, you''re on first and you steal second. The catcher throws to the shortstop covering the bag.', 'What does the shortstop have to do to get you out?', array['Catch the ball with a foot on second before you arrive', 'Tag you with the ball before you touch the base', 'Beat you to the bag, with or without the ball', 'Touch the bag and then throw to first'], 1, 'Nobody is pushing you off first on a steal, so you aren''t forced. That makes it a tag play: the ball has to touch you before you touch second.', 'On a steal, is anyone behind you forcing you to run?', 1, '{"runners":["first"],"outs":1,"you":"runner-first","arrows":[{"from":"first","to":"second","kind":"steal"},{"from":"C","to":"second","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.2 · Rules: a steal is a tag play'),
  ('baserunning-1-20', 'general', null, 'baserunning', 1, null, 'One out, runners on first and third. You''re on third, and the batter hits a ground ball to the second baseman.', 'Are you forced to run home?', array['Yes, every runner is forced on a ground ball', 'Yes, because the batter is running to first', 'Only if the runner from first beats the throw to second', 'No, second base was open, so nobody needs third'], 3, 'A runner is forced only when every base behind her is filled. Second was empty, so the runner from first moves up there and you''re free; any play on you at home would need a tag.', 'Is there a runner directly behind you who needs your base?', 1, '{"runners":["first","third"],"outs":1,"you":"runner-third","ball":{"at":"2B","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.2 · Rules: who is forced at 1B & 3B'),
  ('baserunning-1-21', 'general', null, 'baserunning', 1, null, 'No outs, you''re on first and the pitcher is about to deliver.', 'How big a lead do you take?', array['About three hard steps, close enough that one step plus a dive gets you back', 'One small step, so you can never be picked off', 'As far as you can until the catcher looks at you', 'Halfway to second on every pitch'], 0, 'Three explosive steps gets you a real jump without drifting too far. If the catcher throws over, one step and a dive should get you back.', 'Your lead has to help you, but you also have to get back if the catcher throws.', 1, '{"runners":["first"],"outs":0,"you":"runner-first","arrows":[]}'::jsonb, 'Baserunning Playbook p.30 · Leads: first base'),
  ('baserunning-1-22', 'general', null, 'baserunning', 1, null, 'One out, you''re on second with first and third empty.', 'How big a lead do you take?', array['Just one step, so the catcher can''t pick you off', 'No lead, since you''re already in scoring position', 'Four or five hard steps', 'As far as you can get toward third'], 2, 'You can take more ground at second than at first: four or five strong steps. That head start is what helps you score on a base hit.', 'How far does the catcher have to throw to reach second compared with first?', 1, '{"runners":["second"],"outs":1,"you":"runner-second","arrows":[]}'::jsonb, 'Baserunning Playbook p.30 · Leads: second base'),
  ('baserunning-1-23', 'general', null, 'baserunning', 1, null, 'One out, you''re on first. You took a good lead, the batter took the pitch, and the catcher has the ball.', 'What now?', array['Stay where you are until the pitcher has the ball back', 'Walk back slowly so you don''t look nervous', 'Take a couple more steps to tease a throw', 'Get back to the bag quickly and with purpose'], 3, 'Hanging around off the base after the pitch is how runners get picked off. Go off hard and come back hard, every pitch.', 'Who has the ball now, and how far are you from your base?', 1, '{"runners":["first"],"outs":1,"you":"runner-first","arrows":[]}'::jsonb, 'Baserunning Playbook p.30 · Leads: getting back after the pitch'),
  ('baserunning-1-24', 'general', null, 'baserunning', 1, null, 'No outs, you''re on second, getting ready to take your lead.', 'What''s the best way to start your lead?', array['Shuffle off slowly so you don''t give anything away', 'Push off the base and drive your knee for an explosive first step', 'Start with your foot a step in front of the bag', 'Lean toward third and wait for the ball to be hit'], 1, 'Use the bag like a starting block: push off it and drive your knee so your first step is explosive. Starting with your foot already off the base can get you called out for leaving early.', 'What can the base itself do for your first step?', 1, '{"runners":["second"],"outs":0,"you":"runner-second","arrows":[]}'::jsonb, 'Baserunning Playbook p.30 · Leads: the first step'),
  ('baserunning-1-25', 'general', null, 'baserunning', 1, null, 'One out, you''re on first. The batter pops up to the second baseman, who drifts toward first to make the catch.', 'What do you do?', array['Stay on first base', 'Go halfway to second', 'Run to second on contact', 'Take a big lead to bait a throw'], 0, 'On a pop-up to the right side the fielder is right next to first, and a quick toss can double you off if you''ve wandered. Stay on the bag.', 'How far is the fielder from first base?', 1, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"2B","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: pop-up on the right side'),
  ('baserunning-1-26', 'general', null, 'baserunning', 1, null, 'Nobody on, no outs. You hit a soft blooper into shallow center field, and the center fielder is charging hard.', 'How do you run it?', array['Run straight through first', 'Head straight for second on contact', 'Round first, and go for second only if the ball squirts away after a drop', 'Stop on first and watch'], 2, 'Turn at first so you''re ready, but a drop that stays at her feet isn''t a free base. Go for second only if the ball gets past her.', 'What has to happen before second base is really open?', 1, '{"runners":[],"outs":0,"you":"batter","ball":{"at":"blooper-CF","type":"blooper"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.3 · No runners, <2 outs: blooper to CF'),
  ('baserunning-1-27', 'general', null, 'baserunning', 1, null, 'One out, you''re on second, and the pitcher is about to take her sign.', 'What should you check before the pitch?', array['How deep the outfielders are playing', 'Who''s warming up in the bullpen', 'How fast the pitcher is throwing today', 'What the pitch count is'], 0, 'Outfield depth tells you how hard to push on a hit and when a fly ball is worth tagging on. A soft hit in front of a deep outfield, for example, is a chance to run.', 'What decides whether a shallow hit can be caught?', 1, '{"runners":["second"],"outs":1,"you":"runner-second","arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Baserunning tips: checking the outfield'),
  ('baserunning-1-28', 'general', null, 'baserunning', 1, null, 'Two outs, you''re on third. The batter hits a ground ball to the second baseman.', 'What do you do?', array['Freeze until she throws to first', 'Run home as soon as the ball is hit', 'Go halfway and read the throw', 'Stay on third so you don''t make the third out'], 1, 'With two outs the defense will throw to first for the last out. If they throw the batter out, your run wouldn''t count anyway, and if they don''t, you''ve scored, so go on contact.', 'With two outs, what does holding at third save you?', 1, '{"runners":["third"],"outs":2,"you":"runner-third","ball":{"at":"2B","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.20 · Runner at 3B, 2 outs: ground ball to the infield'),
  ('baserunning-1-29', 'general', null, 'baserunning', 1, null, 'One out, runners on first and second. You''re the runner on first.', 'In baserunning terms, which runner are you?', array['The lead runner', 'The courtesy runner', 'The pinch runner', 'The trail runner'], 3, 'With a teammate ahead of you, you''re the trail runner and she''s the lead runner. Trail runners have to watch what the runner ahead does before taking a base.', 'Is there a teammate on a base ahead of you?', 1, '{"runners":["first","second"],"outs":1,"you":"runner-first","arrows":[]}'::jsonb, 'Baserunning Playbook p.2 · Vocabulary: lead and trail runners'),
  ('baserunning-1-30', 'general', null, 'baserunning', 1, null, 'No outs, you''re on second and the other bases are empty. The batter pops up to the shortstop.', 'What do you do?', array['Take a few steps toward third in case she drops it', 'Run to third on contact', 'Tag up and go on the catch', 'Stay close to second'], 3, 'The shortstop is close to second, and a quick throw would double you off if you''ve strayed. With the ball in front of you and that close, stay near the bag.', 'How long would it take the shortstop to get the ball to second?', 1, '{"runners":["second"],"outs":0,"you":"runner-second","ball":{"at":"SS","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.6 · Runner at 2B, <2 outs: pop-up on the left side'),
  ('baserunning-2-01', 'general', null, 'baserunning', 2, null, 'One out, you''re on second and the other bases are empty. The batter hits a fly ball to medium-deep right field.', 'What do you do?', array['Go halfway to third and wait for the catch', 'Tag up and take third once it''s caught', 'Stay on second, because you never tag from second', 'Run on contact and try to score'], 1, 'A fly to right is behind you and the throw from right field to third is a long one, so tag and go on the catch. On a fly to left, where the throw to third is short, you''d go partway and read it instead.', 'How long is the throw from right field to third?', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.6 · Runner at 2B, <2 outs: fly ball to RF'),
  ('baserunning-2-02', 'general', null, 'baserunning', 2, null, 'Two outs, you''re on second. The batter hits a single on the ground into left field.', 'As you run to third, what decides whether you score?', array['Your own look back at the left fielder', 'Nothing; with two outs you always score from second on a single', 'Your first-base coach''s call', 'Your third-base coach, who tells you to slide, stay up on the bag, round it, or go home'], 3, 'Run hard to third and find your third-base coach; she sees the fielder, the throw, and the plate all at once. Follow her call instead of slowing down to look for the ball yourself.', 'Who can see the fielder, the throw and the plate all at once while you run?', 2, '{"runners":["second"],"outs":2,"you":"runner-second","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Baserunning Playbook p.18 · Runner at 2B, 2 outs: single to LF (reading the 3B coach)'),
  ('baserunning-2-03', 'general', null, 'baserunning', 2, null, 'Two outs, runners on first and third. You single into left field, and the left fielder throws to third trying to get the runner from first.', 'What do you do?', array['Take second on the throw to third', 'Stay on first, because you never advance on a throw to another base', 'Go to second only if the throw to third is wild', 'Run straight through first and walk back to the bag'], 0, 'Once the left fielder commits her throw to third, nobody is in position to stop you at second. Round first with your eyes on the ball and take the free base.', 'Where is the left fielder''s throw going, and what does that leave open?', 2, '{"runners":["first","third"],"outs":2,"you":"batter","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"second","to":"third","kind":"run"},{"from":"LF","to":"third","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.25 · Runners at 1B & 3B, 2 outs: batter on a single to LF'),
  ('baserunning-2-04', 'general', null, 'baserunning', 2, null, 'Two outs, runners on second and third. You''re on second, and the batter hits a ground ball to the shortstop, who is fielding it in your path to third.', 'What do you do?', array['Hold at second until she throws to first', 'Run straight through her path, since it''s her job to get out of your way', 'Run to third on contact, but go around her while she fields the ball', 'Freeze, because the ball is hit in front of you'], 2, 'With two outs you run on contact, but a fielder making a play on a batted ball has the right of way. Run into her and it''s interference, and you can be called out, so steer around her.', 'Who has the right of way when a fielder is making a play on the ball?', 2, '{"runners":["second","third"],"outs":2,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.26 · Runners at 2B & 3B, 2 outs: ground ball to SS'),
  ('baserunning-2-05', 'general', null, 'baserunning', 2, null, 'One out, you''re on third and the other bases are empty. The batter hits a ground ball right back to the pitcher.', 'What do you do?', array['Run home as soon as it''s hit', 'Freeze and stay close to third', 'Go halfway home and wait to see where she throws', 'Tag up on third, then run home'], 1, 'The pitcher fields it a few steps from the plate and is looking right at you, so breaking for home is an easy out. Hold third and let the batter take first.', 'How far is the pitcher from home when she fields it?', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"P","type":"ground"}}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: ground ball back to the pitcher'),
  ('baserunning-2-06', 'general', null, 'baserunning', 2, null, 'One out, you''re on third. The batter hits a short fly ball that pulls the left fielder way in, and she''s set to catch it in shallow left.', 'What''s your best play?', array['Tag up and go home on the catch no matter what', 'Go halfway down the line and read it', 'Stay on the bag and don''t move after the catch', 'Tag up, then take a hard lead after the catch to try to draw a throw'], 3, 'A shallow catch leaves the fielder a short, strong throw home, so scoring is unlikely. Still tag, then break hard off the bag after the catch to bait a throw; a hurried or wild one can give you the run.', 'If scoring isn''t realistic, can you still tempt the fielder into a mistake?', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"LF","type":"fly"}}'::jsonb, 'Baserunning Playbook p.29 · Runner at 3B, <2 outs: shallow fly (draw a throw)'),
  ('baserunning-2-07', 'general', null, 'baserunning', 2, null, 'One out, you''re on third and the pitcher is about to deliver.', 'How should you take your lead?', array['Take a later lead, going off in foul territory and coming back in fair territory', 'Take a big, early lead in fair territory', 'Go off in fair territory and come back in foul territory', 'Don''t lead at all; stay on the bag until the ball is hit'], 0, 'A later lead at third keeps you from getting doubled off on a line drive. Coming back on the fair side of the line puts your body in the catcher''s throwing lane, which makes a pickoff throw harder.', 'Where could you stand to make the catcher''s pickoff throw harder?', 2, '{"runners":["third"],"outs":1,"you":"runner-third"}'::jsonb, 'Baserunning Playbook p.30 · Leads: taking a lead at third base'),
  ('baserunning-2-08', 'general', null, 'baserunning', 2, null, 'One out, you''re on first, and you might get the steal sign this inning.', 'What should you watch to decide how you''ll slide into second?', array['How deep the outfielders are playing', 'Only how hard the pitcher throws', 'Who covers second, whether she gets there on time, and how accurate the catcher''s throws have been', 'Whether the batter is ahead or behind in the count'], 2, 'Knowing who covers, whether she''s early or late, and where the catcher''s throws have been going tells you where the tag will come from. That''s how you decide to slide straight in or to one side of the bag.', 'Where the tag comes from depends on who catches the throw and where it''s thrown.', 2, '{"runners":["first"],"outs":1,"you":"runner-first"}'::jsonb, 'Baserunning Playbook p.31 · Steal tips: scouting before you steal second'),
  ('baserunning-2-09', 'general', null, 'baserunning', 2, null, 'One out, you''re on second. The batter pops a ball up foul behind home plate toward the third-base side, and the catcher and third baseman both chase it.', 'What do you do?', array['Run to third on contact, since a foul ball doesn''t count', 'Tag up at second and watch whether third base is left uncovered', 'Go halfway to third and wait', 'Stay off the bag, because a foul ball is always dead'], 1, 'A caught foul pop is a live ball you can tag up on. With two fielders chasing it and nobody covering third, a good tag can turn into a free base after the catch.', 'Is a caught foul ball live or dead?', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"popup-C","type":"popup"}}'::jsonb, 'Baserunning Playbook p.29 · Foul pop-up: tag up'),
  ('baserunning-2-10', 'general', null, 'baserunning', 2, null, 'One out, nobody on. You hit a ball into the left-center gap.', 'Gap hits usually mean thinking two bases. Which of these is a good reason to hold at first?', array['There''s already one out', 'It went to left-center instead of right-center', 'It''s early in the game', 'It was hit so hard that it reached the outfielder almost instantly'], 3, 'The standard plays assume normal conditions. A rocket that gets to the outfielder fast, a slower runner, or a great defensive play can take away the extra base, so adjust instead of running into an out.', 'What normal conditions is ''think two bases'' built on?', 2, '{"runners":[],"outs":1,"you":"batter","ball":{"at":"LCF-gap","type":"line"}}'::jsonb, 'Baserunning Playbook p.1 · Gap hit: when you can''t push for two'),
  ('baserunning-2-11', 'general', null, 'baserunning', 2, null, 'One out, you''re on first. The batter lifts a fly ball to medium right field.', 'How far off first do you go?', array['About halfway to second', 'Just a few steps, then react to the catch or the drop', 'Run to second on contact', 'Tag up and go on the catch'], 1, 'The right fielder''s throw back to first is short, so drifting halfway gets you doubled off. A few steps is plenty: you can still reach second on a drop and get back on a catch.', 'Which outfielder has the shortest throw back to first?', 2, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"RF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: fly ball to RF'),
  ('baserunning-2-12', 'general', null, 'baserunning', 2, null, 'No outs, you''re on second. The batter hits a soft blooper toward shallow center, and the center fielder is racing in.', 'What do you do?', array['Get a few steps off second, ready to take third on a drop or get back on a catch', 'Tag up at second and go on the catch', 'Run to third on contact', 'Go halfway to third and wait'], 0, 'A blooper is caught close to the infield, so you can''t stray far from second. A few steps gives you a head start on a drop and keeps you safe on a catch.', 'How far is a shallow catch from second base?', 2, '{"runners":["second"],"outs":0,"you":"runner-second","ball":{"at":"blooper-CF","type":"blooper"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.6 · Runner at 2B, <2 outs: blooper to CF'),
  ('baserunning-2-13', 'general', null, 'baserunning', 2, null, 'One out, you''re on second. The batter hits a ground-ball single into right field.', 'How do you handle third base?', array['Run straight into third and stop on the bag', 'Slow down at third to find the ball yourself', 'Round third and pick up your coach''s call to go home or hold', 'Stop at third no matter what, since it''s only a single'], 2, 'A ball in right is behind you and a long way from third, so a hard turn costs you nothing. Round third aggressively and let your coach decide whether you score or go back.', 'How far is the right fielder from third base?', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"RF","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.5 · Runner at 2B, <2 outs: single to RF (rounding third)'),
  ('baserunning-2-14', 'general', null, 'baserunning', 2, null, 'No outs, you''re on first. The batter bunts toward third, and the third baseman charges in, fields it and throws to first.', 'What do you do as you reach second?', array['Stop on second; you only get one base on a bunt', 'Go back to first in case the throw is wild', 'Slide into second and stay down', 'Peek at third, and keep going if nobody is covering it'], 3, 'When the third baseman charges a bunt, third base can be left empty. Run hard to second, glance at third and your coach, and take the extra base if nobody is there.', 'Who covers third when the third baseman charges in?', 2, '{"runners":["first"],"outs":0,"you":"runner-first","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"3B","to":"first","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B: bunt with third base open'),
  ('baserunning-2-15', 'general', null, 'baserunning', 2, null, 'One out, you''re on second. The batter hits a short fly that pulls the center fielder way in. You tag, take a hard lead toward third after the catch, and the center fielder fires the ball to third.', 'What do you do?', array['Stay a few steps off second, ready to run if the throw gets past third', 'Dive back into second right away', 'Sprint for third to beat the throw', 'Jog back to second; the play is over'], 0, 'You''ve drawn the throw you wanted. Stay a few steps off the bag instead of retreating, so if the ball skips past the third baseman you''re already on your way.', 'What could happen to a throw aimed at third, and where do you want to be if it does?', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"CF","type":"fly"},"arrows":[{"from":"CF","to":"third","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.29 · Draw a throw: when the throw goes to the next base'),
  ('baserunning-2-16', 'general', null, 'baserunning', 2, null, 'One out, you''re on third and the other bases are empty. The infield is playing back, and the batter hits a ground ball to the second baseman.', 'What do you do?', array['Freeze, since the ball is on the ground in front of you', 'Hold until she throws to first, then go', 'Run home as soon as it''s hit', 'Go halfway and read the fielder'], 2, 'With the infield playing back, the defense is trading the run for an out at first and is too deep to cut you down at the plate. Break on contact.', 'Where are the infielders standing, and how long is their throw home?', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"2B","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: ground ball with the infield back'),
  ('baserunning-2-17', 'general', null, 'baserunning', 2, null, 'No outs, you''re on first. You know you''ll be forced to run on any ground ball.', 'What skill gets you the best jump?', array['Watching the pitcher''s glove', 'Reading the downward angle of the ball as it leaves the bat', 'Waiting to hear the sound of the bat', 'Watching the catcher''s target'], 1, 'If you see the ball heading down off the bat, you know it''s a grounder before it bounces, and you''re gone. It takes practice, so train it.', 'What can the ball''s path off the bat tell you before it bounces?', 2, '{"runners":["first"],"outs":0,"you":"runner-first","arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Baserunning tips: reading the ball off the bat'),
  ('baserunning-2-18', 'general', null, 'baserunning', 2, null, 'One out, you''re on second. Earlier in the game you saw the left fielder''s throws come in weak, on several hops. Now the batter singles to left.', 'How should that scouting shape your run?', array['It shouldn''t; every single to left is played the same way', 'Slow down so you can watch her throw', 'Stop at third so you don''t run into an out', 'Be ready to score, since a weak arm makes the extra base more likely'], 3, 'Knowing each outfielder''s arm, and whether the defense lines up its cutoffs, tells you when an extra base is really there. A weak arm in left makes it more likely you''re scoring, so run like it.', 'What did her earlier throws tell you about this fielder?', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"LF","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Baserunning tips: knowing the outfielders'' arms'),
  ('baserunning-2-19', 'general', null, 'baserunning', 2, null, 'One out, you''re on second. Before the pitch you noticed the outfield playing deep. The batter loops a soft blooper into shallow left, and it''s obvious no one can get there in time.', 'What do you do?', array['Take off for third right away', 'Get a few steps off second and wait to see if it''s caught', 'Tag up at second', 'Go halfway and freeze'], 0, 'Normally a blooper means short steps and a read. But if you saw the outfield playing deep and the ball clearly can''t be caught, run hard and take third.', 'Where were the outfielders playing before the pitch?', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"blooper-LF","type":"blooper"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Baserunning tips: blooper in front of a deep outfield'),
  ('baserunning-2-20', 'general', null, 'baserunning', 2, null, 'One out, you''re on second and the other bases are empty. The batter hits a fly ball to medium left field.', 'What do you do?', array['Tag up and take third on the catch', 'Stay on second until it comes down', 'Go a third to halfway toward third, then react', 'Run on contact'], 2, 'The left fielder''s throw to third is short, so tagging and running usually loses. Get partway down the line: take third on a drop, get back on a catch.', 'Compare the left fielder''s throw to third with the right fielder''s.', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"LF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.6 · Runner at 2B, <2 outs: fly ball to LF'),
  ('baserunning-2-21', 'general', null, 'baserunning', 2, null, 'One out, runner on first. You hit a fly ball to medium center field.', 'How do you run it out?', array['Round first hard and plan to take second if it''s dropped', 'Jog, since it will probably be caught', 'Stop halfway to first and watch', 'Run hard straight through first base'], 3, 'The runner on first is only partway to second, so if the ball drops she takes second and you need first. Run hard through the bag; the big turn is for when second will be empty.', 'If the ball drops, who is headed to second base?', 2, '{"runners":["first"],"outs":1,"you":"batter","ball":{"at":"CF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: batter on a fly ball to CF'),
  ('baserunning-2-22', 'general', null, 'baserunning', 2, null, 'No outs, you''re on second and the other bases are empty. The batter pops up to the first baseman.', 'What do you do?', array['Stay glued to second', 'Ease a few steps toward third, and go only if it rolls away from her', 'Run to third on contact', 'Tag up and go on the catch'], 1, 'The ball is on the far side of the field, so you can afford a few steps. You aren''t forced, so even on a drop, only go if the ball rolls away from her.', 'How far is the first baseman from second base?', 2, '{"runners":["second"],"outs":0,"you":"runner-second","ball":{"at":"1B","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.6 · Runner at 2B, <2 outs: pop-up on the right side'),
  ('baserunning-2-23', 'general', null, 'baserunning', 2, null, 'One out, you''re on second. The batter pops one up foul behind home plate, and you tag up. The catcher chases it toward the backstop and makes a diving catch, ending up on the ground.', 'What do you do?', array['Stay put; you can''t advance on a foul ball', 'Go halfway and wait for her to get up', 'Leave on the catch and take third', 'Wait for the umpire to award you a base'], 2, 'A caught foul ball is live, so you can tag and advance. With the catcher sprawled on the ground, she can''t make a quick throw to third, so go.', 'How quickly can a fielder lying on the ground make a throw?', 2, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"popup-C","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Foul pop-up: diving catch'),
  ('baserunning-2-24', 'general', null, 'baserunning', 2, null, 'Nobody on, one out. You single to center and make a hard turn at first. The center fielder throws behind you to first, hoping to catch you off the bag.', 'What do you do?', array['Dive back into first', 'Take off for second as soon as she lets it go', 'Stop and wait between the bases', 'Stay where you are and ask for time'], 1, 'This is exactly why you turn hard. A throw behind you to first leaves second wide open, so go right away and make them throw again.', 'When the ball goes to the base behind you, which base is open?', 2, '{"runners":[],"outs":1,"you":"batter","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"CF","to":"first","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.29 · Pushing the outfield: throw behind the batter-runner'),
  ('baserunning-2-25', 'general', null, 'baserunning', 2, null, 'One out, you''re on third. The batter hits a line drive just over the shortstop''s head into left field.', 'When do you head home?', array['The instant it leaves the bat', 'Only after the left fielder throws', 'Only if the left fielder bobbles it', 'As soon as you see it''s past the infield'], 3, 'A liner can be snagged by a leaping infielder, and if you''ve already left you''ll be doubled off. Hold for that split second, and once it''s clearly through the infield, score.', 'What happens if an infielder leaps and snags it after you''ve left?', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"LF","type":"line"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: line-drive single'),
  ('baserunning-2-26', 'general', null, 'baserunning', 2, null, 'One out, runners on second and third. The batter flies out to medium left field, and you''re back on second after the catch. The runner on third tags and heads home, and the left fielder throws home.', 'What now?', array['Stay at second; you already went back once', 'Go halfway and freeze', 'Take off for third on the throw home', 'Run home right behind the lead runner'], 2, 'When the left fielder throws home, the ball is heading away from third. You''ve retouched second after the catch, so take the extra base.', 'Once the left fielder throws home, who is left to cover third?', 2, '{"runners":["second","third"],"outs":1,"you":"runner-second","ball":{"at":"LF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"LF","to":"home","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.15 · Runners at 2B & 3B, <2 outs: fly ball to LF (runner at 2B)'),
  ('baserunning-2-27', 'general', null, 'baserunning', 2, null, 'One out, runner on first. You hit a ground-ball single into left field.', 'What do you do at first base?', array['Round first and watch what the runner ahead of you does', 'Run straight through first, like on a grounder to the infield', 'Head straight for second no matter what', 'Stop on first and wait for the coach'], 0, 'Your next move depends on the runner ahead of you. If she stops at second you hold, but if she pushes for third and draws the throw, second can open up.', 'Can you take second if the runner ahead of you is still standing on it?', 2, '{"runners":["first"],"outs":1,"you":"batter","ball":{"at":"LF","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B, <2 outs: batter on a single to LF'),
  ('baserunning-2-28', 'general', null, 'baserunning', 2, null, 'You hit a clean single into left-center field.', 'How do you round first base?', array['Run straight at the bag and make a sharp 90-degree turn', 'Swing out a step or two before the bag, touch the inside corner and head straight for second', 'Slow down at the bag and look at your coach first', 'Run past the bag toward right field'], 1, 'A small bubble a few steps before first lets you hit the inside corner of the bag at full speed and come out of the turn already on a line to second.', 'How do you keep your speed through the turn?', 2, '{"runners":[],"outs":0,"you":"batter","ball":{"at":"LCF-gap","type":"line"}}'::jsonb, 'GGG.Cafe Softball IQ · The bubble turn'),
  ('baserunning-2-29', 'general', null, 'baserunning', 2, null, 'You''re on first, one out. The pitch bounces in the dirt and gets away from the catcher.', 'What do you do?', array['Stay: you can''t run on a ball in the dirt', 'Read it: if it gets past the catcher, go to second', 'Go back to first', 'Wait for your coach to call time'], 1, 'Once the pitch is released, a ball in the dirt is live. Read the bounce: if it gets past the catcher, take second; if she smothers it in front, hold.', 'Is the ball live after she releases it?', 2, '{"runners":["first"],"outs":1,"you":"runner-first"}'::jsonb, 'GGG.Cafe Softball IQ · Ball in the dirt'),
  ('baserunning-2-30', 'general', null, 'baserunning', 2, null, 'Runner on third, one out. A foul pop drifts toward the fence down the first-base line and the first baseman chases it.', 'What do you do?', array['Stay on the bag, tag up and get ready to score if she catches it moving away from home', 'Run home right away', 'Take a big lead toward home', 'Nothing: you can''t advance on a foul ball'], 0, 'A caught foul fly is still a catch, so runners can tag and advance. With the fielder moving away from home, a tag-up can score you.', 'Is a caught foul ball any different from a caught fair ball?', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"1B","type":"popup"}}'::jsonb, 'GGG.Cafe Softball IQ · Tag on a foul fly'),
  ('baserunning-3-01', 'general', null, 'baserunning', 3, null, 'One out, runners on first and third. Your coach calls the 75% steal, and you''re the runner on first. As you head for second, the catcher throws all the way through to second.', 'What do you do?', array['Kick into full speed and slide into second', 'Turn and sprint straight back to first', 'Stop, get into a rundown, and stay alive so the runner on third can score', 'Stop where you are and let them tag you to avoid a collision'], 2, 'On the 75% play you take second only if they give it to you. If they throw through, get caught in a rundown and keep it going; every throw gives the runner on third a chance to score.', 'If you can''t reach second, how can you still help the runner on third?', 3, '{"runners":["first","third"],"outs":1,"you":"runner-first","arrows":[{"from":"first","to":"second","kind":"steal"},{"from":"C","to":"second","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.31 · First & third: 75% steal, catcher throws through'),
  ('baserunning-3-02', 'general', null, 'baserunning', 3, null, 'One out, you''re on first and the other bases are empty. Your coach puts on the delayed steal.', 'When do you take off for second?', array['On the catcher''s return throw to the pitcher', 'On the pitcher''s release, like a straight steal', 'When the pitcher starts her windup', 'After the pitcher gets the ball back and steps on the rubber'], 0, 'A delayed steal counts on the defense relaxing after the pitch: take your normal lead, then go as the catcher tosses it back to the circle. Scout it first: does the catcher look you back, does the pitcher glance your way, and which way does she turn as she catches the return?', 'When does the defense tend to relax after a pitch?', 3, '{"runners":["first"],"outs":1,"you":"runner-first"}'::jsonb, 'Baserunning Playbook p.31 · Delayed steal: when to go'),
  ('baserunning-3-03', 'general', null, 'baserunning', 3, null, 'No outs, runners on first and third. You''re on third, and the runner on first takes off for second on the pitch.', 'When do you break for home?', array['As soon as the catcher catches the pitch', 'As soon as the catcher stands up to throw', 'Never; stay on third no matter what', 'Only once you see the throw is going all the way through to second'], 3, 'If you leave early, a fake, a short throw, or a cut-off can trap you between third and home. Read the throw, and only go once the ball is clearly headed through to second.', 'What could happen to you if the catcher only fakes the throw?', 3, '{"runners":["first","third"],"outs":0,"you":"runner-third","arrows":[{"from":"first","to":"second","kind":"steal"}]}'::jsonb, 'Baserunning Playbook p.31 · First & third: runner at 3B on a steal of second'),
  ('baserunning-3-04', 'general', null, 'baserunning', 3, null, 'Bases loaded, one out. You''re on third, and the batter hits a ground ball to the shortstop.', 'What do you do?', array['Freeze unless the infield is playing back', 'Sprint home and slide', 'Hold until the defense throws to first, then go', 'Go back and tag third before running'], 1, 'With the bases loaded you''re forced, so the usual reads at third don''t apply; you have to go. Run hard and slide, because the defense may come home for the force.', 'With every base filled, do you have a choice?', 3, '{"runners":["first","second","third"],"outs":1,"you":"runner-third","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.10 · Bases loaded, <2 outs: ground ball (runner at 3B)'),
  ('baserunning-3-05', 'general', null, 'baserunning', 3, null, 'No outs, runners on second and third. You''re on second. The batter hits a ground ball to the shortstop, and the runner on third holds.', 'What do you do?', array['Run to third, because you''re forced on a ground ball', 'Run to third so the lead runner has to go home', 'Hold at second, because the runner ahead of you didn''t go', 'Get into a rundown to help the runner on third score'], 2, 'You''re the trail runner and you aren''t forced, so you can only take third after the runner in front of you leaves it. Get a good jump, but if she stays, you stay.', 'Can two runners share third base?', 3, '{"runners":["second","third"],"outs":0,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Baserunning Playbook p.14 · Runners at 2B & 3B, <2 outs: ground ball to SS (trail runner)'),
  ('baserunning-3-06', 'general', null, 'baserunning', 3, null, 'Two outs, runners on first and second. You''re on second and you''re one of the fastest players on the team. The batter bunts, and the pitcher fields it and throws to first.', 'What do you do?', array['Round third hard and be ready to score if the first baseman drops the throw', 'Stop on third and stay there', 'Score no matter what happens at first', 'Go back to second in case of a double play'], 0, 'The defense is going for the third out at first. If you''ve already rounded third, you can score when the first baseman drops it; if she catches it, the inning is over anyway and the run wouldn''t count.', 'If the throw to first gets away, where do you want to already be?', 3, '{"runners":["first","second"],"outs":2,"you":"runner-second","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"P","to":"first","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.21 · Runners at 1B & 2B, 2 outs: bunt with the play at first'),
  ('baserunning-3-07', 'general', null, 'baserunning', 3, null, 'One out, runners on first and second. The batter pops up to the shortstop, the umpire calls infield fly, and the shortstop drops it. You''re on second.', 'What do you have to do?', array['Run to third, because once the ball hits the ground you''re forced', 'Run to third, because the batter is now safe at first and pushes you along', 'Go to third, because a dropped infield fly awards every runner a base', 'Nothing; the batter is already out, so you''re not forced and can stay at second'], 3, 'Once infield fly is called, the batter is out whether the ball is caught or not, which takes away the force. You can stay where you are and only advance if you can take the base safely.', 'Once infield fly is called, is the batter still a runner?', 3, '{"runners":["first","second"],"outs":1,"you":"runner-second","ball":{"at":"SS","type":"popup"}}'::jsonb, 'Baserunning Playbook p.9 · Infield fly rule: ball dropped'),
  ('baserunning-3-08', 'general', null, 'baserunning', 3, null, 'One out, you''re on second. The batter hits a ball into the left-center gap. As you run to third, the third baseman, who doesn''t have the ball and isn''t fielding it, steps into your path and you have to swerve around her.', 'What is this called?', array['Interference, and you''re out', 'Obstruction on the defense', 'Nothing, because fielders can stand wherever they want', 'Running out of the baseline, and you''re out'], 1, 'Obstruction is a fielder without the ball, and not making a play, getting in a runner''s way. Interference is the reverse: the runner blocking or running into a fielder who is making a play. Keep running hard and let the umpire make the call.', 'Which call goes against the defense, and which against the runner?', 3, '{"runners":["second"],"outs":1,"you":"runner-second","ball":{"at":"LCF-gap","type":"line"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Baserunning Playbook p.2 · Rules: obstruction'),
  ('baserunning-3-09', 'general', null, 'baserunning', 3, null, 'Bases loaded, two outs. You''re on first, and the batter pops up to the second baseman.', 'What do you do?', array['Run straight to second on contact', 'Stay near first, because the infield fly rule protects you', 'Tag up at first and go on the catch', 'Go halfway to second and read it'], 0, 'The infield fly rule only applies with fewer than two outs. With two outs a catch ends the inning, so everyone runs on contact; if it''s dropped, you need to beat the force at second.', 'With two outs, what are you protecting by staying near first?', 3, '{"runners":["first","second","third"],"outs":2,"you":"runner-first","ball":{"at":"2B","type":"popup"}}'::jsonb, 'Baserunning Playbook p.24 · Bases loaded, 2 outs: pop-up to the infield'),
  ('baserunning-3-10', 'general', null, 'baserunning', 3, null, 'One out, runners on first and third. No squeeze is on, but the batter bunts toward first base. You''re on third.', 'What''s your read?', array['Break for home the moment the ball is bunted, like a squeeze', 'Stay on third no matter what, since no squeeze means no run', 'Read the fielder and break for home when she throws to first', 'Go back and tag third before you run'], 2, 'On a squeeze you''re already running on the pitch, but without one you have to read the play. When the fielder commits her throw to first, that''s your window to score; if the bunt is popped up, freeze and get back.', 'Without a squeeze on, what moment gives you your best chance to score?', 3, '{"runners":["first","third"],"outs":1,"you":"runner-third","ball":{"at":"bunt-1B","type":"bunt"}}'::jsonb, 'Baserunning Playbook p.12 · Runners at 1B & 3B, <2 outs: bunt with no squeeze on'),
  ('baserunning-3-11', 'general', null, 'baserunning', 3, null, 'One out, runners on first and third. You''re on first and the call is ''no steal.'' You take an aggressive lead on the pitch, and the catcher throws to third trying to pick off the runner there.', 'What do you do?', array['Get back to first right away', 'Take second while the ball goes to third', 'Freeze where you are and wait', 'Head for second only if the throw gets past third'], 1, 'On ''no steal'' your job is to look like you''re going and see where the ball goes. A throw to third leaves second open, so take it.', 'Which base did the catcher''s throw leave unguarded?', 3, '{"runners":["first","third"],"outs":1,"you":"runner-first","arrows":[{"from":"C","to":"third","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.31 · First & third: ''no steal'' call'),
  ('baserunning-3-12', 'general', null, 'baserunning', 3, null, 'No outs, runners on first and third. You''re on first, and your coach calls the 100% steal.', 'What''s your job?', array['Run at about three-quarter speed and stop if they throw through', 'Fake a steal and watch for a throw', 'Steal second on the release, running all-out', 'Wait for the catcher''s throw back to the pitcher, then go'], 2, 'The 100% call is a straight steal: go on the release and run all-out to take second. Easing up to bait a rundown is the 75% play, not this one.', 'What does ''100%'' tell you about how hard you''re running?', 3, '{"runners":["first","third"],"outs":0,"you":"runner-first","arrows":[]}'::jsonb, 'Baserunning Playbook p.31 · First & third: 100% steal'),
  ('baserunning-3-13', 'general', null, 'baserunning', 3, null, 'One out, you''re on first and the other bases are empty. You''re watching the pitcher and catcher for a few pitches before trying a delayed steal.', 'Which of these is the best sign the delayed steal will work?', array['The catcher looks you back before every return throw', 'The pitcher turns toward you as she catches the return throw', 'The pitcher stares at you before she takes the ball back', 'The catcher tosses the ball back without ever checking you'], 3, 'A delayed steal works when the defense relaxes after the pitch. If the catcher never checks you and the pitcher turns away for the return throw, nobody is watching when you go.', 'On a delayed steal, who needs to be not paying attention to you?', 3, '{"runners":["first"],"outs":1,"you":"runner-first","arrows":[]}'::jsonb, 'Baserunning Playbook p.31 · Delayed steal: scouting the battery'),
  ('baserunning-3-14', 'general', null, 'baserunning', 3, null, 'Bases loaded, one out. You''re on first, and the batter pops the ball high above the shortstop.', 'What do you do?', array['Stay close to first', 'Take off for second in case it''s dropped', 'Go halfway to second', 'Tag up and run to second on the catch'], 0, 'With first and second filled and fewer than two outs, the umpire should call infield fly, so the batter is out and a drop doesn''t force you. Stay close to the bag.', 'What special call can the umpire make on a pop-up with first and second filled?', 3, '{"runners":["first","second","third"],"outs":1,"you":"runner-first","ball":{"at":"SS","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.11 · Bases loaded, <2 outs: pop-up to the infield'),
  ('baserunning-3-15', 'general', null, 'baserunning', 3, null, 'Runners on first and third, one out. You''re on first, and the batter pops up to the shortstop.', 'What do you do?', array['Stay on the bag, since the infield fly rule protects you', 'Get a few steps off first in case she drops it', 'Run to second on contact', 'Tag up and go on the catch'], 1, 'The infield fly rule needs runners on first and second, so it doesn''t apply here. If she drops it the batter becomes a runner and you''re forced, so give yourself a few steps'' head start.', 'Which bases have to be filled for the infield fly rule to apply?', 3, '{"runners":["first","third"],"outs":1,"you":"runner-first","ball":{"at":"SS","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.13 · Runners at 1B & 3B, <2 outs: pop-up to SS (no infield fly)'),
  ('baserunning-3-16', 'general', null, 'baserunning', 3, null, 'One out, you''re on third and the other bases are empty. Your coach puts on the squeeze.', 'When do you break for home?', array['When the fielder throws to first', 'Only if the bunt rolls toward first', 'As the pitcher releases the pitch', 'After the catcher catches the pitch'], 2, 'On a squeeze you''re stealing home, and the batter has to bunt whatever pitch comes. Leave on the release so you''re nearly home by the time the ball is fielded.', 'If you wait to see the bunt, how far from home will you be when it''s fielded?', 3, '{"runners":["third"],"outs":1,"you":"runner-third","arrows":[]}'::jsonb, 'Baserunning Playbook p.7 · Squeeze: when the runner at 3B goes'),
  ('baserunning-3-17', 'general', null, 'baserunning', 3, null, 'Bases loaded, one out. The batter hits a fly ball to medium-deep center field. You''re on second.', 'What do you do?', array['Tag up, and take third only if the runner ahead of you goes home', 'Go halfway to third and read it', 'Run on contact', 'Tag up and go to third on the catch no matter what'], 0, 'Tag at second, but third isn''t yours until the lead runner leaves it. If she tags and scores you move up; if she holds, you hold.', 'Can you move up to a base that''s still occupied?', 3, '{"runners":["first","second","third"],"outs":1,"you":"runner-second","ball":{"at":"CF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.11 · Bases loaded, <2 outs: fly ball to CF (runner at 2B)'),
  ('baserunning-3-18', 'general', null, 'baserunning', 3, null, 'One out, runner on second. You hit a blooper to shallow left, the left fielder drops it, and the ball rolls a few feet away. You''ve rounded first.', 'What decides whether you go to second?', array['How far the ball rolled, no matter what the runner ahead does', 'Your first-base coach''s guess', 'Nothing; always take second on a dropped ball', 'Whether the runner ahead of you has moved up to third'], 3, 'You''re the trail runner, so second only opens once the lead runner has left it. Make sure she''s moving up before you commit, or you''ll end up with two runners on one base.', 'What has to happen ahead of you before second is free?', 3, '{"runners":["second"],"outs":1,"you":"batter","ball":{"at":"blooper-LF","type":"blooper"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.6 · Runner at 2B, <2 outs: batter on a dropped blooper'),
  ('baserunning-3-19', 'general', null, 'baserunning', 3, null, 'One out, runners on first and third. Your coach calls the 75% steal and you''re on first. As you run, the catcher looks the runner on third back and holds onto the ball.', 'What do you do?', array['Stop and get into a rundown', 'Keep going and take second', 'Go back to first', 'Stop halfway and wait for a throw'], 1, 'The 75% play is about taking what the defense gives you. If the catcher won''t throw, second is free, so finish the steal.', 'Is the defense trying to stop you at all?', 3, '{"runners":["first","third"],"outs":1,"you":"runner-first","arrows":[]}'::jsonb, 'Baserunning Playbook p.31 · First & third: 75% steal, no throw'),
  ('baserunning-3-20', 'general', null, 'baserunning', 3, null, 'No outs, you''re on second and the other bases are empty. The batter lays down a bunt toward third, and the third baseman charges in to field it.', 'When do you go?', array['Hold until she throws to first, like on a grounder to short', 'Run straight to third as soon as it''s down', 'Stay at second, since you''re not forced', 'Go halfway and read the fielder'], 1, 'Unlike a hard grounder to the left side, a bunt pulls the infielders in toward the plate. Don''t wait around: run straight to third once it''s down.', 'Where are the infielders moving when a bunt is laid down?', 3, '{"runners":["second"],"outs":0,"you":"runner-second","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.5 · Runner at 2B, <2 outs: bunt'),
  ('baserunning-3-21', 'general', null, 'baserunning', 3, null, 'One out, runners on first and second, and you''re on first. A fly ball to medium right is caught and you retouch first, while the runner on second tags and takes off for third. The right fielder throws to third to get her.', 'What do you do?', array['Take second on the throw to third', 'Stay at first, since you only went a few steps', 'Go to second only if the throw is wild', 'Go halfway and freeze'], 0, 'The right fielder can''t throw to two bases at once. With her throw headed to third and you back on first after the catch, move up to second.', 'Can the right fielder throw to two bases at once?', 3, '{"runners":["first","second"],"outs":1,"you":"runner-first","ball":{"at":"RF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"RF","to":"third","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.9 · Runners at 1B & 2B, <2 outs: fly ball to RF (runner at 1B)'),
  ('baserunning-3-22', 'general', null, 'baserunning', 3, null, 'One out, you''re on first. The batter hits a ball into the right-center gap. As you approach third, the third baseman has already caught the relay throw and is standing in front of the bag, waiting to tag you.', 'Is this obstruction?', array['Yes, a fielder can never block the base', 'Yes, and you''re automatically awarded home', 'No, because she has the ball', 'No, because you left the baseline'], 2, 'Obstruction is a fielder getting in your way without the ball. Once she has it, she can stand there and make the tag, so it''s on you to beat it.', 'What does the definition of obstruction say about the ball?', 3, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"RCF-gap","type":"line"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Baserunning Playbook p.2 · Rules: when it isn''t obstruction'),
  ('baserunning-3-23', 'general', null, 'baserunning', 3, null, 'One out, runner on third, and the squeeze is on. You''re the batter, and the pitch comes in high and a little outside.', 'What do you do?', array['Pull the bat back and take the pitch', 'Swing away to protect the runner', 'Step out of the box', 'Do everything you can to bunt it'], 3, 'Your runner is already sprinting home, so if you take the pitch she''s an easy out at the plate. On a squeeze you have to try to bunt it, wherever it is.', 'Where is your runner while the pitch is on its way?', 3, '{"runners":["third"],"outs":1,"you":"batter","arrows":[{"from":"third","to":"home","kind":"steal"}]}'::jsonb, 'Baserunning Playbook p.2 · Squeeze: the batter''s job'),
  ('baserunning-3-24', 'general', null, 'baserunning', 3, null, 'Two outs, runner on first. You hit a fly ball to center field.', 'How do you run it out?', array['Run hard straight through first', 'Jog, since a catch ends the inning', 'Stop at first and watch the runner ahead', 'Round first hard so you''re ready to take second if it''s dropped'], 3, 'With two outs the runner on first goes on contact and should be around second by the time the ball comes down. That frees second for you, so make a hard turn and be ready to go on a drop.', 'With two outs, where will the runner ahead of you be when the ball comes down?', 3, '{"runners":["first"],"outs":2,"you":"batter","ball":{"at":"CF","type":"fly"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.17 · Runner at 1B, 2 outs: batter on a fly ball to CF'),
  ('baserunning-3-25', 'general', null, 'baserunning', 3, null, 'One out, you''re on third and no squeeze is on. The batter pops the bunt up in the air toward the pitcher.', 'What do you do?', array['Freeze and get back to third', 'Break for home since it''s a bunt', 'Go halfway home and read the catch', 'Tag up and run home on the catch'], 0, 'A popped-up bunt will probably be caught, and the pitcher is close enough to double you off third. Freeze, then get back to the bag.', 'If she catches it, how quickly can she throw to third?', 3, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"bunt-P","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B, <2 outs: bunt popped up'),
  ('baserunning-3-26', 'general', null, 'baserunning', 3, null, 'One out, runners on second and third, and the squeeze is on. You''re on second.', 'What do you do?', array['Stay at second, since the squeeze is only for the runner on third', 'Hold until the bunt is fielded and thrown to first', 'Move up to third once the lead runner leaves it', 'Break for third before the pitch to draw a throw'], 2, 'As the trail runner, third opens the moment the runner ahead leaves for home. Move up behind her.', 'What happens to third base the moment the squeeze starts?', 3, '{"runners":["second","third"],"outs":1,"you":"runner-second","arrows":[]}'::jsonb, 'Baserunning Playbook p.14 · Runners at 2B & 3B, <2 outs: squeeze (runner at 2B)'),
  ('baserunning-3-27', 'general', null, 'baserunning', 3, null, 'Nobody out, you''re on second. A ground ball goes to the shortstop''s right.', 'Should you try for third?', array['Yes, always run on a ground ball', 'Only if it''s a sure thing: never make the first out at third', 'Yes, the shortstop always throws to first', 'Go back toward second'], 1, 'With nobody out you can score from second on a hit and from third on many outs. Getting thrown out at third wastes a runner in scoring position.', 'Can you already score from second?', 3, '{"runners":["second"],"outs":0,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Never make the first out at third'),
  ('baserunning-3-28', 'general', null, 'baserunning', 3, null, 'Two outs, you''re on second. The batter hits a ground ball into the hole and the shortstop dives for it.', 'Do you try to go to third on the play?', array['Yes, any extra base helps', 'No: with two outs you score from second on a hit, so third gains nothing worth the risk', 'Yes, if the ball gets to the outfield', 'Stay on second no matter what'], 1, 'With two outs you''re running on contact and a hit scores you from second anyway. Being out at third ends the inning for no reason.', 'Where does a two-out hit score you from?', 3, '{"runners":["second"],"outs":2,"you":"runner-second","ball":{"at":"SS","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Never make the third out at third'),
  ('baserunning-3-29', 'general', null, 'baserunning', 3, null, 'Runner on third, one out. The infield is drawn in and a sharp ground ball goes right to the second baseman.', 'What do you do?', array['Go home on contact no matter what', 'Freeze and go back to third: a drawn-in infielder has an easy throw home', 'Go halfway and stop', 'Run to the dugout'], 1, 'With the infield in, a ground ball right at an infielder is an easy out at home. Read the ball: go only if it gets through or your coach has called the contact play.', 'Where are the infielders playing?', 3, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"2B","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Contact read at third'),
  ('baserunning-3-30', 'general', null, 'baserunning', 3, null, 'Two outs, you''re on first. The batter swings at a 3-2 pitch.', 'When do you go?', array['On contact only', 'As the pitch is released: with two outs and a full count you''re running', 'After the ball lands', 'Only if your coach yells'], 1, 'With two outs and a full count, a ball walks you to second and a strike ends the inning, so you run as the pitch is released and get a head start on any hit.', 'What happens to you on ball four, strike three or a hit?', 3, '{"runners":["first"],"outs":2,"you":"runner-first"}'::jsonb, 'GGG.Cafe Softball IQ · Two outs: go on contact'),
  ('offense-1-01', 'general', null, 'offense', 1, null, 'Nobody on. The pitcher has missed with her first two pitches.', 'Which of these counts is a hitter''s count?', array['1-2', '2-0', '0-1', '0-2'], 1, 'When you''re ahead (2-0, 3-1, 2-1) the pitcher has to throw a strike, so you can sit on your pitch and attack it. Behind in the count, she can throw her best pitch off the plate.', 'Who is under pressure to throw a strike?', 1, '{"runners":[],"outs":0,"you":"batter","count":{"balls":2,"strikes":0}}'::jsonb, 'GGG.Cafe Offense IQ · Hitter''s counts'),
  ('offense-1-02', 'general', null, 'offense', 1, null, 'You''ve fallen behind 0-2 to a pitcher with good movement.', 'What changes in your approach?', array['Widen your zone a little, shorten up and fight to put the ball in play', 'Take the next pitch no matter what', 'Swing as hard as you can at anything she throws', 'Nothing, you still only swing at your one pitch'], 0, 'With two strikes a close pitch can be called strike three. Expand your zone slightly, shorten your swing (choke up if you like) and foul off tough pitches until you get one you can hit.', 'What happens if a close pitch goes by?', 1, '{"runners":[],"outs":0,"you":"batter","count":{"balls":0,"strikes":2}}'::jsonb, 'GGG.Cafe Offense IQ · Two strikes: battle'),
  ('offense-1-03', 'general', null, 'offense', 1, null, 'It''s 3-0 with nobody on. Your coach gives you the take sign.', 'What do you do?', array['Swing only if it''s right down the middle', 'Bunt it', 'Step out and ask for a different sign', 'Take the pitch, even if it''s a strike'], 3, 'A take sign means take, no matter where the pitch is. Your coach may want a walk, a look at the pitcher or a runner to move. Trust the call.', 'What did the sign tell you to do?', 1, '{"runners":[],"outs":0,"you":"batter","count":{"balls":3,"strikes":0}}'::jsonb, 'GGG.Cafe Offense IQ · The take sign'),
  ('offense-1-04', 'general', null, 'offense', 1, null, 'First pitch of your at-bat: a fastball right in your hot zone.', 'What''s the best approach?', array['Bunt it to surprise the defense', 'Only swing if you already have a strike', 'Be ready to attack it: a first-pitch strike in your zone may be the best pitch you see', 'Always take the first pitch to see what she has'], 2, 'Pitchers like to get ahead with a strike early. If it''s your pitch, be on time and drive it. Taking good first pitches puts you in a hole.', 'When will you see her most hittable pitch?', 1, '{"runners":[],"outs":0,"you":"batter","count":{"balls":0,"strikes":0}}'::jsonb, 'GGG.Cafe Offense IQ · First pitch in your zone'),
  ('offense-1-05', 'general', null, 'offense', 1, null, 'Runner on third, one out. The infield is playing back.', 'What''s your goal at the plate?', array['Strike out swinging rather than hit a ground ball', 'Put the ball in play: a ground ball up the middle or a fly ball to the outfield scores her', 'Bunt it back to the pitcher', 'Take pitches until you walk'], 1, 'With the infield back, the defense is giving up the run for an out. A ground ball to the middle infield or a fly ball deep enough scores her. Putting it in play is what matters.', 'Where does the defense want to get its out?', 1, '{"runners":["third"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Runner on third, infield back'),
  ('offense-1-06', 'general', null, 'offense', 1, null, 'Runner on first, nobody out. Your coach calls the sacrifice bunt.', 'What''s your job?', array['Get the bunt down on the ground, even if you''re out at first', 'Bunt it in the air over the pitcher', 'Bunt for a hit so you''re safe too', 'Swing away if the pitch is good'], 0, 'A sacrifice trades your out for moving the runner. Square early enough, bunt a strike and get it on the ground. Being out at first is the plan.', 'What does the word sacrifice tell you?', 1, '{"runners":["first"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Sacrifice bunt'),
  ('offense-1-07', 'general', null, 'offense', 1, null, 'Runner on first, nobody out, sacrifice bunt on.', 'Where should the bunt go?', array['In the air toward first base', 'Hard enough to reach the shortstop', 'Hard back at the pitcher', 'Down either line on the ground, away from the pitcher'], 3, 'Bunts down the first- or third-base line, on the ground, make a corner infielder field the ball and throw to first. A bunt back to the pitcher gives her an easy force at second.', 'Who has the easiest play on a ball right back to the circle?', 1, '{"runners":["first"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Where to sacrifice'),
  ('offense-1-08', 'general', null, 'offense', 1, null, 'Two outs, runner on second.', 'Why does a base hit matter so much here?', array['Only an extra-base hit can score her', 'A walk scores her', 'She runs on contact with two outs, so a hit to the outfield can score her', 'The runner has to stay at second until the ball is caught'], 2, 'With two outs runners go on contact because there''s no reason to wait. A clean single to the outfield usually scores a runner from second.', 'When do runners go with two outs?', 1, '{"runners":["second"],"outs":2,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Two outs, runner on second'),
  ('offense-1-09', 'general', null, 'offense', 1, null, 'One out, nobody on. You swing through strike three and the ball bounces off the catcher into the dirt.', 'What do you do?', array['Walk back to the dugout: you struck out', 'Run to first right away: she has to tag you or throw you out', 'Wait for the umpire to tell you to run', 'Ask for time'], 1, 'On a dropped third strike with first base open (or with two outs) you can run. Sprint to first; the catcher has to tag you or throw to first.', 'Is the out complete if the catcher doesn''t catch strike three?', 1, '{"runners":[],"outs":1,"you":"batter","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Offense IQ · Dropped third strike'),
  ('offense-1-10', 'general', null, 'offense', 1, null, 'You lead off the inning.', 'What''s your main job?', array['Get on base: a walk is as good as a single', 'See as many pitches as possible and strike out looking', 'Bunt every time', 'Hit a home run'], 0, 'The leadoff hitter''s job is to get on. A walk, a bunt single or a hit all start a rally, and a runner on base puts pressure on the defense.', 'What starts a rally?', 1, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Leadoff hitter'),
  ('offense-1-11', 'general', null, 'offense', 1, null, 'You keep fouling pitches straight back or late to the right side (you hit right-handed).', 'What does that tell you?', array['You need a heavier bat', 'You should bunt', 'You''re too early', 'You''re a little late: start your load sooner as she begins her motion'], 3, 'Fouls straight back and late swings to the opposite side mean you''re just behind the pitch. Start your load earlier so you''re ready to swing as the ball leaves her hand.', 'Where does the ball go when you''re behind it?', 1, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Your timing'),
  ('offense-1-12', 'general', null, 'offense', 1, null, 'You keep swinging under pitches that start at your belt and finish around your chin.', 'What''s the adjustment?', array['Close your eyes on the swing', 'Swing harder', 'Lay off pitches above your hands', 'Move to the back of the box'], 2, 'That''s the rise ball. It looks like a strike, then climbs. Make her bring the ball down: anything that starts at your hands or higher, take.', 'Which pitches can you actually square up?', 1, '{"runners":[],"outs":0,"you":"batter","count":{"balls":1,"strikes":1}}'::jsonb, 'GGG.Cafe Offense IQ · The rise ball'),
  ('offense-1-13', 'general', null, 'offense', 1, null, 'Pitches look like strikes at your knees, then dive into the dirt.', 'What''s the best adjustment?', array['Bunt every pitch', 'Look for the ball up in the zone and let the low ones go', 'Swing at everything at your knees', 'Stand closer to the plate'], 1, 'That''s the drop ball. Raise your eyes: look for pitches from your belt up and let the ones at your knees go, because they''ll end up in the dirt.', 'Where do those pitches finish?', 1, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · The drop ball'),
  ('offense-1-14', 'general', null, 'offense', 1, null, 'You''re way out in front of a slow pitch and roll it over to third.', 'What was it, and how do you adjust?', array['A change-up: stay back and keep your hands back until it gets to you', 'A drop ball: swing down', 'A curve: stand farther off the plate', 'A rise ball: swing up'], 0, 'A change-up looks like a fastball out of her hand, then arrives late. Stay back, keep your weight and hands back, and let it come to you.', 'Why were you out in front?', 1, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · The change-up'),
  ('offense-1-15', 'general', null, 'offense', 1, null, 'You''re on deck while your teammate is batting.', 'What should you be doing?', array['Talking to the fans', 'Looking at your phone in the dugout', 'Practicing your bunt only', 'Timing the pitcher and taking swings on time with her release'], 3, 'The on-deck circle is your best look at the pitcher. Time her release, see her pitches and take swings on time so your first pitch isn''t your first look.', 'What do you want to know before you step in?', 1, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · On deck'),
  ('offense-1-16', 'general', null, 'offense', 1, null, 'Bases loaded, two outs, full count.', 'What''s your approach?', array['Swing only at a pitch right down the middle', 'Take: she might walk you', 'Protect the plate: swing at anything close', 'Bunt for a hit'], 2, 'A close pitch taken could be strike three and end the inning. Swing at anything close and battle. Ball four still walks in a run if she misses badly.', 'What happens if a close pitch goes by?', 1, '{"runners":["first","second","third"],"outs":2,"you":"batter","count":{"balls":3,"strikes":2}}'::jsonb, 'GGG.Cafe Offense IQ · Protect the plate'),
  ('offense-1-17', 'general', null, 'offense', 1, null, 'Runner on third, one out. The infield is playing in.', 'What does that mean for you?', array['The infielders can''t catch line drives', 'A hard ground ball gets through more easily', 'You can''t score the runner', 'You have to bunt'], 1, 'With the infield drawn in, a hard ground ball or line drive has a better chance to get through. Hit the ball hard, on the ground or in the air.', 'What happens when infielders give up range?', 1, '{"runners":["third"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Infield in'),
  ('offense-1-18', 'general', null, 'offense', 1, null, 'Runner on third. Your coach calls the safety squeeze.', 'When does the runner break for home?', array['Only once she sees the bunt go down on the ground', 'On the first pitch no matter what', 'After the catcher throws to first', 'As the pitcher starts her motion'], 0, 'On a safety squeeze the runner reads the bunt and goes only when it''s down on the ground. Your job is to get a good bunt down away from the pitcher.', 'Which squeeze is safe for the runner?', 1, '{"runners":["third"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Safety squeeze'),
  ('offense-1-19', 'general', null, 'offense', 1, null, 'You weren''t sure what sign your coach just gave.', 'What do you do?', array['Take every pitch', 'Guess', 'Swing away', 'Step out of the box and look again (call time if you need it)'], 3, 'Never guess on a sign. Step out with a foot still near the box, look again, or call time. A missed sign can cost an out or a runner.', 'What''s worse than asking again?', 1, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Missed sign'),
  ('offense-1-20', 'general', null, 'offense', 1, null, 'A pitch is coming right at your hip.', 'How do you protect yourself?', array['Dive across the plate', 'Stand still', 'Turn away from the pitch, tuck your hands and let it hit your back side', 'Put your hands out to block it'], 2, 'Turning away protects your face, hands and the front of your body. Tuck your hands in and let the pitch hit your back side, then take your base.', 'What should never get hit?', 1, '{"runners":[],"outs":0,"you":"batter","count":{"balls":0,"strikes":0}}'::jsonb, 'GGG.Cafe Offense IQ · Hit by pitch'),
  ('offense-2-01', 'general', null, 'offense', 2, null, 'Runner on second, nobody out. You hit right-handed.', 'What''s the most useful thing you can do?', array['Strike out so you don''t hit into an out', 'Pull the ball hard to the left side', 'Hit the ball to the right side of the infield so she can take third', 'Pop up so she stays at second'], 2, 'A ground ball to the right side moves her to third with one out, where a fly ball or ground ball can score her. A ground ball to the left side holds her at second.', 'From second, which infielders can she run behind?', 2, '{"runners":["second"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Move the runner from second'),
  ('offense-2-02', 'general', null, 'offense', 2, null, 'Runner on first, hit-and-run is on. The pitch is a little outside.', 'What do you do?', array['Take it: it''s a ball', 'Swing and put it on the ground to protect the runner', 'Bunt it foul', 'Swing as hard as you can for a home run'], 1, 'On a hit-and-run the runner is going, so you have to swing to protect her. Put the ball on the ground, ideally through the hole the middle infielder leaves.', 'What happens to the runner if you take the pitch?', 2, '{"runners":["first"],"outs":0,"you":"batter","count":{"balls":1,"strikes":0}}'::jsonb, 'GGG.Cafe Offense IQ · Hit-and-run'),
  ('offense-2-03', 'general', null, 'offense', 2, null, 'You show bunt, and both corner infielders charge hard. Your coach calls the slash.', 'What do you do?', array['Pull the bat back and chop or drive the ball past the charging corners', 'Take the pitch', 'Bunt it in the air', 'Bunt it anyway'], 0, 'The slash beats a crashing defense. Show bunt to pull the corners in, pull the bat back and swing down to drive the ball past them.', 'Where are the infielders when you pull the bat back?', 2, '{"runners":["first"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · The slash'),
  ('offense-2-04', 'general', null, 'offense', 2, null, 'The first baseman is charging and the second baseman is playing deep.', 'Where''s the best bunt for a hit?', array['Bunt it softly to the first baseman', 'Bunt it straight back to the catcher', 'Pop it up to third', 'Push it firmly past the pitcher toward the second baseman'], 3, 'A push bunt is hit firmer than a sacrifice. With the first baseman crashing and the second baseman deep, push it past the pitcher into the gap between them.', 'Which fielder is too far away to get to a firm bunt?', 2, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Push bunt'),
  ('offense-2-05', 'general', null, 'offense', 2, null, 'The suicide squeeze is on. The pitch comes in high and outside.', 'What do you do?', array['Step out of the box', 'Take it because it''s a ball', 'Get the bat on it any way you can and bunt it on the ground', 'Swing away'], 2, 'On a suicide squeeze the runner breaks as the pitch is released. If you miss or take the pitch she''s out at home, so get the bat on the ball no matter where it is.', 'Where is the runner when the pitch arrives?', 2, '{"runners":["third"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Suicide squeeze'),
  ('offense-2-06', 'general', null, 'offense', 2, null, 'You have two strikes and your coach still wants a bunt.', 'What happens if your bunt rolls foul?', array['It''s just a foul ball', 'It''s strike three: you''re out', 'You get another pitch', 'The runner can advance'], 1, 'A bunt that goes foul with two strikes is strike three. That''s why most coaches bunt earlier in the count.', 'Is a two-strike bunt foul treated like other fouls?', 2, '{"runners":["first"],"outs":0,"you":"batter","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Offense IQ · Bunting with two strikes'),
  ('offense-2-07', 'general', null, 'offense', 2, null, 'Runners on first and second, one out. You pop up in the infield and the umpire calls the infield fly.', 'What does that mean?', array['You''re out automatically, and runners may advance at their own risk', 'The ball is dead and everyone returns', 'You''re safe if the ball drops', 'The runners have to run'], 0, 'On an infield fly the batter is out whether or not it''s caught, so the defense can''t drop it for a cheap double play. Runners may advance at their own risk.', 'Why does the rule exist?', 2, '{"runners":["first","second"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Infield fly'),
  ('offense-2-08', 'general', null, 'offense', 2, null, 'Extra innings start with a runner on second and nobody out. You lead off.', 'What''s a common play here?', array['Take until you walk', 'Bunt for a hit toward the pitcher', 'Swing for the fences', 'Sacrifice bunt to move her to third'], 3, 'With a runner on second and nobody out, a sacrifice puts her on third with one out, where a fly ball, a ground ball or a squeeze can score her.', 'How many ways can she score from third with one out?', 2, '{"runners":["second"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Tiebreaker inning'),
  ('offense-2-09', 'general', null, 'offense', 2, null, 'Runner on second, nobody out, sacrifice on.', 'Where should the bunt go?', array['Straight to the catcher', 'To the first-base side', 'Toward third, so the third baseman has to field it', 'Back to the pitcher'], 2, 'Make the third baseman field the bunt. If she comes in for it, nobody is covering third and the runner moves up safely.', 'Who has to leave third base empty?', 2, '{"runners":["second"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Sacrifice with a runner on second'),
  ('offense-2-10', 'general', null, 'offense', 2, null, 'Runners on first and second, nobody out. Your coach calls the sacrifice.', 'Where''s the best place for the bunt?', array['In the air to the first baseman', 'Toward third, making the third baseman come off the bag', 'Back to the pitcher', 'Foul, to see what the defense does'], 1, 'Bunting to the third-base side forces the third baseman to field it, so she can''t take the force at third. The defense ends up taking the out at first.', 'Where is the force play the defense wants?', 2, '{"runners":["first","second"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Runners on first and second: the bunt'),
  ('offense-2-11', 'general', null, 'offense', 2, null, 'She has struck you out twice with a rise ball up at 0-2. You''re 0-2 again.', 'What do you do?', array['Lay off pitches above your hands and make her come down', 'Bunt with two strikes', 'Step out and argue the last call', 'Swing at the next high pitch: you''re due'], 0, 'Pitchers repeat what works. If her strikeout pitch is the rise ball up, know it''s coming and take it. Make her throw a strike.', 'What has she thrown you twice in this count?', 2, '{"runners":[],"outs":0,"you":"batter","count":{"balls":0,"strikes":2}}'::jsonb, 'GGG.Cafe Offense IQ · Lay off her out pitch'),
  ('offense-2-12', 'general', null, 'offense', 2, null, 'You''re a left-handed slapper. The third baseman is playing back.', 'What''s your best option?', array['Swing away for a home run', 'Take the first pitch', 'Hard slap at the shortstop', 'Soft slap or drag bunt toward third'], 3, 'A third baseman playing back can''t get to a soft slap or a drag bunt down the line in time to throw out a fast slapper.', 'Who has the longest way to come in?', 2, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Soft slap'),
  ('offense-2-13', 'general', null, 'offense', 2, null, 'You''re a slapper. The shortstop and third baseman both charge as she starts her motion.', 'What''s the play?', array['Pop it up over the pitcher', 'Bunt it to third', 'Hard slap on the ground past them, through the left side', 'Take the pitch'], 2, 'When the left side crashes, there''s open space behind them. A hard slap on the ground beats charging infielders.', 'Where is the open space when they charge?', 2, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Hard slap'),
  ('offense-2-14', 'general', null, 'offense', 2, null, '3-1 count, runner on first, nobody out. Your coach gives you the green light.', 'What''s your approach?', array['Swing at anything', 'Look for your pitch in your hot zone; if it''s not there, take it', 'Bunt it', 'Take no matter what'], 1, 'A green light at 3-1 means you''re hunting one pitch. If it''s in your zone, drive it; if not, a walk still puts two on.', 'Who has to throw a strike?', 2, '{"runners":["first"],"outs":0,"you":"batter","count":{"balls":3,"strikes":1}}'::jsonb, 'GGG.Cafe Offense IQ · Green light at 3-1'),
  ('offense-2-15', 'general', null, 'offense', 2, null, 'Two outs, runner on second, first base open. The batter behind you is struggling.', 'What should you expect, and how do you handle it?', array['She may pitch around you; stay disciplined and take the walk if she won''t give you a strike', 'Bunt to keep the inning going', 'Swing at everything to avoid a walk', 'She''ll throw you strikes: swing early'], 0, 'With first base open and a weaker hitter next, pitchers often work the corners. Don''t chase. Take your walk and let your teammate hit with two on.', 'Why might she not want to throw you a strike?', 2, '{"runners":["second"],"outs":2,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Pitching around you'),
  ('offense-2-16', 'general', null, 'offense', 2, null, 'Bases loaded, nobody out.', 'What does the defense want, and what do you want?', array['They want a fly ball; you want a bunt', 'They want a walk; you want a strikeout', 'They want a strikeout; you want a walk', 'They want a ground ball for a double play; you want a ball hit hard or in the air to the outfield'], 3, 'With the bases loaded the defense can turn a double play on a ground ball. A line drive or a fly ball to the outfield scores a run without the double play.', 'Which kind of ball gives the defense two outs?', 2, '{"runners":["first","second","third"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Bases loaded, nobody out'),
  ('offense-2-17', 'general', null, 'offense', 2, null, 'Runner on third, one out, early in the game. The infield stays back, willing to trade the run for an out.', 'Which out still scores the run?', array['A strikeout', 'A pop-up to the second baseman', 'A ground ball to the shortstop or second baseman', 'A line drive caught by the third baseman'], 2, 'With the infield back, a ground ball to the middle infield scores the runner even though you''re out at first. That''s a productive out.', 'Where is the defense willing to give up the run?', 2, '{"runners":["third"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · The productive out'),
  ('offense-2-18', 'general', null, 'offense', 2, null, 'It''s the 7th. Her fastball is slower and her change-up is staying up.', 'What''s the adjustment?', array['Take more pitches to tire her out', 'Be ready to attack early in the count: pitches are staying up', 'Bunt every time', 'Move to the back of the box'], 1, 'A tired pitcher leaves the ball up. Be on time and aggressive early in the count before she finds her rhythm again.', 'What happens to her pitches when she tires?', 2, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · A tiring pitcher'),
  ('offense-2-19', 'general', null, 'offense', 2, null, 'Runner on first, hit-and-run. You see the second baseman break to cover second.', 'Where should you hit the ball?', array['Through the right side, where the second baseman just left', 'To the third baseman', 'In the air to left field', 'Up the middle'], 0, 'When the second baseman covers, a hole opens on the right side. Hitting behind the runner there moves her to third.', 'Which spot just opened?', 2, '{"runners":["first"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Hit behind the runner on the steal'),
  ('offense-2-20', 'general', null, 'offense', 2, null, 'Down one in the 6th. Runner on first, nobody out. Your coach asks you to bunt.', 'Why might the coach want the bunt?', array['To make the pitcher throw more pitches', 'To end the inning', 'To play for a big inning', 'To get the tying run into scoring position'], 3, 'Late in a close game, one run matters most. A sacrifice puts the tying run on second, where one hit scores her.', 'Where can a single score her?', 2, '{"runners":["first"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Late in a close game'),
  ('offense-3-01', 'general', null, 'offense', 3, null, 'The defense moves the second baseman toward first and the shortstop up the middle every time you hit.', 'What''s your best adjustment?', array['Bunt to the pitcher', 'Don''t swing', 'Hit it right at them to prove a point', 'Use the open side: let the ball travel and hit it where they aren''t'], 3, 'A shift takes away your pull side and opens the other side. Let the ball get deeper and drive it where the defense isn''t.', 'Which side did they leave open?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Beat the shift'),
  ('offense-3-02', 'general', null, 'offense', 3, null, 'The catcher sets up outside on every pitch to you.', 'How do you adjust?', array['Stand farther from the plate', 'Crowd the plate and expect inside pitches', 'Expect pitches away: let the ball travel and drive it the other way', 'Swing at the first pitch no matter what'], 2, 'If they''re living outside, look away. Let the ball travel and drive it to the opposite field instead of rolling it over.', 'Where is she most likely to throw?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Catcher sets up away'),
  ('offense-3-03', 'general', null, 'offense', 3, null, 'Two outs, runner on second, 2-0 count.', 'What''s your plan?', array['Take a strike to see a pitch', 'Sit on your pitch in your hot zone and drive it if it''s there', 'Bunt for a hit', 'Swing at anything to drive in the run'], 1, 'At 2-0 she has to come to you. Look for one pitch in one zone and attack it. If it isn''t there, let it go: 3-0 is still your count.', 'Who has to give in at 2-0?', 3, '{"runners":["second"],"outs":2,"you":"batter","count":{"balls":2,"strikes":0}}'::jsonb, 'GGG.Cafe Offense IQ · Ahead with a runner in scoring position'),
  ('offense-3-04', 'general', null, 'offense', 3, null, 'You notice the pitcher''s glove flares every time she throws her change-up.', 'What do you do with that?', array['Tell your coach and look for the change when you see it', 'Yell it out to the pitcher', 'Tell the umpire', 'Ignore it'], 0, 'Reading a tipped pitch is part of the game. Share it with your coach and teammates, and sit on the change-up when you see the tell.', 'Who should know before your next at-bat?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · A tipped pitch'),
  ('offense-3-05', 'general', null, 'offense', 3, null, 'Runners on first and third, one out. The infield is at double-play depth.', 'What''s your best result short of a hit?', array['A strikeout so nobody gets doubled up', 'A pop-up to the first baseman', 'A ground ball to the shortstop', 'A fly ball to the outfield: the run scores on the tag and there''s no double play'], 3, 'At double-play depth a ground ball can end the inning. A fly ball deep enough scores the runner from third and avoids the double play.', 'What does double-play depth tell you they want?', 3, '{"runners":["first","third"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Corners and the double play'),
  ('offense-3-06', 'general', null, 'offense', 3, null, 'You''re facing a pitcher with a sharp drop ball.', 'Where in the box can help?', array['Stand on top of the plate', 'Stand as far away as allowed', 'Move up in the box to hit the pitch before it drops', 'Move to the very back of the box'], 2, 'Moving up in the box lets you hit the drop ball before it breaks all the way, when it''s still at the bottom of the zone instead of in the dirt.', 'When is a drop ball easiest to hit?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Drop-ball pitcher'),
  ('offense-3-07', 'general', null, 'offense', 3, null, 'This pitcher throws her change-up whenever she falls behind. It''s 2-0.', 'What do you look for?', array['Her best fastball', 'The change-up: stay back and wait for it', 'A pitch in the dirt', 'Nothing: take the pitch'], 1, 'Pitchers have patterns. If she goes to the change when she''s behind, sit on it: stay back, keep your hands back and drive it.', 'What does she do when she''s behind?', 3, '{"runners":[],"outs":0,"you":"batter","count":{"balls":2,"strikes":0}}'::jsonb, 'GGG.Cafe Offense IQ · Behind-in-the-count change-ups'),
  ('offense-3-08', 'general', null, 'offense', 3, null, 'Runner on second, nobody out. You''re a slapper and the defense expects the slap.', 'What''s the best way to move the runner?', array['Slap or bunt to the third-base side so the third baseman has to come in', 'Hard slap at the pitcher', 'Pop it up', 'Take until you walk'], 0, 'Making the third baseman come in to field the ball leaves third base open for the runner from second.', 'Who has to leave third base?', 3, '{"runners":["second"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Slapper, runner on second'),
  ('offense-3-09', 'general', null, 'offense', 3, null, 'Tie game, bottom of the 7th, runner on third, one out. The infield is in.', 'What are you looking for?', array['Only a home run', 'A walk', 'A bunt back to the pitcher', 'A pitch to drive in the air to the outfield or hard on the ground'], 3, 'A fly ball deep enough or a hard ground ball through a drawn-in infield wins it. Look for a pitch you can drive and stay on top of high pitches.', 'What kinds of contact score her?', 3, '{"runners":["third"],"outs":1,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Walk-off chance'),
  ('offense-3-10', 'general', null, 'offense', 3, null, 'Down two in the last inning. You lead off, nobody on, 3-1 count.', 'What''s the mindset?', array['Swing at the first pitch no matter what', 'Swing at anything for a home run', 'Be selective: you need baserunners, so make her throw a strike', 'Bunt for a hit'], 2, 'One run doesn''t tie it. Baserunners do. Don''t help a pitcher who''s behind: make her throw a strike, and take the walk if she won''t.', 'What does your team need most right now?', 3, '{"runners":[],"outs":0,"you":"batter","count":{"balls":3,"strikes":1}}'::jsonb, 'GGG.Cafe Offense IQ · Down two, leading off'),
  ('offense-3-11', 'general', null, 'offense', 3, null, 'Tie game in the 7th, two outs, nobody on.', 'What''s your goal?', array['Bunt for a hit', 'Look for a pitch you can drive for extra bases', 'Take until you walk', 'Strike out swinging'], 1, 'With two outs and nobody on, a double puts the winning run in scoring position for one more hit. Hunt a pitch you can drive.', 'How far does the winning run have to get to score on a single?', 3, '{"runners":[],"outs":2,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Two outs, tie game'),
  ('offense-3-12', 'general', null, 'offense', 3, null, 'The other team brings in a new pitcher late in the game.', 'What should you do before your first at-bat against her?', array['Watch her warm-ups from the dugout and on deck: time her, see her pitches', 'Talk to the umpire', 'Ask the catcher what she throws', 'Nothing: just swing'], 0, 'Her warm-ups are your scouting report. Time her release and see what moves so your first look isn''t in the box.', 'Where can you see her pitches before you hit?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · New pitcher'),
  ('offense-3-13', 'general', null, 'offense', 3, null, 'As a slapper you see the shortstop break in early, before the pitch.', 'Where''s the hole?', array['Back to the pitcher', 'Down the first-base line', 'Over the catcher', 'Behind the shortstop, through the left side'], 3, 'When the shortstop crashes early, she leaves the left side open behind her. A hard slap through that hole is a hit.', 'Where did she just leave?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Hard slap at the crash'),
  ('offense-3-14', 'general', null, 'offense', 3, null, 'The pitcher has thrown 25 pitches in the first inning. You''re up with nobody on.', 'What helps your team?', array['Strike out quickly', 'Swing at the first pitch', 'Work the count: make her throw strikes and keep her pitch count climbing', 'Bunt'], 2, 'A pitcher who''s laboring tires faster. A long at-bat, even an out, keeps her working and helps every hitter after you.', 'What happens to a pitcher who throws too many pitches early?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Pitch count'),
  ('offense-3-15', 'general', null, 'offense', 3, null, 'The defense seems to know when your team bunts.', 'What should your team do?', array['Keep the same signs', 'Tell your coach so the signs can change or an indicator can be added', 'Stop bunting forever', 'Bunt every pitch'], 1, 'If the defense is reading your signs, your coach can switch to new signs or add an indicator. Tell her what you''re seeing.', 'Who can change the signs?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Sign security'),
  ('offense-3-16', 'general', null, 'offense', 3, null, 'Runner on first, nobody out. The corners are playing back and your coach wants them in.', 'What can you do?', array['Show bunt early on the first pitch to pull them in', 'Swing away on the first pitch', 'Step out every pitch', 'Ask the umpire to move them'], 0, 'Showing bunt early brings the corners in. Once they''re charging, a slash or a hit past them has more room.', 'What makes the corners come in?', 3, '{"runners":["first"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Fake bunt to move the defense'),
  ('offense-3-17', 'general', null, 'offense', 3, null, 'The umpire is calling the low pitch a strike today.', 'How do you adjust with two strikes?', array['Complain after each call', 'Move back in the box', 'Ignore it and keep your normal zone', 'Widen your zone down: protect the low pitch'], 3, 'Adjust to today''s zone. If the low pitch is a strike, you have to protect it with two strikes instead of taking it.', 'Who decides today''s strike zone?', 3, '{"runners":[],"outs":0,"you":"batter","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Offense IQ · Strike zone this game'),
  ('offense-3-18', 'general', null, 'offense', 3, null, 'Runner on first. She''s stealing on this pitch and you get a pitch you don''t like.', 'What do you do?', array['Bunt it foul', 'Swing at it to distract the catcher', 'Take it, and stay in the box without blocking the catcher''s throw', 'Step across the plate'], 2, 'Unless it''s a hit-and-run, let your runner steal. Take the pitch and don''t step into the catcher''s throwing lane.', 'Is this a hit-and-run?', 3, '{"runners":["first"],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Runner going on the pitch'),
  ('offense-3-19', 'general', null, 'offense', 3, null, 'Before the game you notice the left fielder plays very shallow.', 'How can that help you?', array['It doesn''t matter', 'A line drive or fly ball over her head can go for extra bases', 'Bunt every time', 'Only hit to the right side'], 1, 'A shallow outfielder takes away bloopers but leaves the space behind her. A hard line drive or fly ball over her head is extra bases.', 'What space did she give up?', 3, '{"runners":[],"outs":0,"you":"batter"}'::jsonb, 'GGG.Cafe Offense IQ · Scouting the defense'),
  ('offense-3-20', 'general', null, 'offense', 3, null, 'Two strikes against a pitcher who lives up in the zone.', 'What''s a smart two-strike adjustment?', array['Shorten up and stay on top of the ball; lay off the high ones', 'Bunt', 'Take until you walk', 'Swing at anything high'], 0, 'Shorten your swing and stay on top of the ball. High pitches are her chase pitch; with a short swing you can still fight off strikes.', 'Where does she want you to swing?', 3, '{"runners":[],"outs":0,"you":"batter","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Offense IQ · Two strikes against a rise-ball pitcher'),
  ('battery-1-01', 'general', null, 'battery', 1, null, 'First pitch to the leadoff hitter.', 'What''s your goal with this pitch?', array['Throw your hardest pitch right down the middle', 'Throw a change-up in the dirt', 'Throw a quality strike you command', 'Waste a pitch to see if she swings'], 2, 'Getting ahead 0-1 changes the whole at-bat: hitters do far less damage when they''re behind. Throw a quality strike with a pitch you command.', 'Whose count is 0-1?', 1, '{"runners":[],"outs":0,"you":"P","count":{"balls":0,"strikes":0}}'::jsonb, 'GGG.Cafe Battery IQ · First-pitch strikes'),
  ('battery-1-02', 'general', null, 'battery', 1, null, 'You''re ahead 0-2.', 'What''s the smartest pitch?', array['A fastball down the middle to finish her', 'A pitch just off the plate she might chase, thrown with purpose', 'A pitch way outside so you don''t give up a hit', 'Whatever the catcher didn''t call last time'], 1, 'Ahead 0-2 you don''t have to throw a strike. Throw a pitch that looks like one and ends just off the plate, where a swing is weak contact or a miss.', 'Does she have to swing at a ball?', 1, '{"runners":[],"outs":0,"you":"P","count":{"balls":0,"strikes":2}}'::jsonb, 'GGG.Cafe Battery IQ · 0-2: make her chase'),
  ('battery-1-03', 'general', null, 'battery', 1, null, 'You''ve fallen behind 3-1 with nobody on.', 'What''s the pitch?', array['Your most reliable pitch for a strike, on a corner if you can', 'Your newest pitch', 'A pitch in the dirt', 'A pitch way inside'], 0, 'Behind in the count, throw the pitch you trust most for a strike. A walk puts a free runner on; a strike gets you back in the at-bat.', 'Which pitch do you trust most?', 1, '{"runners":[],"outs":0,"you":"P","count":{"balls":3,"strikes":1}}'::jsonb, 'GGG.Cafe Battery IQ · Avoid 3-ball counts'),
  ('battery-1-04', 'general', null, 'battery', 1, null, 'First batter of the inning, 2-0 count.', 'Why does this hitter matter so much?', array['You should walk her to set up a double play', 'The leadoff hitter can''t steal', 'She doesn''t: the leadoff hitter rarely scores', 'A leadoff walk scores far more often than you''d think, so attack the zone'], 3, 'Free runners to start an inning come around to score a lot. Make the leadoff hitter earn her way on: attack the zone with pitches you command.', 'What does a free runner do to an inning?', 1, '{"runners":[],"outs":0,"you":"P","count":{"balls":2,"strikes":0}}'::jsonb, 'GGG.Cafe Battery IQ · Leadoff walks'),
  ('battery-1-05', 'general', null, 'battery', 1, null, 'You''re catching and the pitcher keeps missing your spot.', 'What helps her most?', array['Stand up between pitches', 'Move your glove around after she releases', 'Give a clear, still target early and keep it there', 'Set up behind the batter'], 2, 'A big, still target gives the pitcher something to throw to. Moving the glove late or a lazy target makes it harder to hit spots.', 'What is she aiming at?', 1, '{"runners":[],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Catcher''s target'),
  ('battery-1-06', 'general', null, 'battery', 1, null, 'Hitters are timing your fastball well.', 'What does the change-up do?', array['It''s only for when you''re tired', 'It looks like a fastball out of your hand, then arrives late and ruins timing', 'It''s thrown harder than your fastball', 'It always breaks into the dirt'], 1, 'A change-up uses the same arm speed and motion as your fastball but arrives later. Hitters who are on time for the fastball end up out in front.', 'What do hitters see when you release it?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Why the change-up'),
  ('battery-1-07', 'general', null, 'battery', 1, null, 'You have a rise ball that climbs out of the zone.', 'When is it most effective?', array['When you''re ahead, to get a swing and miss above the hands', 'On 3-0 for a called strike', 'Only with nobody on', 'To get a ground ball for a double play'], 0, 'A rise ball works best as a chase pitch when you''re ahead: it starts like a strike and finishes above the hands, where swings miss or pop up.', 'Where does it finish?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · When to throw the rise'),
  ('battery-1-08', 'general', null, 'battery', 1, null, 'Runner on first, one out.', 'Which pitch gives you the best chance at a double-play ground ball?', array['A change-up up', 'A pitch high and outside', 'A rise ball up', 'A drop ball low in the zone'], 3, 'The drop ball lives low, and low pitches get ground balls. A ground ball to the middle infield is your double-play chance.', 'Which pitch gets hitters to hit the top of the ball?', 1, '{"runners":["first"],"outs":1,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · When to throw the drop'),
  ('battery-1-09', 'general', null, 'battery', 1, null, 'Your defense has been flat behind you the last two innings.', 'What can you do as the pitcher?', array['Step off after every pitch', 'Slow down between every pitch', 'Work quickly and stay in a rhythm: get the ball, get the sign, go', 'Throw to first more often'], 2, 'A pitcher who works at a good pace keeps the defense on its toes and the hitter from getting comfortable.', 'What happens to fielders during long breaks?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Tempo'),
  ('battery-1-10', 'general', null, 'battery', 1, null, 'The batter stands right on top of the plate.', 'Where should you work?', array['Only outside', 'Inside, to take away her space, then use the outside corner', 'Down the middle', 'Only change-ups'], 1, 'A hitter crowding the plate wants the outside pitch. Pitch inside to move her off the plate, then the outside corner is a weapon again.', 'What is she trying to reach?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Hitter crowds the plate'),
  ('battery-1-11', 'general', null, 'battery', 1, null, 'The batter stands far from the plate.', 'Where is she weakest?', array['The outside corner', 'Down the middle', 'High and inside', 'Inside'], 0, 'Standing off the plate makes the outside corner hard to reach. Work away and make her extend.', 'Which pitch is hardest to reach from there?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Hitter far off the plate'),
  ('battery-1-12', 'general', null, 'battery', 1, null, 'Runner on first, nobody out. The batter squares early to bunt.', 'Which pitch makes a good bunt hardest?', array['A pitch right at the belt', 'A slow pitch down the middle', 'Any pitch: it doesn''t matter', 'A high pitch: it''s hard to bunt down on the ground'], 3, 'High pitches are tough to bunt down, so they often turn into pop-ups. Make her bunt a pitch up in the zone.', 'What happens when you bunt a high pitch?', 1, '{"runners":["first"],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Sacrifice coming'),
  ('battery-1-13', 'general', null, 'battery', 1, null, 'You''re catching. Strike three bounces off your shin, first base is empty, one out.', 'What do you do?', array['Ask the umpire', 'Nothing: the batter is out', 'Get the ball and tag the batter or throw to first', 'Roll the ball to the circle'], 2, 'With first base open (or two outs), the batter can run on a dropped third strike. Pick it up and tag her or throw to first to finish the out.', 'Is the out finished if strike three isn''t caught?', 1, '{"runners":[],"outs":1,"you":"C","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Battery IQ · Dropped third strike'),
  ('battery-1-14', 'general', null, 'battery', 1, null, 'You just released the pitch.', 'What''s your job now?', array['Watch the hitter', 'Get set to field: you''re the fifth infielder', 'Walk back to the rubber', 'Look at your coach'], 1, 'After the pitch, you''re a fielder 43 feet from home. Land balanced with your glove ready for a comebacker or a bunt.', 'Who''s closest to the hitter after the catcher?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Fifth infielder'),
  ('battery-1-15', 'general', null, 'battery', 1, null, 'You''re not sure what pitch was called.', 'What do you do?', array['Step off, reset and get the sign again', 'Throw a fastball down the middle', 'Shake your head at the catcher', 'Throw what you think it was'], 0, 'Never throw a pitch you''re unsure of: a cross-up can mean a passed ball or a hit batter. Step off and get the sign again.', 'What can go wrong on a cross-up?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Agree on the pitch'),
  ('battery-1-16', 'general', null, 'battery', 1, null, '2-0 count to a good hitter, nobody on.', 'What do you throw?', array['A pitch in the dirt', 'An intentional ball', 'A pitch right down the middle so you don''t fall behind 3-0', 'A strike to a corner with a pitch you command'], 3, 'She''s looking for something to drive. Throw a strike, but put it on a corner with a pitch you command rather than over the middle.', 'What is she hoping you''ll throw?', 1, '{"runners":[],"outs":0,"you":"P","count":{"balls":2,"strikes":0}}'::jsonb, 'GGG.Cafe Battery IQ · 2-0 to a good hitter'),
  ('battery-1-17', 'general', null, 'battery', 1, null, 'Late in a long tournament day your pitches are flattening out and you''re missing up.', 'What do you do?', array['Throw only change-ups', 'Keep quiet and keep throwing', 'Tell your coach: location and movement slip when you''re tired', 'Throw harder'], 2, 'Fatigue shows up as lost movement and location. Your coach needs to know so she can plan, and so you don''t get hurt.', 'Who needs to know how you feel?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Tired arm'),
  ('battery-1-18', 'general', null, 'battery', 1, null, 'You just gave up a double.', 'What''s next?', array['Throw harder at the next hitter', 'Use your reset: a breath, a release, and win the next pitch', 'Look at the dugout', 'Rush the next pitch'], 1, 'The double is over. Your reset gets you back to green so the next pitch gets your full focus.', 'Which pitch can you still win?', 1, '{"runners":["second"],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Reset after a hit'),
  ('battery-1-19', 'general', null, 'battery', 1, null, 'There''s a runner on second who can see the catcher''s signs.', 'What should the battery do?', array['Switch to a sign sequence or indicator so the runner can''t relay the pitch', 'Stop using signs', 'Yell the pitch', 'Use the same simple signs'], 0, 'From second, a runner can see the catcher''s signs and tell the hitter. Use a sequence or an indicator so the real sign is hidden.', 'Who can see the signs from second?', 1, '{"runners":["second"],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Sign security'),
  ('battery-1-20', 'general', null, 'battery', 1, null, 'Your scouting report says this hitter can''t catch up to the inside fastball.', 'What''s the plan?', array['Throw only change-ups', 'Walk her', 'Never throw her inside', 'Work her inside with hard stuff, and change eye levels with it'], 3, 'Pitch to the weakness. If she can''t get to the hard inside pitch, make her prove it, and use other pitches to keep her from sitting on it.', 'Where is she late?', 1, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Pitching to a hitter''s weakness'),
  ('battery-2-01', 'general', null, 'battery', 2, null, 'You just struck a hitter out with a rise ball up.', 'Why does a drop ball low make your rise better?', array['Low pitches are always strikes', 'The umpire likes it', 'It doesn''t: throw rise balls only', 'Changing eye levels makes each pitch harder to read'], 3, 'Up then down makes the hitter adjust her eyes and her swing plane. Each pitch looks more like a strike next to the other.', 'What does the hitter have to adjust?', 2, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Change eye levels'),
  ('battery-2-02', 'general', null, 'battery', 2, null, 'You throw a fastball and a change-up from the same release.', 'Why does it matter that they look the same early?', array['It''s required by the rules', 'It doesn''t matter', 'The hitter can''t tell which pitch is coming until it''s too late', 'It makes the change-up faster'], 2, 'Pitches that start on the same line and from the same motion force the hitter to guess. By the time they separate, it''s too late to adjust.', 'When does the hitter decide to swing?', 2, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Tunneling'),
  ('battery-2-03', 'general', null, 'battery', 2, null, 'A fast left-handed slapper is up.', 'What''s a good plan?', array['Pitch her outside and slow', 'Work inside and up, and change speeds to upset her timing', 'Throw only drop balls away', 'Walk her'], 1, 'Slappers want the outside pitch they can run into. Inside pitches jam her and pitches up are hard to slap down; changing speeds ruins her timing.', 'Which pitch is she hoping to run into?', 2, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Pitching to a slapper'),
  ('battery-2-04', 'general', null, 'battery', 2, null, 'The hitter is late on your fastball, fouling it to the opposite side.', 'What do you throw next?', array['Another hard pitch: she isn''t catching up', 'A pitch in the dirt', 'A soft pitch down the middle', 'A change-up'], 0, 'If she''s late on your heat, don''t speed her bat up with a change-up. Stay hard until she proves she can catch up.', 'What does a change-up do to a late hitter?', 2, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Late on the fastball'),
  ('battery-2-05', 'general', null, 'battery', 2, null, 'The hitter is out in front, pulling everything foul.', 'What''s the adjustment?', array['Throw slower', 'Throw it down the middle', 'Throw another change-up', 'Go hard and inside, or work away where she can''t pull it'], 3, 'A hitter who''s early is waiting on slow pitches. Speed and location away take the pull side from her.', 'What is she sitting on?', 2, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Out in front'),
  ('battery-2-06', 'general', null, 'battery', 2, null, 'Tie game, 6th inning, runner on third, one out. The infield is in.', 'What do you want the hitter to do?', array['Bunt', 'Hit a fly ball', 'Hit a ground ball: keep the ball down', 'Walk'], 2, 'A fly ball scores the run. Pitch down in the zone for ground balls your drawn-in infield can turn into an out at home.', 'What kind of ball scores her from third?', 2, '{"runners":["third"],"outs":1,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Runner on third, infield in'),
  ('battery-2-07', 'general', null, 'battery', 2, null, 'The count is 1-1.', 'Why is this pitch so important?', array['It isn''t', '1-2 and 2-1 are very different at-bats', 'It decides the walk', 'It''s the only pitch the umpire watches'], 1, 'After 1-1 you''re either ahead 1-2 (her best pitch can be a ball) or behind 2-1 (you have to come to her). Win this pitch.', 'What are the two counts it can become?', 2, '{"runners":[],"outs":0,"you":"P","count":{"balls":1,"strikes":1}}'::jsonb, 'GGG.Cafe Battery IQ · Win the 1-1 pitch'),
  ('battery-2-08', 'general', null, 'battery', 2, null, 'You''ve started every hitter this inning with a drop ball.', 'What''s the risk?', array['Hitters notice patterns and start sitting on it', 'The umpire will call it a ball', 'The catcher gets tired', 'None: it''s working'], 0, 'A pattern turns your best pitch into a guess the hitter wins. Mix first pitches and sequences.', 'What does the dugout notice?', 2, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Patterns'),
  ('battery-2-09', 'general', null, 'battery', 2, null, 'You''re catching. The runner on first takes a big step off the bag after every pitch.', 'What can you do?', array['Tell the umpire', 'Throw to second', 'Nothing', 'Back-pick: throw behind her to first with the first baseman covering'], 3, 'A runner wandering off after the pitch is a back-pick chance. With your first baseman ready, a quick throw behind her can get an out.', 'Where is she when you catch the pitch?', 2, '{"runners":["first"],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Back-pick'),
  ('battery-2-10', 'general', null, 'battery', 2, null, 'You''re catching a pitch at the bottom of the zone.', 'How do you give it the best chance to be a strike?', array['Stab down at it', 'Catch it with one knee up and move toward it late', 'Catch it with your glove under the ball and keep it still', 'Snatch it up into the zone'], 2, 'Get your glove under the low pitch and receive it quietly. Yanking or stabbing it makes it look like a ball.', 'What does the umpire see when you move it?', 2, '{"runners":[],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Receiving the low pitch'),
  ('battery-2-11', 'general', null, 'battery', 2, null, 'Runner on third. Your pitcher throws her drop ball.', 'If it bounces, what''s your job?', array['Try to catch it with your glove only', 'Block it: drop to your knees, glove between your legs, chest over the ball, keep it in front', 'Let it go to the backstop', 'Stand up'], 1, 'With a runner on third, keeping the ball in front saves a run. Block with your body and smother it.', 'Where does the run come from if it gets by?', 2, '{"runners":["third"],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Blocking'),
  ('battery-2-12', 'general', null, 'battery', 2, null, 'Runner on third. The pitch gets past the catcher to the backstop.', 'What does the pitcher do?', array['Sprint to cover home and take the catcher''s throw', 'Back up third', 'Go to first', 'Stay in the circle'], 0, 'On a wild pitch or passed ball with a runner on third, the pitcher covers home for the catcher''s throw.', 'Who''s left to cover the plate?', 2, '{"runners":["third"],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Cover home'),
  ('battery-2-13', 'general', null, 'battery', 2, null, 'Two outs, runners on first and second, full count.', 'What''s the pitch?', array['A waste pitch', 'A brand-new pitch', 'A pitch you might bounce', 'Your most reliable strike'], 3, 'With runners moving on the pitch, a walk loads the bases and a strike ends the inning. Throw the pitch you trust most for a strike.', 'What does each result do?', 2, '{"runners":["first","second"],"outs":2,"you":"P","count":{"balls":3,"strikes":2}}'::jsonb, 'GGG.Cafe Battery IQ · Full count, two outs, runners going'),
  ('battery-2-14', 'general', null, 'battery', 2, null, 'The scouting report shows this hitter crushes pitches up and in.', 'How do you pitch her?', array['Walk her every time', 'Up and in to challenge her', 'Keep the ball away from up and in, and make her hit your pitch', 'Only change-ups'], 2, 'Don''t feed a hitter her favorite pitch. Work the zones she struggles with and use your best pitches there.', 'Where does she do damage?', 2, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Stay out of her hot zone'),
  ('battery-2-15', 'general', null, 'battery', 2, null, 'You expect the runner on first to steal and your coach calls a pitchout.', 'Where does the pitch go?', array['Down the middle', 'Wide of the plate where the catcher can catch it standing and throw', 'In the dirt', 'At the batter'], 1, 'A pitchout is a fastball well outside, so the catcher can catch it moving toward second and make a strong throw.', 'What does the catcher need to throw quickly?', 2, '{"runners":["first"],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Pitchout for the steal'),
  ('battery-2-16', 'general', null, 'battery', 2, null, 'Your best hitter on the other side fouled off three fastballs in a row.', 'What do you throw?', array['A change-up or a pitch on a different eye level', 'A pitch at her', 'Nothing: call time', 'A fourth fastball in the same spot'], 0, 'She''s on time for your fastball. Change her timing or her eye level; give her something different to hit.', 'What is she timed to?', 2, '{"runners":[],"outs":0,"you":"P","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Battery IQ · Changing speeds on a good hitter'),
  ('battery-2-17', 'general', null, 'battery', 2, null, 'Runners on first and second, nobody out, the batter squares.', 'What pitch helps your defense most?', array['A slow pitch down the middle', 'A pitch in the dirt', 'A pitch at her hands', 'A high strike that''s hard to bunt on the ground'], 3, 'A high strike is hard to bunt down and often pops up. Throw it, then get off the mound to field.', 'Which bunts become pop-ups?', 2, '{"runners":["first","second"],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Bunt coverage call'),
  ('battery-2-18', 'general', null, 'battery', 2, null, 'Your pitcher has walked two in a row and looks rattled.', 'As the catcher, what''s helpful?', array['Ask the coach to take her out', 'Ignore it', 'Go out (if allowed), say something short and simple, and give her one target', 'Yell at her from behind the plate'], 2, 'A quick visit with one clear thought (breathe, hit the glove) can reset a pitcher. Keep it short and positive.', 'What does she need to hear?', 2, '{"runners":["first","second"],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Catcher talks to the pitcher'),
  ('battery-2-19', 'general', null, 'battery', 2, null, 'Runner on first, one out. A hard ground ball comes right back to you in the circle.', 'Where''s your throw?', array['First base', 'Second base, to start the double play', 'Home', 'Hold the ball'], 1, 'A comebacker with a runner on first is a double-play ball. Turn and throw to the infielder covering second and let her finish it.', 'Which out can start two?', 2, '{"runners":["first"],"outs":1,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Comebacker double play'),
  ('battery-2-20', 'general', null, 'battery', 2, null, 'Bases loaded, nobody out.', 'What are you trying to get?', array['A ground ball for a force at home or a double play', 'A fly ball', 'A walk', 'A strikeout only'], 0, 'With the bases loaded and nobody out, a ground ball gives your defense a force at home and maybe two outs.', 'Where are all the force plays?', 2, '{"runners":["first","second","third"],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Ground ball pitch with the bases loaded'),
  ('battery-3-01', 'general', null, 'battery', 3, null, 'You''re facing the top of the order for the third time.', 'What should change?', array['Change your sequences: they''ve seen your pattern', 'Throw only fastballs', 'Pitch slower', 'Nothing: it''s worked twice'], 0, 'Hitters learn from each at-bat. The third time through, change first pitches and sequences so they can''t sit on what worked before.', 'What have they learned so far?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Third time through'),
  ('battery-3-02', 'general', null, 'battery', 3, null, 'The hitter is sitting on your fastball in fastball counts.', 'What''s pitching backward?', array['Throwing from the back of the rubber', 'Throwing only balls', 'Throwing behind the runner', 'Throwing off-speed in counts where she expects a fastball'], 3, 'Pitching backward means off-speed when she expects heat. A change-up at 2-0 to a hitter sitting fastball can steal a strike.', 'What does she expect at 2-0?', 3, '{"runners":[],"outs":0,"you":"P","count":{"balls":2,"strikes":0}}'::jsonb, 'GGG.Cafe Battery IQ · Pitching backward'),
  ('battery-3-03', 'general', null, 'battery', 3, null, 'Two strikes on a hitter who has handled every low pitch.', 'What''s the putaway?', array['A pitch at her feet', 'Another low pitch', 'A rise ball just above her hands', 'A change-up down the middle'], 2, 'If she owns the low pitch, change her eye level: a rise ball just above the hands is hard to lay off and harder to square up.', 'Where has she been all day?', 3, '{"runners":[],"outs":0,"you":"P","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Battery IQ · Elevate with two strikes'),
  ('battery-3-04', 'general', null, 'battery', 3, null, 'The hitter''s front foot opens toward third as she strides (she hits right-handed).', 'Where is she weakest?', array['Inside', 'Away', 'Up and in', 'Down the middle'], 1, 'A hitter who pulls off with her front side can''t cover the outside corner well. Work away.', 'Which way is her body going?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Reading the feet'),
  ('battery-3-05', 'general', null, 'battery', 3, null, 'After your drop ball got her twice, the hitter moves up in the box.', 'What''s she doing, and how do you answer?', array['She''s trying to hit the drop before it breaks; go up with the rise or hard inside', 'She''s leaving; throw a strike', 'Nothing changes', 'She wants your change-up; throw it'], 0, 'Moving up lets her hit the drop early. Answer with pitches up or hard inside, which are harder to handle that close.', 'Which pitch does moving up help her hit?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Hitter moves up in the box'),
  ('battery-3-06', 'general', null, 'battery', 3, null, 'A hitter moves to the back of the box against your speed.', 'What''s the answer?', array['Pitch outside only', 'Rise balls only', 'More fastballs', 'Change speeds: she''s giving herself time for the hard pitch'], 3, 'Backing up buys time against velocity. A change-up punishes it, because she''s ready for heat.', 'What did she just buy herself?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Hitter backs off in the box'),
  ('battery-3-07', 'general', null, 'battery', 3, null, 'A fast runner on first is likely to steal.', 'What helps your catcher throw her out?', array['Don''t call anything', 'Call change-ups', 'Call pitches with speed that your catcher can handle cleanly', 'Call pitches in the dirt'], 2, 'A slow pitch gives the runner extra time. With a likely steal, faster pitches give your catcher her best chance.', 'Which pitch takes longest to reach the catcher?', 3, '{"runners":["first"],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Pitch calling with a base stealer'),
  ('battery-3-08', 'general', null, 'battery', 3, null, 'The other coach seems to know where you''re pitching.', 'What could be giving it away?', array['Nothing', 'The catcher setting up early, before the pitcher starts her motion', 'The color of the ball', 'The umpire'], 1, 'If the catcher moves to her spot too early, the hitter or coach can see the location. Set up late, as the pitcher begins her motion.', 'When does the catcher move to her target?', 3, '{"runners":[],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Setting up too early'),
  ('battery-3-09', 'general', null, 'battery', 3, null, 'Your coach says your glove opens wider before every change-up.', 'What''s the fix?', array['Keep the same glove and hand position for every pitch', 'Hide behind your leg', 'Throw the change-up harder', 'Throw fewer change-ups'], 0, 'Every pitch should start the same. Practice a consistent glove and grip so nothing gives away the change.', 'What should every pitch look like at the start?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Tipping pitches'),
  ('battery-3-10', 'general', null, 'battery', 3, null, 'You''re ahead 1-2.', 'What makes a good waste pitch?', array['Right at the hitter', 'Down the middle', 'Way outside so it can''t be hit', 'Just off the plate, looking like a strike, to get a chase'], 3, 'A pitch way outside is just a ball. A good waste pitch starts like a strike and ends just off the edge, where she might chase.', 'What makes a hitter swing?', 3, '{"runners":[],"outs":0,"you":"P","count":{"balls":1,"strikes":2}}'::jsonb, 'GGG.Cafe Battery IQ · Waste pitch with purpose'),
  ('battery-3-11', 'general', null, 'battery', 3, null, 'Extra inning: runner on second, nobody out. They''re expected to bunt.', 'What''s the battery''s plan?', array['Throw to second', 'Walk the batter', 'Throw a high strike, field the bunt and take the sure out', 'Throw a pitch in the dirt'], 2, 'A high strike is hard to bunt well. Field it cleanly and get a sure out; a wild throw for the lead runner can lose the game.', 'What''s worse than giving up the base?', 3, '{"runners":["second"],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Tiebreaker inning'),
  ('battery-3-12', 'general', null, 'battery', 3, null, 'It''s the third game of the day and your pitch count is climbing.', 'What''s a smart approach?', array['Try to strike everyone out', 'Attack early and pitch to contact: let your defense work', 'Nibble at the corners', 'Throw only change-ups'], 1, 'Long at-bats wear you down. Attacking early and trusting your defense saves pitches for the late innings.', 'Who else is on the field to help?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Pitch to contact'),
  ('battery-3-13', 'general', null, 'battery', 3, null, 'The umpire is calling the low pitch a strike today.', 'How do you use it?', array['Live at the bottom of the zone with your drop and change', 'Throw everything high', 'Complain about the zone', 'Ignore it'], 0, 'Use today''s zone. If the low pitch is a strike, pitch there all day with the pitches that live down.', 'Who sets today''s zone?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Umpire''s zone'),
  ('battery-3-14', 'general', null, 'battery', 3, null, 'You''ve walked three of the last four batters.', 'What''s the reset?', array['Throw as hard as you can', 'Speed up', 'Try a new pitch', 'Simplify: your most reliable pitch, a big target, hit the glove'], 3, 'When command goes, simplify. One pitch you trust, one target, one breath, one focus: hit the glove.', 'What''s the one thing you trust most?', 3, '{"runners":["first","second","third"],"outs":1,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Lost command'),
  ('battery-3-15', 'general', null, 'battery', 3, null, 'Two outs, runner on second, first base open. The best hitter in their lineup is up, 2-0.', 'What''s a reasonable plan?', array['Throw only off-speed in the dirt', 'Throw her a strike down the middle', 'Pitch carefully to the edges; walking her to face the next hitter is acceptable', 'Hit her with a pitch'], 2, 'With first base open and two outs, there''s no need to give her anything good. Work the edges and accept the walk if she won''t chase.', 'Is a walk a disaster here?', 3, '{"runners":["second"],"outs":2,"you":"P","count":{"balls":2,"strikes":0}}'::jsonb, 'GGG.Cafe Battery IQ · First base open, two outs'),
  ('battery-3-16', 'general', null, 'battery', 3, null, 'Your out pitch is a rise ball.', 'How do you set it up?', array['Throw it every pitch', 'Show pitches low first so the rise looks like a strike when it comes', 'Throw it only on 3-0', 'Never throw it with two strikes'], 1, 'Pitches low change the hitter''s eye level, so the rise ball looks like a strike out of your hand before it climbs.', 'What makes a chase pitch look like a strike?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Set up the out pitch'),
  ('battery-3-17', 'general', null, 'battery', 3, null, 'You''re catching and see the hitter''s hands drift away from her body before the pitch.', 'What might that mean?', array['She''s going to bunt or slap', 'She''s tired', 'She wants a walk', 'Nothing'], 0, 'Hands sliding or a shift in her stance can be the start of a bunt or a slap. Let your corners and pitcher know.', 'What do hitters do just before they bunt?', 3, '{"runners":[],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Battery IQ · Catcher reads the hitter''s hands'),
  ('battery-3-18', 'general', null, 'battery', 3, null, 'You want to get a hitter out away.', 'How can an inside pitch help?', array['Inside pitches are always strikes', 'It makes her bunt', 'It can''t', 'Inside moves her feet and eyes, so the pitch away looks farther and is harder to reach'], 3, 'Hard stuff inside makes her guard the inner half. Then the pitch away is a longer reach.', 'What is she guarding after an inside pitch?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Inside to set up away'),
  ('battery-3-19', 'general', null, 'battery', 3, null, 'Your coach comes out to talk in a big moment.', 'How do you use the visit?', array['Talk about the score', 'Argue the last call', 'Listen to the plan, take a breath, and leave with one clear focus', 'Look at the stands'], 2, 'A visit is a reset. Get the plan, breathe and go back with one thing to do on the next pitch.', 'What do you take back to the rubber?', 3, '{"runners":[],"outs":0,"you":"P"}'::jsonb, 'GGG.Cafe Battery IQ · Mound visit'),
  ('battery-3-20', 'general', null, 'battery', 3, null, 'This hitter has chased the high pitch twice already.', 'With two strikes, what do you do?', array['Never throw her high again', 'Go back up: make her prove she can lay off it', 'Throw it down the middle', 'Walk her'], 1, 'Until she shows she can lay off it, her weakness is your out pitch. Throw it again, just above the hands.', 'What has she done twice?', 3, '{"runners":[],"outs":0,"you":"P","count":{"balls":0,"strikes":2}}'::jsonb, 'GGG.Cafe Battery IQ · Hitter who chases up'),
  ('position-1b-01', 'position', '1B', 'position', 1, null, 'Runner on first, two outs. The batter squares and bunts toward the mound. You''re the first baseman.', 'What''s your first move?', array['Stay on first base for the throw', 'Run to cover second base', 'Back up the pitcher', 'Charge the bunt until you''re called off'], 3, 'On a bunt you crash with the pitcher and catcher, and the second baseman slides over to cover first. If the pitcher calls for it, let her take it.', 'Someone else is already sliding over to your bag on this play.', 2, '{"runners":["first"],"outs":2,"you":"1B","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.75 · Runner at 1B, 2 outs: bunt to the pitcher'),
  ('position-1b-02', 'position', '1B', 'position', 1, null, 'Runners on first and third, two outs. A ground ball single goes into center field. The runner on third scores easily and the runner from first heads for third. You''re the first baseman.', 'Where do you go?', array['Cover first base and stay out of the batter''s path', 'Go out as the cut to home', 'Go out as the cut to third', 'Back up second base'], 0, 'The throw goes through the shortstop to third, so you aren''t a cut on this one. Cover first without getting in the batter-runner''s way so you don''t cause obstruction.', 'Find which infielder is lined up for the throw to third. What''s left for you after that?', 2, '{"runners":["first","third"],"outs":2,"you":"1B","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.99 · Runners at 1B & 3B, 2 outs: single to center'),
  ('position-1b-03', 'position', '1B', 'position', 1, null, 'Runners on second and third, two outs. The batter bunts toward you, and the runner on third breaks for home. You field it. You''re the first baseman.', 'Where do you throw?', array['First base, to the second baseman covering', 'Home plate', 'Third base', 'Hold it and check the runners'], 0, 'With two outs, the out at first ends the inning before the run counts. Your catcher should be calling it for you.', 'Two outs changes everything. Which out finishes the inning for good?', 2, '{"runners":["second","third"],"outs":2,"you":"1B","ball":{"at":"bunt-1B","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.102 · Runners at 2B & 3B, 2 outs: bunt to the first baseman'),
  ('position-1b-04', 'position', '1B', 'position', 1, null, 'Runner on second, two outs. A routine ground ball is hit to you a step from first base, and the runner from second is running on contact.', 'What''s your play?', array['Throw to third to get the lead runner', 'Step on first base yourself', 'Throw home to stop the run', 'Look the runner back to second first'], 1, 'With two outs, the runner from second doesn''t matter if you get the batter. You''re a step away, so take the out yourself and end the inning.', 'Two outs: what''s the shortest path to the third out?', 2, '{"runners":["second"],"outs":2,"you":"1B","ball":{"at":"1B","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.80 · Runner at 2B, 2 outs: ground ball to first near the bag'),
  ('position-1b-05', 'position', '1B', 'position', 1, null, 'Runner on second, two outs. A ground ball single goes into left field, and the runner from second is rounding third. You''re the first baseman.', 'Where do you go?', array['Go out as the cut to home', 'Back up home plate', 'Cover first and help direct the throw', 'Cover second base'], 2, 'On a single to left, the shortstop (or the third baseman) is the cut to home. You stay at first and help call where the throw should go.', 'On a ball to the left side, the cut comes from the left side of the infield.', 2, '{"runners":["second"],"outs":2,"you":"1B","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.81 · Runner at 2B, 2 outs: single to left'),
  ('position-1b-06', 'position', '1B', 'position', 1, null, 'Runners on first and second, one out. A fly ball is caught in right field, and the runner on second tags for third. You''re the first baseman.', 'Where do you go?', array['Go out as the cut to third', 'Go out as the cut to home', 'Back up second base', 'Cover first base'], 3, 'The second baseman is the cut to third on this throw. You stay on first to keep the runner there honest.', 'Someone else is lined up for the throw to third, and the runner behind her still needs watching.', 2, '{"runners":["first","second"],"outs":1,"you":"1B","ball":{"at":"RF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.45 · Runners at 1B & 2B, <2 outs: fly ball to right'),
  ('position-1b-07', 'position', '1B', 'position', 1, null, 'Runner on third, one out. Ground ball to the shortstop. She looks the runner back to third and throws to you at first for the out. You''re the first baseman.', 'What do you do right after the catch?', array['Turn and throw to second base', 'Check the runner at third', 'Toss the ball back to the pitcher right away', 'Throw across to third base'], 1, 'An out at first isn''t the end of the play while a runner sits on third. Look at her right away so she can''t break for home behind your back.', 'There''s still someone on base who can score if nobody''s watching her.', 2, '{"runners":["third"],"outs":1,"you":"1B","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"SS","to":"first","kind":"throw"}]}'::jsonb, 'Defensive Playbook p.32 · Runner at 3B, <2 outs: after the out at first'),
  ('position-1b-08', 'position', '1B', 'position', 1, null, 'Runner on first, nobody out. The batter bunts it hard right at you as you charge in. You''re the first baseman.', 'Where do you throw?', array['First base', 'Third base', 'Second base', 'Hold it and look the runner back'], 2, 'A hard bunt gets to you fast enough to beat the lead runner to second, where the shortstop is covering. On a slow bunt you''d take the out at first.', 'A hard bunt saves you time. Spend it on the runner who''s further along.', 2, '{"runners":["first"],"outs":0,"you":"1B","ball":{"at":"bunt-1B","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.12 · Runner at 1B, <2 outs: hard bunt to the first baseman'),
  ('position-1b-09', 'position', '1B', 'position', 1, null, 'Runners on second and third, one out. The batter bunts it hard right at you as you charge, and both runners stay at their bases. You''re the first baseman.', 'What''s your play?', array['Tag the batter as she runs past', 'Throw home', 'Throw to third', 'Throw to second'], 0, 'A hard bunt reaches you before the batter can get by, so tag her yourself. No throw means nothing to overthrow with two runners in scoring position.', 'Think about the path to first and how close it runs to you.', 2, '{"runners":["second","third"],"outs":1,"you":"1B","ball":{"at":"bunt-1B","type":"bunt"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.63 · Runners at 2B & 3B, <2 outs: hard bunt at the first baseman'),
  ('position-1b-10', 'position', '1B', 'position', 1, null, 'Runner on second, one out. A fly ball is caught in center field, and the runner on second tags up for third. You''re the first baseman.', 'Where do you go?', array['Cover first base', 'Back up second base', 'Go out as the cut to home', 'Go out as the cut to third'], 1, 'With the batter out and nobody on first, your bag doesn''t need you. The second baseman is just getting back to cover second, so you back her up in case a throw gets loose.', 'With the batter out, your own bag is empty for a reason. Where else could a loose ball hurt you?', 2, '{"runners":["second"],"outs":1,"you":"1B","ball":{"at":"CF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.27 · Runner at 2B, <2 outs: fly ball to center'),
  ('position-1b-11', 'position', '1B', 'position', 1, null, 'Runner on second, nobody out. A ground ball is hit to you a few steps off the bag, and the runner on second takes a couple of steps toward third and stops. You''re the first baseman.', 'What''s your play?', array['Throw to third right away', 'Throw to second base', 'Get the out at first without looking', 'Check the runner, then get the out at first'], 3, 'Freeze the lead runner with a look before you go to first. Skip that, and she takes third on your throw.', 'Before you take the sure thing, deal with whoever is already in scoring position.', 2, '{"runners":["second"],"outs":0,"you":"1B","ball":{"at":"1B","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.22 · Runner at 2B, <2 outs: ground ball to the first baseman'),
  ('position-1b-12', 'position', '1B', 'position', 1, null, 'Bases loaded, one out. A ground ball is hit right to you, and every runner is moving on contact. You''re the first baseman.', 'What''s the best play?', array['Step on first base', 'Throw to second base', 'Throw home to the catcher', 'Throw to third base'], 2, 'With the bases loaded, the force at home keeps the run off the board. Your catcher can then look to first or third for a second out.', 'Every runner is forced, including the one about to score.', 2, '{"runners":["first","second","third"],"outs":1,"you":"1B","ball":{"at":"1B","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.48 · Bases loaded, <2 outs: ground ball to the first baseman'),
  ('position-1b-13', 'position', '1B', 'position', 1, null, 'Bases loaded, two outs, and the game isn''t close. A hard ground ball shoots through the right side right at the right fielder, who is playing shallow. The batter is slow. You''re the first baseman.', 'Where do you go?', array['Line up as the cut to home', 'Cover first for a throw from the right fielder', 'Back up home plate', 'Cover second base'], 1, 'Normally you''d be the cut to home, but a hard ball right at a shallow right fielder with a slow batter is a chance to throw her out at first. Talk with your right fielder and get on the bag.', 'Your usual job on this kind of single changes when the outfielder has a real shot at the batter.', 2, '{"runners":["first","second","third"],"outs":2,"you":"1B","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.95 · Bases loaded, 2 outs: hard single right at the right fielder'),
  ('position-1b-14', 'position', '1B', 'position', 1, null, 'Bases loaded, one out. Ground ball to the third baseman, who throws home to the catcher for the force. You''re the first baseman.', 'Where should you be?', array['On first base, ready for the catcher''s throw', 'Backing up home plate', 'Out in front of first as a cut', 'Covering second base'], 0, 'The force at home is the first out, and the batter is still forced at first. Be on the bag and give your catcher a target so she can finish the double play.', 'The play at the plate is only the first out. Who else is still forced?', 2, '{"runners":["first","second","third"],"outs":1,"you":"1B","ball":{"at":"3B","type":"ground"},"arrows":[{"from":"3B","to":"home","kind":"throw"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.49 · Bases loaded, <2 outs: double play through home'),
  ('position-1b-15', 'position', '1B', 'position', 1, null, 'Runner on third, one out. The batter bunts toward you, and the runner on third breaks for home on the pitch. You field it. You''re the first baseman.', 'Where do you throw?', array['Home to the catcher', 'First base, to the second baseman covering', 'Third base', 'Second base'], 0, 'It''s a squeeze, and your catcher stayed home for exactly this. With fewer than two outs, stopping the run comes first.', 'With fewer than two outs, an out at first doesn''t stop this runner from counting.', 2, '{"runners":["third"],"outs":1,"you":"1B","ball":{"at":"bunt-1B","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.29 · Runner at 3B, <2 outs: bunt with the runner breaking'),
  ('position-1b-16', 'position', '1B', 'position', 1, null, 'Runners on first and second, two outs. A ground ball rolls into the left-center gap, and both runners are flying. The shortstop races out to be the cut. You''re the first baseman.', 'Where do you go?', array['Stay on first base', 'Back up home plate', 'Line up as the double cut to home', 'Cover second base'], 2, 'A throw from deep in the gap is too long for one relay, so you set up as the second cut in line with the plate. The pitcher backs up home behind your catcher.', 'A ball deep in the gap needs more than one relay to reach the plate.', 2, '{"runners":["first","second"],"outs":2,"you":"1B","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.90 · Runners at 1B & 2B, 2 outs: ground ball into the left-center gap'),
  ('position-1b-17', 'position', '1B', 'position', 1, null, 'Runner on first, one out. A fly ball looks like it will drop in right field, and the runner on first takes off. The right fielder makes the catch. You''re the first baseman.', 'Where do you go?', array['Go out as the cut to second', 'Cover second base', 'Back up second base', 'Get back to first base for the throw'], 3, 'The runner has to get back and retouch first. If the right fielder''s throw beats her there, she''s out, so be on the bag and give a big target.', 'After a catch, every baserunner has to return to where she started.', 2, '{"runners":["first"],"outs":1,"you":"1B","ball":{"at":"RF","type":"fly"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.19 · Runner at 1B, <2 outs: catch in right with the runner off the bag'),
  ('position-1b-18', 'position', '1B', 'position', 1, null, 'Runner on third, two outs. The batter bunts in front of the plate. You charge, but the catcher calls you off, fields it and throws to the second baseman covering first. You''re the first baseman.', 'Where do you go?', array['Cover first base', 'Cover home plate', 'Back up first base', 'Cover third base'], 1, 'The catcher left the plate to make the play, and there''s a runner on third. Fill in at home in case the throw gets away and she tries to score.', 'One base on the field was left empty by this play, and you''re already moving toward it.', 2, '{"runners":["third"],"outs":2,"you":"1B","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"C","to":"first","kind":"throw"}]}'::jsonb, 'Defensive Playbook p.83 · Runner at 3B, 2 outs: catcher leaves home on a bunt'),
  ('position-1b-19', 'position', '1B', 'position', 1, null, 'Runners on second and third, one out. A hard ground ball is hit right at you, a step from the bag. The runner on third takes a few steps toward home and stops. You''re the first baseman.', 'What''s your play?', array['Step on first, then be ready to throw home', 'Throw home right away', 'Throw to third', 'Step on first and throw to second'], 0, 'A hard ball lets you take the sure out at first without losing sight of the runner on third. Keep her in front of you and be ready to throw home if she goes.', 'Get one out cleanly, but never lose sight of the runner who can score.', 2, '{"runners":["second","third"],"outs":1,"you":"1B","ball":{"at":"1B","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.65 · Runners at 2B & 3B, <2 outs: hard grounder at the first baseman'),
  ('position-1b-20', 'position', '1B', 'position', 1, null, 'Runner on second, nobody out. A ground ball single goes into center field, and the runner from second is heading home. You''re the first baseman.', 'Where do you go?', array['Cover first base', 'Cover second base', 'Line up as the cut to home', 'Back up home plate'], 2, 'On a single to center with a runner scoring, you''re the cut to home. Get in line between the center fielder and the plate and listen to your catcher.', 'The shortstop handles the throw to third on this one. Which infielder is free to help get the ball to the plate?', 2, '{"runners":["second"],"outs":0,"you":"1B","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.25 · Runner at 2B, <2 outs: single to center'),
  ('position-1b-21', 'position', '1B', 'position', 1, null, 'Bases loaded, one out. A fly ball is caught in right field, and the runner on third tags to score. You''re the first baseman.', 'Where do you go?', array['Stay on first base', 'Go out as the cut to third', 'Back up home plate', 'Become the cut between right field and home'], 3, 'On a fly to right with a runner tagging from third, you''re the relay to the plate. Line up between the right fielder and home and let your catcher tell you whether to cut it.', 'When a runner tags from third on a ball to that side, the relay comes from the same side of the infield.', 2, '{"runners":["first","second","third"],"outs":1,"you":"1B","ball":{"at":"RF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.53 · Bases loaded, <2 outs: fly ball to right'),
  ('position-2b-01', 'position', '2B', 'position', 1, null, 'Nobody on, one out. A ground ball is hit right back to the pitcher. You''re the second baseman.', 'What''s your job?', array['Cover second base for a possible throw', 'Cover first base and take the throw', 'Back up the pitcher in case the ball gets through', 'Run down the line to back up the throw to first'], 2, 'The first baseman has her bag and the shortstop takes second, so you get behind the play. If the ball deflects off the pitcher or skips past her, you keep it in the infield.', 'Two bases are already covered, so think about what happens if the ball gets past the mound.', 2, '{"runners":[],"outs":1,"you":"2B","ball":{"at":"P","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.5 · No runners, <2 outs: ground ball to the pitcher'),
  ('position-2b-02', 'position', '2B', 'position', 1, null, 'Nobody on, nobody out. A ground ball rolls through the middle into center field for a single. You''re the second baseman.', 'Where do you go?', array['Cover second base and take the throw', 'Go out and set up as the cut to second', 'Cover first base behind the runner', 'Back up the center fielder in case it gets by her'], 0, 'On a ground-ball single to center, the shortstop goes out as the cut. You take second, help line her up, and be ready for the throw if the batter tries to stretch it.', 'On a grounder to center your middle-infield partner is the one who goes out, so which job is left for you?', 2, '{"runners":[],"outs":0,"you":"2B","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.8 · No runners, <2 outs: ground-ball single to center'),
  ('position-2b-03', 'position', '2B', 'position', 1, null, 'Nobody on, two outs. A ground ball gets through the right side into right field. You''re the second baseman.', 'What''s your job?', array['Cover second base and take the throw', 'Cover first base and watch the runner', 'Back up the right fielder in case it gets by her', 'Go out toward the ball and set up as the cut to second'], 3, 'A ball to right is on your side, so you go out and become the cut to second. The shortstop covers the bag and takes the throw.', 'The ball is on your side, and the right fielder needs a short target between her and the batter''s next base.', 2, '{"runners":[],"outs":2,"you":"2B","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.73 · No runners, 2 outs: ground-ball single to right'),
  ('position-2b-04', 'position', '2B', 'position', 1, null, 'Nobody on, two outs. A ground ball is hit to the first baseman. You''re the second baseman.', 'What''s your job?', array['Cover second base in case the batter keeps going', 'Back her up and be ready to take a throw at first', 'Back up first base from foul territory', 'Hold your position and call out the play'], 1, 'Get behind the first baseman in case the ball gets by her. If she can''t get back to the bag herself, you''re the one taking her throw at first.', 'If the first baseman gets pulled off her bag, someone close by has to finish the play there.', 2, '{"runners":[],"outs":2,"you":"2B","ball":{"at":"1B","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.72 · No runners, 2 outs: ground ball to the first baseman'),
  ('position-2b-05', 'position', '2B', 'position', 1, null, 'Runner on first, nobody out. The batter bunts slowly toward first, and the first baseman fields it and throws to you covering first. The batter is out. You''re the second baseman.', 'What do you do right after the catch?', array['Throw to second base to get the runner', 'Look at the lead runner before you do anything else', 'Throw to third base ahead of the runner', 'Toss the ball back to the pitcher and reset'], 1, 'The runner from first may round second and try for third while everyone watches the play at first. Check her right away and be ready to throw if she commits.', 'The out is made, but someone is still moving on the bases.', 2, '{"runners":["first"],"outs":0,"you":"2B","ball":{"at":"bunt-1B","type":"bunt"},"arrows":[{"from":"1B","to":"first","kind":"throw"},{"from":"home","to":"first","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.12 · Runner at 1B, <2 outs: after the out on a bunt'),
  ('position-2b-06', 'position', '2B', 'position', 1, null, 'Runner on first, one out. A sharp ground ball comes back to the pitcher, and the shortstop breaks for second to take her throw. You''re the second baseman.', 'Where do you go?', array['Cover first base for the throw', 'Back up the pitcher in case it gets through', 'Back up second base behind the shortstop', 'Cover third base behind the runner'], 2, 'With a runner on first, the pitcher''s throw is likely going to second, where the shortstop has the bag. You get behind second in case the throw gets away.', 'The pitcher''s throw is probably headed to the middle of the diamond for the force, so think about what happens if it sails.', 2, '{"runners":["first"],"outs":1,"you":"2B","ball":{"at":"P","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.13 · Runner at 1B, <2 outs: ground ball to the pitcher'),
  ('position-2b-07', 'position', '2B', 'position', 1, null, 'Runner on first, one out. A hard ground ball is hit right at you, and you field it cleanly. You''re the second baseman.', 'Where''s your throw?', array['Second base', 'First base', 'Third base', 'Home'], 0, 'A hard-hit ball gives you time to get the lead runner. Feed the shortstop at second for the force, and she can try to finish the double play at first.', 'The ball got to you fast, so which runner can you get besides the safe one?', 2, '{"runners":["first"],"outs":1,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.14 · Runner at 1B, <2 outs: hard ground ball to 2B'),
  ('position-2b-08', 'position', '2B', 'position', 1, null, 'Runner on first, nobody out. A ground ball single goes into right field, and the runner from first is rounding second. You''re the second baseman.', 'What''s your job?', array['Cover second base for the batter', 'Go out and set up as the cut to second', 'Cover first base behind the batter', 'Go out and set up as the cut to third'], 3, 'The runner from first is going for third, so the right fielder''s throw goes there. Go out toward the ball and line up between her and third while the shortstop covers second.', 'Follow the lead runner: the throw has to beat her to the base she''s heading for.', 2, '{"runners":["first"],"outs":0,"you":"2B","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.17 · Runner at 1B, <2 outs: single to right, runner going to third'),
  ('position-2b-09', 'position', '2B', 'position', 1, null, 'Runners on second and third, one out. A fly ball goes to medium center field, and both runners are ready to tag. You''re the second baseman.', 'What''s your job?', array['Go out and line up as the cut to home', 'Go out and line up as the cut to third', 'Go out toward the ball, then get back to cover second', 'Back up the center fielder in case it gets by her'], 2, 'The first baseman is the cut to home and the shortstop is the cut to third, so second is yours. Go out in case the ball drops, then get back so the bag isn''t left empty.', 'Two other infielders handle the relays to home and third, so which bag would be left empty if you stayed out?', 2, '{"runners":["second","third"],"outs":1,"you":"2B","ball":{"at":"CF","type":"fly"},"arrows":[]}'::jsonb, 'Defensive Playbook p.70 · Runners at 2B & 3B, <2 outs: fly ball to center'),
  ('position-2b-10', 'position', '2B', 'position', 1, null, 'Runner on second, nobody out. A ground ball splits the right-center gap. You''re the second baseman.', 'Where do you go?', array['Line up between the gap and home as the cut', 'Go out toward the gap as the cut to second or third', 'Cover second base and help direct the throw', 'Cover first base behind the batter'], 1, 'The ball is on your side, so you go out as the cut and the outfielder throws through you to second or third. The first baseman takes the relay to home and the shortstop covers second.', 'The ball is deep on the right side, so who in the infield is closest to it, and who''s left to handle the plate?', 2, '{"runners":["second"],"outs":0,"you":"2B","ball":{"at":"RCF-gap","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.26 · Runner at 2B, <2 outs: ground ball into the right-center gap'),
  ('position-2b-11', 'position', '2B', 'position', 1, null, 'Runner on third, one out, infield playing back. A routine ground ball comes to you, and the runner on third stays close to her bag. You''re the second baseman.', 'What do you do?', array['Look the runner back to third, then throw to first', 'Throw home to cut down the run', 'Run at the runner to drive her back to third', 'Throw to third to pick the runner off'], 0, 'Check the runner first: she''s holding, so freeze her with a look and take the sure out at first. If she had broken for the plate, your throw would go home.', 'If she isn''t going anywhere there''s no play on her yet, so make sure she sees you and take the out that''s there.', 2, '{"runners":["third"],"outs":1,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.31 · Runner at 3B, <2 outs: ground ball to 2B, runner holds'),
  ('position-2b-12', 'position', '2B', 'position', 1, null, 'Runner on third, nobody out. A fly ball goes to medium right field, and the runner is ready to tag. You''re the second baseman.', 'What''s your job?', array['Set up in shallow right as the cut to home', 'Cover second base in case of a throw there', 'Cover first base for a possible throw', 'Go after it until the right fielder calls you off'], 3, 'Go hard after the ball until the right fielder takes it. On this play the first baseman is the cut to home and the shortstop covers second.', 'The relay to the plate belongs to another infielder here, so how can you help on a ball in the air on your side?', 2, '{"runners":["third"],"outs":0,"you":"2B","ball":{"at":"RF","type":"fly"},"arrows":[]}'::jsonb, 'Defensive Playbook p.36 · Runner at 3B, <2 outs: fly ball to right'),
  ('position-2b-13', 'position', '2B', 'position', 1, null, 'Runners on first and second, one out. A slow roller comes toward you, and you have to charge hard to field it. You''re the second baseman.', 'Where''s your throw?', array['Second base', 'Third base', 'First base', 'Home'], 2, 'A slow ball takes away your shot at the lead runners. Take the sure out at first.', 'The runners got a big head start on a ball that slow, so which out can you still count on?', 2, '{"runners":["first","second"],"outs":1,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.40 · Runners at 1B & 2B, <2 outs: slow roller to 2B'),
  ('position-2b-14', 'position', '2B', 'position', 1, null, 'Bases loaded, nobody out. The batter bunts back to the pitcher, who throws home to the catcher for the force. You''re the second baseman covering first.', 'What should you be ready for?', array['A throw from the pitcher for a second out', 'A throw from the catcher for a second out', 'A throw from the third baseman for a second out', 'Nothing, the play ends at home'], 1, 'After the force at home, the catcher may turn and throw to first to get the batter. Stay on the bag and give her a target.', 'The play isn''t necessarily over after the force at the plate, so who has the ball now?', 2, '{"runners":["first","second","third"],"outs":0,"you":"2B","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"P","to":"home","kind":"throw"},{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.45 · Bases loaded, <2 outs: covering first after the force at home'),
  ('position-2b-15', 'position', '2B', 'position', 1, null, 'Bases loaded, one out. A ground ball splits the right-center gap, and all three runners are moving. You''re the second baseman.', 'What''s your job?', array['Go out toward the gap as the cut to home', 'Cover second base and help direct the throw', 'Go out toward the gap as the cut to third', 'Cover first base behind the batter'], 0, 'With the bases loaded the throw goes home, and the ball is on your side, so you go out as the cut to the plate. The first baseman sets up as a second cut behind you.', 'With the bases full the runner who matters most is heading for the plate, and the ball is on your side.', 2, '{"runners":["first","second","third"],"outs":1,"you":"2B","ball":{"at":"RCF-gap","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.52 · Bases loaded, <2 outs: ground ball into the right-center gap'),
  ('position-2b-16', 'position', '2B', 'position', 1, null, 'Runners on first and third, one out. A ground ball is hit up the middle, and the shortstop gets to it near second base. The runner on third stays put. You''re the second baseman.', 'What''s your job?', array['Cover first base for her throw', 'Back up the shortstop in case it gets through', 'Break toward home to back up the plate', 'Call for the ball at second, then throw to first'], 3, 'When the ball takes her up the middle, demand the ball at second for the force, then finish the double play at first.', 'She''s moving toward a base you can reach quickly, and the batter is still running.', 2, '{"runners":["first","third"],"outs":1,"you":"2B","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.57 · Runners at 1B & 3B, <2 outs: ball up the middle to the shortstop'),
  ('position-2b-17', 'position', '2B', 'position', 1, null, 'Runners on first and second, one out. A fly ball to right field is caught, and the runner on second tags and heads for third. You''re the second baseman.', 'What''s your job?', array['Cover second base behind the runner', 'Cover first base behind the runner', 'Go out and set up as the cut to third', 'Go out and set up as the cut to home'], 2, 'The throw from right goes to third to get the tagging runner, and the ball is on your side, so you''re the cut. The shortstop covers second.', 'Follow the runner who''s tagging; the right fielder''s throw needs a relay target on your side of the field.', 2, '{"runners":["first","second"],"outs":1,"you":"2B","ball":{"at":"RF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.45 · Runners at 1B & 2B, <2 outs: fly ball to right'),
  ('position-2b-18', 'position', '2B', 'position', 1, null, 'Runners on second and third, one out. A ground ball rolls into the left-center gap. You''re the second baseman.', 'Where do you go?', array['Cover second base and help direct the throw', 'Go out toward the gap as the cut', 'Cover third base and help direct the throw', 'Go out and line up as the cut to home'], 0, 'The ball is on the left side, so the shortstop goes out as the cut and the first baseman takes the relay to home. You cover second and talk to the outfield about where the throw goes.', 'This ball is on the far side from you, so which bag does your middle-infield partner leave behind when she goes out?', 2, '{"runners":["second","third"],"outs":1,"you":"2B","ball":{"at":"LCF-gap","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.68 · Runners at 2B & 3B, <2 outs: ground ball into the left-center gap'),
  ('position-2b-19', 'position', '2B', 'position', 1, null, 'Runner on first, two outs. A ground ball pulls you toward second base, and you field it a few steps from the bag. You''re the second baseman.', 'What''s the best play?', array['Throw to first base', 'Throw to second base', 'Throw to third base', 'Run the ball to first yourself'], 1, 'With two outs, one out ends the inning. When the ball takes you toward second, the force there is the shortest, easiest throw.', 'You only need one out, so take the shortest throw from where you fielded it.', 2, '{"runners":["first"],"outs":2,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.76 · Runner at 1B, 2 outs: ground ball takes you toward second'),
  ('position-2b-20', 'position', '2B', 'position', 1, null, 'Runner on third, two outs. A ground ball single goes into left field, and the runner on third scores easily. You''re the second baseman.', 'What''s your job?', array['Go out toward left as the cut to second', 'Cover first base behind the batter', 'Back up home plate on the throw', 'Cover second base for the throw from left'], 3, 'The run is in, so the job now is keeping the batter at first. The shortstop is the cut on a ball to left, and you take the throw at second.', 'The run can''t be stopped, so think about the batter''s next base and who the relay is on a ball to left.', 2, '{"runners":["third"],"outs":2,"you":"2B","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.85 · Runner at 3B, 2 outs: ground-ball single to left'),
  ('position-2b-21', 'position', '2B', 'position', 1, null, 'Runner on second, two outs. The batter drops a bunt toward third, and the third baseman charges it. You''re the second baseman.', 'Where do you go?', array['Cover second base', 'Cover third base', 'Cover first base', 'Back up the third baseman'], 2, 'The first baseman crashes on the bunt, so first is empty. Get there and take the throw for the third out.', 'Both corners charged in, so which bag is open for the out on the batter?', 2, '{"runners":["second"],"outs":2,"you":"2B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[]}'::jsonb, 'Defensive Playbook p.79 · Runner at 2B, 2 outs: bunt to the third baseman'),
  ('position-3b-01', 'position', '3B', 'position', 1, null, 'Nobody on, nobody out. The batter bunts toward first. You charge, but the first baseman calls you off and fields it. You''re the third baseman.', 'Now what?', array['Cover home plate since the catcher charged', 'Run toward first to back up the throw', 'Cover second base in case of an overthrow', 'Get back and cover third base'], 3, 'When you don''t field the bunt, get back to your bag. If the throw to first gets away, the batter will try to take extra bases.', 'Think about what you left behind when you charged in.', 2, '{"runners":[],"outs":0,"you":"3B","ball":{"at":"bunt-1B","type":"bunt"},"arrows":[]}'::jsonb, 'Defensive Playbook p.4 · No runners, <2 outs: bunt fielded by the first baseman'),
  ('position-3b-02', 'position', '3B', 'position', 1, null, 'Nobody on, one out. A ground ball is hit to your left, toward the shortstop. You''re the third baseman.', 'What''s your job?', array['Stay on the bag at third and let her have it', 'Go for it, then get back to third if she takes it', 'Cover second base in case of a bad throw', 'Back up the shortstop in case it gets by her'], 1, 'Cut across for it if you can reach it. If the shortstop fields it, get back to third so your bag is covered.', 'A ball between you and the shortstop is worth an attempt, but then think about your own base.', 2, '{"runners":[],"outs":1,"you":"3B","ball":{"at":"SS","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.6 · No runners, <2 outs: ground ball to the shortstop''s side'),
  ('position-3b-03', 'position', '3B', 'position', 1, null, 'Nobody on, two outs. A ground ball splits the left-center gap. You''re the third baseman.', 'What''s your job?', array['Go out toward the gap as the cut', 'Cover second base and take the throw', 'Cover third and help direct the outfielder''s throw', 'Back up the left fielder in case it gets by'], 2, 'The shortstop goes out as the cut and the second baseman covers second. You cover third and talk to the outfield about where the throw should go.', 'A batter can try for three on a ball in the gap, and your middle infielders handle the relay and second.', 2, '{"runners":[],"outs":2,"you":"3B","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.74 · No runners, 2 outs: ground ball into the left-center gap'),
  ('position-3b-04', 'position', '3B', 'position', 1, null, 'Runner on first, one out. A hard ground ball is hit right at you, and you field it cleanly. You''re the third baseman.', 'Where''s your throw?', array['Second base', 'First base', 'Step on third base', 'Home'], 0, 'On a hard-hit ball you have time to get the lead runner. Throw to second for the force, and the second baseman can finish the double play at first.', 'The ball got to you quickly, so go after the runner who''s ahead of the batter.', 2, '{"runners":["first"],"outs":1,"you":"3B","ball":{"at":"3B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.15 · Runner at 1B, <2 outs: hard ground ball to 3B'),
  ('position-3b-05', 'position', '3B', 'position', 1, null, 'Runner on first, nobody out. A ground ball single goes into right field, and the runner from first is heading for third. You''re the third baseman covering third.', 'Who should be lined up as your cut?', array['The shortstop', 'The first baseman', 'The second baseman', 'The pitcher'], 2, 'On a ball to right, the second baseman goes out and becomes the cut to third. Direct her left or right from the bag so the throw comes straight to you.', 'Which infielder is closest to a ball in right field?', 2, '{"runners":["first"],"outs":0,"you":"3B","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.17 · Runner at 1B, <2 outs: single to right, lining up your cut'),
  ('position-3b-06', 'position', '3B', 'position', 1, null, 'Runners on first and third, one out. A slow ground ball single rolls into left field. The run scores, and the runner from first is trying for third. You''re the third baseman.', 'What''s your job?', array['Go out toward left as the cut to home', 'Cover third and line up the shortstop as your cut', 'Cover home plate in case the throw goes there', 'Back up the left fielder in case it gets by'], 1, 'The run is in, so the play is on the runner from first trying for third. Get on the bag and line up the shortstop, who is your cut.', 'The runner from third is gone, so follow the runner who started at first.', 2, '{"runners":["first","third"],"outs":1,"you":"3B","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.58 · Runners at 1B & 3B, <2 outs: slow single to left'),
  ('position-3b-07', 'position', '3B', 'position', 1, null, 'Runner on second, nobody out. The batter drops a bunt just in front of the plate. You charge, but the catcher fields it and throws to first. The shortstop has covered third. You''re the third baseman.', 'What''s your next job?', array['Get back to third base', 'Back up the throw to first', 'Cover second base', 'Cover home plate'], 3, 'The catcher left home to field the bunt, and the shortstop already has third. Home is empty, so you take it in case the runner tries to keep going.', 'Look at who left her spot to field this ball, and who already has your bag.', 2, '{"runners":["second"],"outs":0,"you":"3B","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"C","to":"first","kind":"throw"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.20 · Runner at 2B, <2 outs: bunt fielded by the catcher'),
  ('position-3b-08', 'position', '3B', 'position', 1, null, 'Runner on second, one out. A ground ball goes back to the pitcher. She looks the runner back and throws to first for the out, and the runner breaks for third on the throw. You''re the third baseman.', 'Who''s most likely to throw to you?', array['The first baseman', 'The pitcher', 'The catcher', 'The shortstop'], 0, 'The first baseman has the ball after the out, and she checks the lead runner right away. If the runner breaks, her throw comes to you, so be on the bag.', 'Follow the ball: who''s holding it after the out?', 2, '{"runners":["second"],"outs":1,"you":"3B","ball":{"at":"P","type":"ground"},"arrows":[{"from":"P","to":"first","kind":"throw"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.22 · Runner at 2B, <2 outs: throw to third after the out at first'),
  ('position-3b-09', 'position', '3B', 'position', 1, null, 'Runner on second, nobody out. The batter bunts toward third, and you charge and field it. The runner from second got a great jump and is almost to third. You''re the third baseman.', 'Where''s your throw?', array['Third base', 'First base', 'Second base', 'Home'], 1, 'The lead runner already has the base, so don''t chase her. Take the sure out at first.', 'If the lead runner already has the base, which out is still available?', 2, '{"runners":["second"],"outs":0,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.21 · Runner at 2B, <2 outs: sacrifice bunt to 3B'),
  ('position-3b-10', 'position', '3B', 'position', 1, null, 'Runner on second, two outs. The batter bunts toward the pitcher, and you charge until she calls you off. You''re the third baseman.', 'Who''s covering third behind you?', array['The left fielder', 'Nobody, so you have to get back', 'The shortstop', 'The pitcher'], 2, 'With a runner on second, the shortstop rotates to third on a bunt so you can charge hard. The left fielder backs up third; she doesn''t cover it.', 'On this play the center fielder comes in to take second, which frees up an infielder who''s usually there.', 2, '{"runners":["second"],"outs":2,"you":"3B","ball":{"at":"bunt-P","type":"bunt"},"arrows":[]}'::jsonb, 'Defensive Playbook p.79 · Runner at 2B, 2 outs: who covers third on a bunt'),
  ('position-3b-11', 'position', '3B', 'position', 1, null, 'Runner on third, nobody out. A ground ball comes back to the pitcher. You''re the third baseman.', 'What''s your job?', array['Cover home plate in case the runner breaks for it', 'Back up the pitcher in case it gets through', 'Cover second base in case of an overthrow', 'Cover third and call out if the runner breaks for home'], 3, 'Get to your bag behind the runner. The pitcher is checking her, and your call tells everyone right away if she''s going.', 'The pitcher has to decide based on that runner, and you''re the closest one to see what she does.', 2, '{"runners":["third"],"outs":0,"you":"3B","ball":{"at":"P","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.30 · Runner at 3B, <2 outs: ground ball to the pitcher'),
  ('position-3b-12', 'position', '3B', 'position', 1, null, 'Runner on third, one out, infield back. A routine ground ball comes to you, and the runner stays near the bag. You''re the third baseman.', 'What do you do?', array['Look the runner back, then throw to first', 'Throw home right away to stop the run', 'Run the runner back to third and tag her', 'Hold the ball until the runner commits'], 0, 'Check the runner first; she''s holding, so freeze her with a look and take the out at first. If she breaks for the plate, the throw goes home.', 'She''s not going anywhere yet, so make sure she knows you see her and get the out that''s there.', 2, '{"runners":["third"],"outs":1,"you":"3B","ball":{"at":"3B","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.32 · Runner at 3B, <2 outs: ground ball to 3B, runner holds'),
  ('position-3b-13', 'position', '3B', 'position', 1, null, 'Runners on first and second, one out. A ground ball is hit to the shortstop. You''re the third baseman.', 'What''s your job?', array['Get on third and tell her if the lead out is there', 'Cut across in front of her to field it yourself', 'Back up the shortstop in case it gets by her', 'Cover second base for the force from her'], 0, 'With two runners on, there''s a force at third. Get on the bag and let the shortstop know whether she can get the lead runner.', 'The runner from second is forced, so where is she going and who can help the shortstop decide?', 2, '{"runners":["first","second"],"outs":1,"you":"3B","ball":{"at":"SS","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.40 · Runners at 1B & 2B, <2 outs: ground ball to the shortstop'),
  ('position-3b-14', 'position', '3B', 'position', 1, null, 'Runners on first and second, nobody out. The batter bunts it hard right at you as you charge, and you field it cleanly. The shortstop is covering third. You''re the third baseman.', 'Where''s your throw?', array['First base', 'Second base', 'Third base', 'Home'], 2, 'A hard bunt gets to you fast enough to beat the lead runner, so throw to the shortstop at third for the force. On a slow bunt you''d take the out at first instead.', 'The ball got to you quickly, so which runner is closest to scoring and is someone there to take a throw?', 2, '{"runners":["first","second"],"outs":0,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.38 · Runners at 1B & 2B, <2 outs: hard bunt to 3B'),
  ('position-3b-15', 'position', '3B', 'position', 1, null, 'Bases loaded, one out, infield in. A ground ball comes back to the pitcher, and she throws home for the force. You''re the third baseman.', 'What''s your job?', array['Back up the throw home behind the catcher', 'Be on third for a possible throw from the catcher', 'Cover second base for a possible throw', 'Back up the pitcher in case she bobbles it'], 1, 'After the force at home, the catcher may look to third, where the runner from second is still forced. Be on the bag and give her a target.', 'The play doesn''t have to end at the plate, because the runner from second is still forced.', 2, '{"runners":["first","second","third"],"outs":1,"you":"3B","ball":{"at":"P","type":"ground"},"arrows":[{"from":"P","to":"home","kind":"throw"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.47 · Bases loaded, <2 outs: ground ball to the pitcher, throw home'),
  ('position-3b-16', 'position', '3B', 'position', 1, null, 'Runners on first and third, nobody out. The batter bunts toward you, the runner on third holds, and you field it and throw to first for the out. You''re the third baseman.', 'What do you do next?', array['Cover home plate in case the runner breaks', 'Follow your throw to back up first', 'Cover second base for the trail runner', 'Get back and cover third'], 3, 'The runner on third is still there, and the runner from first may keep going. Once your throw is gone, hustle back to your bag; the shortstop is at second on this play, not third.', 'Think about who covers your bag when the shortstop is busy at second on this play.', 2, '{"runners":["first","third"],"outs":0,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"3B","to":"first","kind":"throw"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.55 · Runners at 1B & 3B, <2 outs: after fielding the bunt'),
  ('position-3b-17', 'position', '3B', 'position', 1, null, 'Runners on second and third, two outs. A routine ground ball comes to you. You''re the third baseman.', 'Where''s your throw?', array['Home', 'Step on third base', 'First base', 'Second base'], 2, 'With first base open, neither runner is forced. The out is at first, and it ends the inning.', 'Check which runners are actually forced to run.', 2, '{"runners":["second","third"],"outs":2,"you":"3B","ball":{"at":"3B","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.104 · Runners at 2B & 3B, 2 outs: ground ball to 3B'),
  ('position-3b-18', 'position', '3B', 'position', 1, null, 'Bases loaded, one out. A fly ball to medium center field is caught, and all three runners tag. You''re the third baseman.', 'What''s your job?', array['Go out and line up as the cut to home', 'Cover third base for a possible throw', 'Cover home plate for the throw', 'Back up home plate behind the catcher'], 1, 'The first baseman is the cut to home and the shortstop is the cut to third. Stay on third: the catcher may send the throw there for the runner tagging from second.', 'Two other infielders are setting up relays, and the catcher might send the throw somewhere other than home.', 2, '{"runners":["first","second","third"],"outs":1,"you":"3B","ball":{"at":"CF","type":"fly"},"arrows":[]}'::jsonb, 'Defensive Playbook p.53 · Bases loaded, <2 outs: fly ball to center'),
  ('position-3b-19', 'position', '3B', 'position', 1, null, 'Runners on second and third, one out. A ground ball single goes into right field. The runner from second is rounding third and heading home, and you don''t have the ball. You''re the third baseman.', 'What''s your priority at the bag?', array['Stay out of her path so you don''t obstruct her', 'Stand in the baseline to slow her down', 'Leave third and run to cover home', 'Go out toward right as the cut to home'], 0, 'You''re covering third, but you aren''t in the play yet, so give her the base path. A fielder without the ball who gets in a runner''s way is committing obstruction.', 'Think about what you''re allowed to do when you don''t have the ball.', 2, '{"runners":["second","third"],"outs":1,"you":"3B","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.68 · Runners at 2B & 3B, <2 outs: single to right, staying out of the runner''s way'),
  ('position-3b-20', 'position', '3B', 'position', 1, null, 'Runner on first, one out. A ground ball is hit to the second baseman. You''re the third baseman.', 'Where do you go?', array['Back up second base', 'Cover home plate', 'Back up first base', 'Cover third base'], 3, 'The runner from first could round second and try for third if a throw gets away. Be on your bag.', 'Picture the runner from first if the throw to second sails.', 2, '{"runners":["first"],"outs":1,"you":"3B","ball":{"at":"2B","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.14 · Runner at 1B, <2 outs: ground ball to the second baseman'),
  ('position-3b-21', 'position', '3B', 'position', 1, null, 'Runner on third, two outs. A ground ball gets through into left field for a single, and the runner scores. You''re the third baseman.', 'Where do you go?', array['Go out toward left as the cut to second', 'Cover second base', 'Cover third base', 'Back up home plate'], 2, 'The shortstop is the cut to second and the second baseman takes that bag. You cover third so the batter can''t take an extra base on a bad throw.', 'The relay and second base are both handled by the middle infield.', 2, '{"runners":["third"],"outs":2,"you":"3B","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.85 · Runner at 3B, 2 outs: single to left'),
  ('position-c-01', 'position', 'C', 'position', 1, null, 'Nobody on, two outs. The batter drops a bunt up the first-base line. You''re the catcher.', 'What''s your first move?', array['Stay at home plate', 'Run down the line to back up first', 'Charge the bunt until someone calls you off', 'Cover third base'], 2, 'With nobody on, there''s no one to keep from scoring, so you attack the bunt along with the pitcher and first baseman. Whoever has the best play calls for it loudly.', 'With the bases empty, ask whether home plate needs protecting right now.', 2, '{"runners":[],"outs":2,"you":"C","ball":{"at":"bunt-1B","type":"bunt"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.71 · No runners, 2 outs: bunt toward first base'),
  ('position-c-02', 'position', 'C', 'position', 1, null, 'Runner on third, one out. The batter bunts it back toward the mound and the pitcher charges it. You''re the catcher.', 'What''s your job?', array['Charge out to field the bunt', 'Run down the line to back up first', 'Cover third base', 'Stay home and tell her: home or first'], 3, 'With a runner on third, the bunt may be a squeeze, so home can''t be left empty. Hold the plate and call the throw based on what the runner does.', 'A runner is one base from scoring. Think about what an empty plate would invite.', 2, '{"runners":["third"],"outs":1,"you":"C","ball":{"at":"bunt-P","type":"bunt"},"arrows":[]}'::jsonb, 'Defensive Playbook p.28 · Runner at 3B, <2 outs: bunt back to the pitcher'),
  ('position-c-03', 'position', 'C', 'position', 1, null, 'Nobody on, one out. The batter bunts it a few feet in front of the plate and you pounce on it. The first baseman charged in on the pitch.', 'Who should be covering first for your throw?', array['The second baseman', 'The first baseman', 'The pitcher', 'The right fielder'], 0, 'On a bunt the first baseman crashes in, so the second baseman slides over to cover first. Throw to her; the right fielder is behind the bag backing up.', 'The fielder who normally owns that bag is charging at you. Who is closest to fill it?', 2, '{"runners":[],"outs":1,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.4 · No runners, <2 outs: catcher fields the bunt'),
  ('position-c-04', 'position', 'C', 'position', 1, null, 'Runner on first, two outs. The batter bunts it in front of the plate, and you''re the one who fields it.', 'Where do you throw?', array['Second base', 'Third base', 'First base', 'Hold it and check the runner'], 2, 'With two outs you don''t need the lead runner. Take the sure out at first and the inning is over.', 'With two outs, any single out does the job. Pick the easiest one.', 2, '{"runners":["first"],"outs":2,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.75 · Runner at 1B, 2 outs: catcher fields the bunt'),
  ('position-c-05', 'position', 'C', 'position', 1, null, 'Runner on first, one out. A ground ball splits the left-center gap, and the runner from first is digging around second. You''re the catcher.', 'What''s your job?', array['Run down the line to back up first', 'Go out as a cut to home', 'Stay home and direct the throw', 'Cover third base'], 2, 'A ball in the gap can score the runner from first, so the plate can''t be empty. Stay home and tell the cut where the throw needs to go.', 'Picture how far the runner from first can get on a ball that rolls toward the fence.', 2, '{"runners":["first"],"outs":1,"you":"C","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.17 · Runner at 1B, <2 outs: ground ball into the left-center gap'),
  ('position-c-06', 'position', 'C', 'position', 1, null, 'Nobody on, one out. A ground ball goes up the middle for a single to center field. You''re the catcher.', 'What''s your job?', array['Run down the line to back up first', 'Call out where the throw goes so the infield can repeat it', 'Back up second base', 'Go out to be the cut'], 1, 'On a ground ball to the outfield you''re the lead communicator, because you see the whole field. Make the call early and loud, and the infield echoes it.', 'From behind the plate you''re the only fielder facing the entire play.', 2, '{"runners":[],"outs":1,"you":"C","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.8 · No runners, <2 outs: ground-ball single to center'),
  ('position-c-07', 'position', 'C', 'position', 1, null, 'Runner on third, one out. A fly ball is caught in center field, and the runner on third is tagging up to score. You''re the catcher.', 'Where should you be?', array['Out in front of the plate as the cut', 'At home plate, ready to take the throw', 'Behind third base backing up', 'Down the first-base line'], 1, 'The center fielder throws through the first baseman toward you, so you own the plate. Set up, give your cut a target and be ready to tag.', 'Which base is the runner trying to reach, and who covers it?', 2, '{"runners":["third"],"outs":1,"you":"C","ball":{"at":"CF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.36 · Runner at 3B, <2 outs: fly ball to center'),
  ('position-c-08', 'position', 'C', 'position', 1, null, 'Nobody on, nobody out. A hard ground ball shoots through the right side straight at the right fielder. You''re the catcher.', 'Where do you go?', array['Stay at home plate', 'Back up second base', 'Hustle toward first in foul ground', 'Go out to be the cut'], 2, 'A right fielder who gets a hard ball right at her can throw to first. Get down the line in foul ground so an overthrow there doesn''t send the batter to second.', 'Think about the right fielder''s quickest possible throw and what''s behind that bag.', 2, '{"runners":[],"outs":0,"you":"C","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.8 · No runners, <2 outs: hard grounder right at the right fielder'),
  ('position-c-09', 'position', 'C', 'position', 1, null, 'Runner on first, nobody out. The batter bunts it hard, straight out in front of the plate, and you field it right away.', 'Where do you throw?', array['First base', 'Third base', 'Hold it and look the runner back', 'Second base'], 3, 'A bunt right at you gives you time to get the lead runner at second, where the shortstop is covering. If it were off to the side and took longer to reach, you''d take the out at first.', 'How much time did this bunt cost you, and is that enough to go after the runner ahead of the batter?', 2, '{"runners":["first"],"outs":0,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.12 · Runner at 1B, <2 outs: bunt right at the catcher'),
  ('position-c-10', 'position', 'C', 'position', 1, null, 'Runner on second, nobody out. The batter bunts it right in front of the plate and you field it cleanly. The runner on second takes a short lead toward third and stops.', 'What''s your play?', array['Look the runner back, then throw to first', 'Throw to third right away', 'Throw to second', 'Throw to first without looking'], 0, 'Freeze the lead runner first so she can''t take third on your throw. Then get the sure out at first, where the second baseman is covering.', 'Before you let go of the ball, deal with the player already in scoring position.', 2, '{"runners":["second"],"outs":0,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.20 · Runner at 2B, <2 outs: bunt right at the catcher'),
  ('position-c-11', 'position', 'C', 'position', 1, null, 'Runners on first and second, two outs. A ground ball single goes into left field, and the runner from second is rounding third. You''re at the plate waiting for the throw.', 'Who should be backing you up?', array['The first baseman', 'The third baseman', 'The right fielder', 'The pitcher'], 3, 'The pitcher gets behind home in line with the throw on this play. Know she''s there so you can stay locked in on the catch and the tag.', 'Think about which fielder has no base to cover and no ball to chase on this play.', 2, '{"runners":["first","second"],"outs":2,"you":"C","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.89 · Runners at 1B & 2B, 2 outs: single to left, throw home'),
  ('position-c-12', 'position', 'C', 'position', 1, null, 'Runners on first and second, one out. A ground ball single goes into center field, and the runner from second is heading home. You''re the catcher.', 'Who should be your cut on the throw home?', array['The shortstop', 'The second baseman', 'The pitcher', 'The first baseman'], 3, 'On a single to center with a runner scoring, the first baseman is the cut to home while the shortstop is the cut to third. Line her up with your voice.', 'The shortstop already has a job on the throw to third. Who''s free on the right side?', 2, '{"runners":["first","second"],"outs":1,"you":"C","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.42 · Runners at 1B & 2B, <2 outs: single to center, throw home'),
  ('position-c-13', 'position', 'C', 'position', 1, null, 'Runners on first and second, nobody out. The batter bunts it hard, right out in front of you, and you''re on it in a flash.', 'Where''s the best throw?', array['First base', 'Second base', 'Hold it and look the runners back', 'Third base'], 3, 'A hard bunt gives you time to get the lead runner, and she''s forced at third, where the shortstop is covering. On a slow bunt you''d take the out at first.', 'Quick play, two runners forced: which one is closest to scoring?', 2, '{"runners":["first","second"],"outs":0,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.37 · Runners at 1B & 2B, <2 outs: hard bunt to the catcher'),
  ('position-c-14', 'position', 'C', 'position', 1, null, 'Runners on first and third, one out. The bunt dies right in front of the plate where only you can get it. The runner on third stays close to her bag.', 'Where do you throw?', array['Second base', 'First base', 'Third base', 'Hold the ball and stay home'], 1, 'With the runner on third staying put, get the sure out at first. You''d only go after her if she wandered far off the bag.', 'The runner you''d love to get isn''t giving you a chance, so take what the play offers.', 2, '{"runners":["first","third"],"outs":1,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.54 · Runners at 1B & 3B, <2 outs: catcher fields the bunt'),
  ('position-c-15', 'position', 'C', 'position', 1, null, 'Bases loaded, one out. The batter bunts it right in front of the plate, and you scoop it up a step from home.', 'What''s the best play?', array['Step on home, then throw to first or third', 'Throw to first right away', 'Tag the runner coming from third', 'Step on home and hold the ball'], 0, 'Every runner is forced, so touching the plate gets the first out without a tag. Then turn and throw to first or third to try for two.', 'Every runner is forced. How many outs can you get, and which one also stops a run?', 2, '{"runners":["first","second","third"],"outs":1,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.46 · Bases loaded, <2 outs: catcher fields the bunt'),
  ('position-c-16', 'position', 'C', 'position', 1, null, 'Runner on third, one out. The bunt dies right in front of the plate where only you can get it. The runner on third took a big lead and is stuck far off the bag.', 'What''s your play?', array['Go after the runner stranded off third', 'Throw to first for the sure out', 'Step on home plate', 'Throw to second base'], 0, 'When the lead runner is caught far off third, she''s the out you want. Make her commit and get her before she can score or get back; the shortstop is covering third.', 'The normal play changes when the player closest to scoring hands you a chance.', 2, '{"runners":["third"],"outs":1,"you":"C","ball":{"at":"bunt-C","type":"bunt"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.29 · Runner at 3B, <2 outs: runner caught off third on a bunt'),
  ('position-c-17', 'position', 'C', 'position', 1, null, 'Bases loaded, one out. Ground ball to the second baseman, who throws home. You catch it with your foot on the plate for the force.', 'What''s next?', array['Tag the runner sliding in to make sure', 'Look to throw to first or third for a second out', 'Hold the ball; one out is enough', 'Flip it back to the pitcher'], 1, 'The force at home is only the first out. The other runners are still forced, so turn and look to throw to first or third for the double play.', 'Every runner was forced when the ball was hit, and some of them still are.', 2, '{"runners":["first","second","third"],"outs":1,"you":"C","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"2B","to":"home","kind":"throw"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.48 · Bases loaded, <2 outs: after the force at home'),
  ('position-c-18', 'position', 'C', 'position', 1, null, 'Runners on second and third, two outs. The batter bunts it to the pitcher, and the runner on third breaks for home. You''re the catcher.', 'What do you tell the pitcher?', array['Throw to first', 'Throw home', 'Throw to third', 'Hold it and look the runners back'], 0, 'With two outs, the out at first ends the inning before that run counts. Stay on the plate and make the call loud and early.', 'Count the outs, then ask what happens to the runner from third if the batter never reaches base.', 2, '{"runners":["second","third"],"outs":2,"you":"C","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.102 · Runners at 2B & 3B, 2 outs: bunt with the runner breaking'),
  ('position-c-19', 'position', 'C', 'position', 1, null, 'Runner on second, two outs. The batter bunts toward the mound. You charge, but the pitcher calls you off, fields it and throws to first.', 'Where do you go now?', array['Get back and cover home', 'Follow the throw down the first-base line', 'Cover third base', 'Stay out in front of the plate'], 0, 'The runner from second is moving, and an empty plate invites her to try to score if anything goes wrong at first. Once you''re called off, hustle back to the plate.', 'You left your base to chase the ball. Who could take advantage of that?', 2, '{"runners":["second"],"outs":2,"you":"C","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"P","to":"first","kind":"throw"}]}'::jsonb, 'Defensive Playbook p.79 · Runner at 2B, 2 outs: bunt to the pitcher, after the throw'),
  ('position-c-20', 'position', 'C', 'position', 1, null, 'Runners on second and third, one out. A fly ball is caught in center field and both runners tag. The runner from third is fast and will score easily, so you call the throw to third to get the runner from second.', 'Who should be the cut on that throw?', array['The first baseman', 'The second baseman', 'The shortstop', 'The third baseman'], 2, 'On a fly to center, the first baseman is the cut to home and the shortstop is the cut to third. You called third, so the shortstop takes that line.', 'Two cuts set up on this play. Which one lines up with third?', 2, '{"runners":["second","third"],"outs":1,"you":"C","ball":{"at":"CF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.70 · Runners at 2B & 3B, <2 outs: fly to center, throw to third'),
  ('position-c-21', 'position', 'C', 'position', 1, null, 'Runner on first, nobody out. A hard ground ball is hit right at the third baseman. You''re the catcher, calling the play.', 'Where do you tell her to throw?', array['First base', 'Second base', 'Home plate', 'Hold it and check the runner'], 1, 'A hard-hit ball gives the third baseman time to get the lead runner at second, and the second baseman covering can try to turn two. On a slow roller you''d call first.', 'A hard-hit ball buys time; use it on the runner closest to scoring.', 2, '{"runners":["first"],"outs":0,"you":"C","ball":{"at":"3B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.15 · Runner at 1B, <2 outs: calling the throw on a hard grounder to third'),
  ('position-cf-01', 'position', 'CF', 'position', 1, null, 'Nobody on, nobody out. The batter grounds one to the first baseman. You''re the center fielder.', 'Where do you go?', array['Back up second base', 'Back up the first baseman', 'Back up first base', 'Cover second base'], 0, 'The right fielder backs up the ball on the right side. You get in line behind second, because if the play at first goes wrong, the next stop for the batter is second.', 'The right fielder has the ground ball covered. Think one play ahead of the out at first.', 2, '{"runners":[],"outs":0,"you":"CF","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.5 · No runners, <2 outs: ground ball to 1B'),
  ('position-cf-02', 'position', 'CF', 'position', 1, null, 'Runners on first and third, one out. A fly ball goes to left field. You''re the center fielder.', 'What''s your first job?', array['Back up second base', 'Back up third base', 'Set up as the cut toward home', 'Back up the left fielder'], 3, 'Get behind the left fielder so a ball that skips by her doesn''t roll to the wall. With a runner on third, that''s a run plus extra bases.', 'Your neighbor in the outfield is making the play. What if she misses it?', 2, '{"runners":["first","third"],"outs":1,"you":"CF","ball":{"at":"LF","type":"fly"}}'::jsonb, 'Defensive Playbook p.61 · Runners at 1B & 3B, <2 outs: fly ball to LF'),
  ('position-cf-03', 'position', 'CF', 'position', 1, null, 'Runner on second, nobody out. A fly ball goes to right field. You''re the center fielder.', 'Where do you go?', array['Back up second base', 'Back up the right fielder', 'Back up third base', 'Cover second base'], 1, 'Any ball to right means you''re behind the right fielder. If it gets by her with a runner on second, that runner scores.', 'One outfielder makes the catch; the closest one protects her.', 2, '{"runners":["second"],"outs":0,"you":"CF","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Defensive Playbook p.28 · Runner at 2B, <2 outs: fly ball to RF'),
  ('position-cf-04', 'position', 'CF', 'position', 1, null, 'Nobody on, two outs. The batter tries to bunt for a hit down the first-base line, and the first baseman charges it. You''re the center fielder.', 'Where do you go?', array['Back up second base', 'Run in and cover second base', 'Back up first base', 'Back up third base'], 0, 'With nobody on, the shortstop covers second, so your job is to back her up. If the throw to first gets away and the batter heads for second, you''re there.', 'With no runners, a middle infielder is free to get to the bag herself.', 2, '{"runners":[],"outs":2,"you":"CF","ball":{"at":"bunt-1B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.71 · No runners, 2 outs: bunt to 1B'),
  ('position-cf-05', 'position', 'CF', 'position', 1, null, 'Runner on third, one out. The batter bunts toward first base. You''re the center fielder.', 'Where do you go?', array['Back up second base', 'Back up first base', 'Back up third base', 'Run in and cover second base'], 3, 'With a runner on third, the shortstop covers third and the second baseman covers first, so second base is empty. Come in and take the bag so the batter can''t take second for free.', 'The shortstop''s job changes when there''s a runner on third. Who does that leave in the middle?', 2, '{"runners":["third"],"outs":1,"you":"CF","ball":{"at":"bunt-1B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.29 · Runner at 3B, <2 outs: bunt to 1B'),
  ('position-cf-06', 'position', 'CF', 'position', 1, null, 'Runners on first and third, nobody out. The batter bunts back to the pitcher. You''re the center fielder.', 'Where do you go?', array['Run in and cover second base', 'Back up second base', 'Back up third base', 'Back up first base'], 1, 'With first and third, the third baseman goes back to third after the bunt, which frees the shortstop to cover second. You back her up; you cover second yourself only when the shortstop has to go to third.', 'Ask who is covering third. That decides whether the middle bag is empty.', 2, '{"runners":["first","third"],"outs":0,"you":"CF","ball":{"at":"bunt-P","type":"bunt"}}'::jsonb, 'Defensive Playbook p.54 · Runners at 1B & 3B, <2 outs: bunt to the pitcher'),
  ('position-cf-07', 'position', 'CF', 'position', 1, null, 'Runner on first, one out. A hard ground ball skips up the middle and comes right at you. You''re the center fielder.', 'Where does your throw go?', array['Third base, through the shortstop', 'Home', 'First base', 'Second base'], 3, 'The ball got to you fast, so the runner from first can''t safely take third; throw to second to keep the batter at first. A slow ball is different: then the throw goes through the cut to third.', 'A ball that reaches you this quickly limits how far the runner from first can go.', 2, '{"runners":["first"],"outs":1,"you":"CF","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.16 · Runner at 1B, <2 outs: hard single right at CF'),
  ('position-cf-08', 'position', 'CF', 'position', 1, null, 'Runners on first and third, two outs. A ground ball single rolls into center field, and both runners are moving on contact. You''re the center fielder.', 'Where does your throw go?', array['Home, through the first baseman', 'Third base, through the shortstop', 'Second base', 'First base'], 1, 'The runner from third scores no matter what. The play is on the runner from first going for third, so hit the shortstop as your cut to third.', 'One run is already in. Find the runner who is still trying to move up.', 2, '{"runners":["first","third"],"outs":2,"you":"CF","ball":{"at":"CF","type":"ground"}}'::jsonb, 'Defensive Playbook p.100 · Runners at 1B & 3B, 2 outs: single to CF'),
  ('position-cf-09', 'position', 'CF', 'position', 1, null, 'Runner on second, one out. A ground ball single goes into center field, and the runner from second is rounding third. You''re the center fielder.', 'Where does your throw go?', array['Third base', 'Second base', 'First base', 'Home, through the cut'], 3, 'The runner from second is the run. Throw home through your cut, the first baseman, lined up between you and the plate.', 'The lead runner is already past third. What''s at stake now?', 2, '{"runners":["second"],"outs":1,"you":"CF","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.25 · Runner at 2B, <2 outs: single to CF'),
  ('position-cf-10', 'position', 'CF', 'position', 1, null, 'Runner on third, nobody out. A ground ball single goes into center field, and the runner from third trots home. You''re the center fielder.', 'Where does your throw go?', array['Home plate', 'Second base', 'Third base', 'First base'], 1, 'That run is already in, so a throw home does nothing. Get it to second right away so the batter has to stay at first.', 'You can''t stop the run. Focus on the batter-runner.', 2, '{"runners":["third"],"outs":0,"you":"CF","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.33 · Runner at 3B, <2 outs: single to CF'),
  ('position-cf-11', 'position', 'CF', 'position', 1, null, 'Runner on second, nobody out. You catch a fly ball in center, and the runner on second tags up. You''re the center fielder.', 'Where does your throw go?', array['Second base', 'Home plate', 'Third base, through the cut', 'First base'], 2, 'The tagging runner wants third, where she can score on an out. Throw through the shortstop to third to stop her.', 'Watch the tagging runner and beat her to the bag she''s going for.', 2, '{"runners":["second"],"outs":0,"you":"CF","ball":{"at":"CF","type":"fly"}}'::jsonb, 'Defensive Playbook p.27 · Runner at 2B, <2 outs: fly ball to CF, runner tagging'),
  ('position-cf-12', 'position', 'CF', 'position', 1, null, 'Runner on third, one out. You''re camped under a fly ball in center, the runner on third is tagging, and you''ll throw home after the catch. You''re the center fielder.', 'Who should be your cut on the throw home?', array['The shortstop', 'The second baseman', 'The pitcher', 'The first baseman'], 3, 'On a fly to center with a runner tagging from third, the first baseman comes across to be the cut to home. The middle infielders chase the ball until you call them off, then the second baseman takes second, and the pitcher backs up the plate.', 'Both middle infielders went out after the ball and the pitcher is behind the plate. Who''s left to line up in the middle?', 2, '{"runners":["third"],"outs":1,"you":"CF","ball":{"at":"CF","type":"fly"}}'::jsonb, 'Defensive Playbook p.36 · Runner at 3B, <2 outs: fly ball to CF, the cut to home'),
  ('position-cf-13', 'position', 'CF', 'position', 1, null, 'Runner on first, one out. A fly ball goes to medium center, and the runner on first stays near the bag. You''re the center fielder.', 'After the catch, where do you throw?', array['Second base', 'First base', 'Third base, through the cut', 'Home'], 0, 'Get the ball to second right away. That''s the bag the runner would try to tag and take, so a quick throw there keeps her at first.', 'Think about where the runner on first would go if you lobbed the ball in.', 2, '{"runners":["first"],"outs":1,"you":"CF","ball":{"at":"CF","type":"fly"}}'::jsonb, 'Defensive Playbook p.19 · Runner at 1B, <2 outs: fly ball to CF'),
  ('position-cf-14', 'position', 'CF', 'position', 1, null, 'Runners on first and second, one out. A ground ball splits the right-center gap. You and the right fielder both go after it, and she gets there first. You''re the center fielder.', 'What''s your job now?', array['Back up the right fielder', 'Set up as the cut toward third', 'Back up second base', 'Cover second base'], 0, 'On a gap ball, whoever doesn''t field it backs up the one who does. If it gets past both of you, both runners score and the batter keeps going.', 'Your teammate has the ball in front of her, but it isn''t in her glove yet.', 2, '{"runners":["first","second"],"outs":1,"you":"CF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.43 · Runners at 1B & 2B, <2 outs: right-center gap, RF gets there first'),
  ('position-cf-15', 'position', 'CF', 'position', 1, null, 'Bases loaded, nobody out. A ground ball splits the left-center gap and you cut it off before the left fielder. You''re the center fielder.', 'Where does your throw go?', array['Third base, through the shortstop', 'Second base', 'Home, through the shortstop', 'First base'], 2, 'With the bases loaded, runners are coming home on a gap ball, including the one who started at first. Throw home through the shortstop, with the first baseman set as a second cut if the throw is long.', 'With every base full, find the runner you can still keep from scoring.', 2, '{"runners":["first","second","third"],"outs":0,"you":"CF","ball":{"at":"LCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.52 · Bases loaded, <2 outs: left-center gap, you field it'),
  ('position-cf-16', 'position', 'CF', 'position', 1, null, 'Runners on second and third, one out. A ground ball splits the left-center gap and you get to it first. Both runners are going to score easily. You''re the center fielder.', 'Where does your throw go?', array['Home, through the first baseman', 'Home on the fly, skipping the cut', 'Through the shortstop to second or third, to hold the batter', 'First base'], 2, 'Both runs are going to score, so don''t throw behind them. Hit the shortstop as your cut to second or third and keep the batter from taking an extra base.', 'When the runs are already in, the only runner left to stop is the one who just hit the ball.', 2, '{"runners":["second","third"],"outs":1,"you":"CF","ball":{"at":"LCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.68 · Runners at 2B & 3B, <2 outs: left-center gap, you field it'),
  ('position-cf-17', 'position', 'CF', 'position', 1, null, 'Runners on first and second, nobody out. The batter grounds one to the third baseman. You''re the center fielder.', 'Where do you go?', array['Back up second base', 'Back up the third baseman', 'Back up third base', 'Back up first base'], 0, 'On infield ground balls your spot is behind second base. A throw there for a force or a double play can''t be allowed to roll into the outfield.', 'The left fielder has the ball itself covered. Where might a throw for a double play go?', 2, '{"runners":["first","second"],"outs":0,"you":"CF","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.41 · Runners at 1B & 2B, <2 outs: ground ball to 3B'),
  ('position-cf-18', 'position', 'CF', 'position', 1, null, 'Runners on first and second, two outs. A ground ball single rolls into right field. You''re the center fielder.', 'What''s your job?', array['Back up second base', 'Back up third base', 'Back up the right fielder', 'Set up as the cut toward home'], 2, 'Get behind the right fielder so a ball that skips by her doesn''t reach the fence. With two outs both runners are moving on contact, so that would score them both.', 'The ball is going to your neighbor in the outfield.', 2, '{"runners":["first","second"],"outs":2,"you":"CF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.90 · Runners at 1B & 2B, 2 outs: single to RF'),
  ('position-cf-19', 'position', 'CF', 'position', 1, null, 'Bases loaded, two outs. A ground ball single goes into center field, and every runner is moving on contact. You''re the center fielder.', 'Where does your throw go?', array['Home, through the cut', 'Third base, through the shortstop', 'Second base', 'First base'], 0, 'The runner from third scores, and the runner from second is trying to score behind her. Throw home through the first baseman to stop that second run.', 'The runner from third is in. Which runner is trying to make it two?', 2, '{"runners":["first","second","third"],"outs":2,"you":"CF","ball":{"at":"CF","type":"ground"}}'::jsonb, 'Defensive Playbook p.95 · Bases loaded, 2 outs: single to CF'),
  ('position-cf-20', 'position', 'CF', 'position', 1, null, 'Runner on first, two outs. A ground ball splits the right-center gap and you get to it first. The runner from first was running on contact. You''re the center fielder.', 'Where does your throw go?', array['Second base, through the shortstop', 'Through the cut to third or home, following the runner', 'First base, behind the batter', 'Straight to the catcher, skipping the cut'], 1, 'With two outs the runner from first got a running start and may try to score. Throw through the second baseman, your cut, to third or home depending on where that runner is going.', 'With two outs, whoever was on first left with the pitch. How far could she get by the time you pick it up?', 2, '{"runners":["first"],"outs":2,"you":"CF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.78 · Runner at 1B, 2 outs: right-center gap, you field it'),
  ('position-cf-21', 'position', 'CF', 'position', 1, null, 'Runner on first, two outs. A slow ground ball dribbles past the pitcher into center, and you have to charge it. You''re the center fielder.', 'Where does your throw go?', array['Second base', 'Home', 'Third base, through the shortstop', 'First base'], 2, 'On a slow ball the runner from first has time to go for third, so throw through the shortstop to third. If the ball had been hit hard right at you, second would be the throw.', 'Ball speed decides it: how much time did the runner from first get?', 2, '{"runners":["first"],"outs":2,"you":"CF","ball":{"at":"CF","type":"ground"}}'::jsonb, 'Defensive Playbook p.77 · Runner at 1B, 2 outs: slow single to CF'),
  ('position-lf-01', 'position', 'LF', 'position', 1, null, 'Nobody on, one out. The third baseman gets a sharp grounder. You''re the left fielder.', 'What''s your move?', array['Back up second base', 'Run in to cover third base', 'Back up first base', 'Charge in behind the third baseman in case it gets through'], 3, 'A ball to the left side of the infield is yours to back up. Close in behind the third baseman so a bobble or a ball through the hole doesn''t turn into extra bases.', 'Think about where the ball ends up if the infielder misses it.', 2, '{"runners":[],"outs":1,"you":"LF","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.7 · No runners, <2 outs: ground ball to 3B'),
  ('position-lf-02', 'position', 'LF', 'position', 1, null, 'Nobody on, nobody out. A fly ball goes to right field. You''re the left fielder.', 'Where do you go?', array['Back up the right fielder', 'Back up third base', 'Stay in left field', 'Back up second base'], 3, 'The center fielder is the one behind the right fielder. Your spot is behind second, where the throw comes in, so a ball that gets away doesn''t roll free.', 'Another outfielder is already behind the catch. Where does the ball go next?', 2, '{"runners":[],"outs":0,"you":"LF","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Defensive Playbook p.11 · No runners, <2 outs: fly ball to RF'),
  ('position-lf-03', 'position', 'LF', 'position', 1, null, 'Nobody on, two outs. The first baseman gets a ground ball. You''re the left fielder.', 'Where should you be?', array['Backing up third base', 'Backing up second base', 'Backing up the first baseman', 'Covering third base'], 0, 'The right fielder backs up the ball on the right side and the center fielder takes second. You take third, so if the ball gets loose and the batter keeps running, someone is behind that bag.', 'Your teammates in center and right already have the middle and the right side covered.', 2, '{"runners":[],"outs":2,"you":"LF","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.72 · No runners, 2 outs: ground ball to 1B'),
  ('position-lf-04', 'position', 'LF', 'position', 1, null, 'Runner on first, nobody out. A hard ground ball shoots through the left side and comes straight to you. You''re the left fielder.', 'Where does your throw go?', array['Third base, through the shortstop', 'Home', 'Second base, through the shortstop', 'First base'], 2, 'A ball hit hard right at you gets there fast, so the runner from first usually has to stop at second; your throw to second keeps the batter at first. On a slow ball the runner is thinking third, and that''s where the throw goes.', 'How fast the ball reached you decides how far the lead runner can go.', 2, '{"runners":["first"],"outs":0,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.16 · Runner at 1B, <2 outs: hard single right at LF'),
  ('position-lf-05', 'position', 'LF', 'position', 1, null, 'Runner on first, two outs. A ground ball splits the right-center gap, and the center and right fielders are chasing it. You''re the left fielder.', 'Where do you go?', array['Back up second base', 'Back up the center fielder', 'Back up home plate', 'Back up third base'], 3, 'With two outs the runner from first is running on contact, so the throw from the gap goes through the cut to third or home. The pitcher has the plate; you get behind third.', 'The runner from first had a running start. Which bag on your side of the field could the throw be headed for?', 2, '{"runners":["first"],"outs":2,"you":"LF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.78 · Runner at 1B, 2 outs: ground ball in the right-center gap'),
  ('position-lf-06', 'position', 'LF', 'position', 1, null, 'Runner on first, nobody out. A ground ball rolls into the left-center gap. You both chase it, and the center fielder gets there first and calls you off. You''re the left fielder.', 'What do you do now?', array['Sprint in to cover third base', 'Back up the center fielder', 'Back up second base', 'Set up as the cut between her and home'], 1, 'On a gap ball, whichever outfielder doesn''t field it backs up the one who does. Stay behind her so a bad hop doesn''t roll to the fence.', 'The ball can still skip past the player fielding it.', 2, '{"runners":["first"],"outs":0,"you":"LF","ball":{"at":"LCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.17 · Runner at 1B, <2 outs: left-center gap, CF gets there first'),
  ('position-lf-07', 'position', 'LF', 'position', 1, null, 'Runner on second, one out. A hard ground ball rips through the left side and comes right to you. You''re the left fielder.', 'Where does the ball go?', array['Third base', 'Home, through the cut', 'Second base', 'First base'], 0, 'A hard shot reaches you quickly, so the runner from second has to stop at third; get the ball straight there. On a slower ball she can try to score, and that''s when you go home through the cut.', 'The ball got to you in a hurry. How far can the runner from second realistically get?', 2, '{"runners":["second"],"outs":1,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.24 · Runner at 2B, <2 outs: hard single right at LF'),
  ('position-lf-08', 'position', 'LF', 'position', 1, null, 'Runner on second, nobody out. A ground ball single goes into right field. You''re the left fielder.', 'What''s your job on this play?', array['Run in to back up home plate', 'Back up the right fielder', 'Back up third, then shift to back up second if there''s no play at third', 'Run in and cover third base'], 2, 'Start behind third in case the runner from second stops there and a throw follows her. If no play develops at third, slide over behind second, where the batter may try to move up on the throw home.', 'Your job has two parts: start where the lead runner might stop, and adjust as the ball moves.', 2, '{"runners":["second"],"outs":0,"you":"LF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.25 · Runner at 2B, <2 outs: single to RF, two-step backup'),
  ('position-lf-09', 'position', 'LF', 'position', 1, null, 'Runner on third, one out. A ground ball single gets through into left field, and the runner from third is jogging home. You''re the left fielder.', 'Where does your throw go?', array['Home plate', 'Second base, through the cut', 'Third base', 'First base'], 1, 'That run is going to score, so don''t chase it with a throw home. Get the ball through the shortstop to second so the batter stays at first.', 'The runner from third is home free. Think about the runner you can still stop.', 2, '{"runners":["third"],"outs":1,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.33 · Runner at 3B, <2 outs: ground-ball single to LF'),
  ('position-lf-10', 'position', 'LF', 'position', 1, null, 'Runner on third, nobody out. A ground ball single rolls into right field and the run is going to score. You''re the left fielder.', 'Where do you go?', array['Back up third base', 'Back up home plate', 'Back up second base', 'Back up the right fielder'], 2, 'With the run scoring, the right fielder''s throw goes through the cut to second to hold the batter. That''s the base you back up from the left side.', 'Figure out where the right fielder is throwing, then get behind that bag.', 2, '{"runners":["third"],"outs":0,"you":"LF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.34 · Runner at 3B, <2 outs: single to RF'),
  ('position-lf-11', 'position', 'LF', 'position', 1, null, 'Runner on third, one out. A fly ball comes to you in medium left, and the runner on third is tagging up. You''re the left fielder.', 'After the catch, where does the ball go?', array['Third base', 'Second base', 'First base', 'Home, through the cut'], 3, 'The tagging runner is the run. Make the catch and throw home through the cut lined up between you and the plate.', 'Only one runner is on base. What is she trying to do?', 2, '{"runners":["third"],"outs":1,"you":"LF","ball":{"at":"LF","type":"fly"}}'::jsonb, 'Defensive Playbook p.35 · Runner at 3B, <2 outs: fly ball to LF, runner tagging'),
  ('position-lf-12', 'position', 'LF', 'position', 1, null, 'Runners on first and second, nobody out. The batter bunts toward third and the third baseman charges in while the shortstop heads over to third. You''re the left fielder.', 'Where do you go?', array['Back up third base', 'Cover second base', 'Back up second base', 'Back up first base'], 0, 'The third baseman may go to third for the lead out, and the shortstop is taking that throw on the run. Get behind the bag so a throw that gets by her doesn''t let the lead runner come home.', 'The lead out on this bunt is at the bag on your side of the diamond.', 2, '{"runners":["first","second"],"outs":0,"you":"LF","ball":{"at":"bunt-3B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.38 · Runners at 1B & 2B, <2 outs: bunt to 3B'),
  ('position-lf-13', 'position', 'LF', 'position', 1, null, 'Runners on first and second, one out. You catch a fly ball in left, and the runner on second tags up. You''re the left fielder.', 'Where does your throw go?', array['Third base, through the shortstop', 'Second base, through the shortstop', 'Home', 'First base'], 0, 'The runner tagging from second wants third, where she can score on an out. Throw through the shortstop to third to stop her.', 'Follow the lead runner who is tagging. Which bag is she trying to reach?', 2, '{"runners":["first","second"],"outs":1,"you":"LF","ball":{"at":"LF","type":"fly"}}'::jsonb, 'Defensive Playbook p.44 · Runners at 1B & 2B, <2 outs: fly ball to LF'),
  ('position-lf-14', 'position', 'LF', 'position', 1, null, 'Runners on first and second, nobody out. A fly ball goes to right field. You''re the left fielder.', 'Where do you go?', array['Back up second base', 'Back up third base', 'Back up the right fielder', 'Back up home plate'], 1, 'With a runner on second who can tag, the right fielder''s throw goes through the cut to third, so that''s the bag you back up. With nobody on, you''d be behind second instead.', 'A runner on second can tag up, and that changes where the right fielder throws.', 2, '{"runners":["first","second"],"outs":0,"you":"LF","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Defensive Playbook p.45 · Runners at 1B & 2B, <2 outs: fly ball to RF'),
  ('position-lf-15', 'position', 'LF', 'position', 1, null, 'Bases loaded, one out. A ground ball comes back to the pitcher, who throws home for the force. You''re the left fielder.', 'Where should you be?', array['Backing up second base', 'Backing up third base', 'Backing up home plate', 'Covering third base'], 1, 'After the force at home, the catcher may throw to third or first for a second out. A throw to third comes straight at you, so be behind that bag.', 'The play may not end at home. Think about where the catcher could throw next.', 2, '{"runners":["first","second","third"],"outs":1,"you":"LF","ball":{"at":"P","type":"ground"},"arrows":[{"from":"P","to":"home","kind":"throw"}]}'::jsonb, 'Defensive Playbook p.47 · Bases loaded, <2 outs: ground ball to the pitcher'),
  ('position-lf-16', 'position', 'LF', 'position', 1, null, 'Runners on first and third, one out. A slow ground ball dribbles through the left side, and you have to charge hard to get it. You''re the left fielder.', 'Where does your throw go?', array['Second base, through the cut', 'Home plate', 'First base', 'Third base, through the cut'], 3, 'The runner from third scores easily. On a slow ball the runner from first is going for third, so throw through the shortstop to third; a ball hit hard right at you would go to second instead.', 'The lead runner is gone. Ball speed tells you how aggressive the runner from first will be.', 2, '{"runners":["first","third"],"outs":1,"you":"LF","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Defensive Playbook p.58 · Runners at 1B & 3B, <2 outs: slow single to LF'),
  ('position-lf-17', 'position', 'LF', 'position', 1, null, 'Runners on second and third, nobody out. A ground ball splits the right-center gap and both runners are going to score. You''re the left fielder.', 'Where do you go?', array['Back up home plate', 'Back up the center fielder', 'Back up second or third, wherever the throw is headed', 'Run in and cover third base'], 2, 'Both runs are in, so the throw from the gap goes to second or third to stop the batter. Read it and get behind that bag.', 'Both runs score, so the batter-runner is the one to stop. Where could she be going?', 2, '{"runners":["second","third"],"outs":0,"you":"LF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.69 · Runners at 2B & 3B, <2 outs: ground ball in the right-center gap'),
  ('position-lf-18', 'position', 'LF', 'position', 1, null, 'Runner on second, two outs. A ground ball splits the left-center gap and you get to it first. The runner from second was running on contact and is already rounding third. You''re the left fielder.', 'Where does your throw go?', array['Home, through the cut', 'Through the cut to second or third, to hold the batter', 'Home on the fly, skipping the cut', 'First base'], 1, 'With two outs the runner from second scores easily on a gap ball, so don''t waste the throw. Get it through the shortstop to second or third so the batter doesn''t take an extra base.', 'The lead runner is a lost cause. Who is still in play?', 2, '{"runners":["second"],"outs":2,"you":"LF","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.82 · Runner at 2B, 2 outs: left-center gap, you field it'),
  ('position-lf-19', 'position', 'LF', 'position', 1, null, 'Bases loaded, two outs. A ground ball goes up the middle into center field. You''re the left fielder.', 'What''s your job?', array['Back up the center fielder', 'Back up third base', 'Back up home plate', 'Back up second base'], 0, 'On any ball to center, both corner outfielders back up the center fielder. If it gets by her with the bases loaded, everybody scores.', 'Think about what happens if the ball gets past the outfielder fielding it.', 2, '{"runners":["first","second","third"],"outs":2,"you":"LF","ball":{"at":"CF","type":"ground"}}'::jsonb, 'Defensive Playbook p.95 · Bases loaded, 2 outs: ground-ball single to CF'),
  ('position-lf-20', 'position', 'LF', 'position', 1, null, 'Runners on first and third, two outs. A ground ball single rolls into right field. You''re the left fielder.', 'Where do you go?', array['Back up third base', 'Back up second base', 'Back up home plate', 'Back up the right fielder'], 0, 'The runner from first is heading for third, so the right fielder throws through the cut to third and you get behind that bag. With only a runner on third, you''d back up second instead.', 'Follow the runner from first and see where the throw has to go to stop her.', 2, '{"runners":["first","third"],"outs":2,"you":"LF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.100 · Runners at 1B & 3B, 2 outs: single to RF'),
  ('position-lf-21', 'position', 'LF', 'position', 1, null, 'Runners on second and third, two outs. A ground ball single comes into left field, and both runners are running on contact. You''re the left fielder.', 'Where does your throw go?', array['Third base', 'Second base', 'Home, through the cut', 'First base'], 2, 'The runner from third scores, but the runner from second is trying to score behind her. Get the ball home through the cut to keep that second run off the board.', 'Count the runs that could score and focus on the one you can still stop.', 2, '{"runners":["second","third"],"outs":2,"you":"LF","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Defensive Playbook p.104 · Runners at 2B & 3B, 2 outs: single to LF'),
  ('position-p-01', 'position', 'P', 'position', 1, null, 'Nobody on, two outs. The batter bunts down the third-base line. You break toward it, but the third baseman calls you off and charges it. You''re the pitcher.', 'Where do you go?', array['Cover third base', 'Cover first base', 'Back up first base', 'Stay on the mound'], 0, 'Your third baseman left her bag to make the play, so third is empty. Peel off and cover it while she throws to the second baseman covering first.', 'When a corner charges in, the bag she left behind still needs somebody.', 2, '{"runners":[],"outs":2,"you":"P","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.71 · No runners, 2 outs: bunt fielded by the third baseman'),
  ('position-p-02', 'position', 'P', 'position', 1, null, 'Nobody on, one out. A ground ball rolls up the middle into center field for a single. You''re the pitcher.', 'Where do you go?', array['Back up third base', 'Cover first base', 'Back up home plate', 'Back up second base'], 3, 'The center fielder throws to second to keep the batter at first. Get behind the bag in line with that throw so a miss doesn''t hand her an extra base.', 'The batter is the only runner; picture which bag the outfielder is throwing to.', 2, '{"runners":[],"outs":1,"you":"P","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.8 · No runners, <2 outs: ground-ball single to center'),
  ('position-p-03', 'position', 'P', 'position', 1, null, 'Bases loaded, one out. A ground ball gets through the right side for a single, and the runner from second is trying to score. You''re the pitcher.', 'Where do you go?', array['Back up first base', 'Back up home plate', 'Cover home plate', 'Back up third base'], 1, 'The right fielder''s throw comes through the cut to the plate. Get deep behind your catcher in line with it so a miss doesn''t let another run in.', 'Find the throw that is trying to stop a run, then think about where it could get away.', 2, '{"runners":["first","second","third"],"outs":1,"you":"P","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.51 · Bases loaded, <2 outs: single to right'),
  ('position-p-04', 'position', 'P', 'position', 1, null, 'Runner on third, one out. A ground ball comes back to you on the mound, and the runner on third breaks for home on contact.', 'Where do you throw?', array['Home to the catcher', 'First base', 'Third base', 'Second base'], 0, 'Your first look is always at the runner on third. She''s running, so the ball goes home to cut down the run; if she had held, you''d take the out at first.', 'Your first look decides the throw: is the runner in front of you holding or going?', 2, '{"runners":["third"],"outs":1,"you":"P","ball":{"at":"P","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.30 · Runner at 3B, <2 outs: comebacker with the runner breaking'),
  ('position-p-05', 'position', 'P', 'position', 1, null, 'Runner on second, two outs. The batter bunts it back to you, and the runner from second takes off for third.', 'Where do you throw?', array['Third base', 'Home plate', 'Hold it and look the runner back', 'First base'], 3, 'With two outs, the out at first ends the inning and the runner never gets home. Don''t chase the lead runner; get the batter.', 'Count the outs. Which out is the surest one, and what does it do to the inning?', 2, '{"runners":["second"],"outs":2,"you":"P","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.79 · Runner at 2B, 2 outs: bunt back to the pitcher'),
  ('position-p-06', 'position', 'P', 'position', 1, null, 'Runner on first, nobody out. A slow ground ball rolls through the left side for a single, and the runner from first is going hard for third. You''re the pitcher.', 'Where do you go?', array['Back up second base', 'Back up third base', 'Back up home plate', 'Cover first base'], 1, 'On a slow single to left, the left fielder throws through the shortstop to third to get the lead runner. Get behind third in line with that throw; the right fielder has second.', 'Follow the lead runner: where is the throw going to try to get her?', 2, '{"runners":["first"],"outs":0,"you":"P","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.16 · Runner at 1B, <2 outs: slow single to left'),
  ('position-p-07', 'position', 'P', 'position', 1, null, 'Nobody on, nobody out. A routine ground ball is hit to the second baseman. You''re the pitcher.', 'What''s your job on this play?', array['Sprint to cover first base', 'Back up first base', 'Cover second base', 'Call out where the throw should go'], 3, 'The first baseman has her bag, the shortstop has second and the catcher is running down the line behind first. Your job is to help your second baseman by calling the play.', 'Count who is already at each base and behind first. What''s left for you?', 2, '{"runners":[],"outs":0,"you":"P","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.6 · No runners, <2 outs: ground ball to the second baseman'),
  ('position-p-08', 'position', 'P', 'position', 1, null, 'Runner on first, one out. The batter pushes a soft bunt toward the mound, and you have to charge hard to get to it.', 'Where do you throw?', array['Second base', 'First base', 'Third base', 'Hold it and look the runner back'], 1, 'A slow bunt doesn''t give you time to beat the runner to second. Take the sure out at first, where your second baseman is covering.', 'Weigh how long it took you to reach the ball against how far the runner from first has already gone.', 2, '{"runners":["first"],"outs":1,"you":"P","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.11 · Runner at 1B, <2 outs: slow bunt to the pitcher'),
  ('position-p-09', 'position', 'P', 'position', 1, null, 'Runners on second and third, one out. A ground ball comes back to you, and the runner on third stays close to her bag.', 'What''s your play?', array['Throw home right away', 'Throw to third to try to pick her off', 'Throw to first without looking', 'Look the runner back to third, then throw to first'], 3, 'Check the runner on third so she can''t break for home the moment you release. Once she''s frozen, take the out at first.', 'Nobody is forced home, so the player closest to scoring only hurts you if she goes unwatched.', 2, '{"runners":["second","third"],"outs":1,"you":"P","ball":{"at":"P","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.64 · Runners at 2B & 3B, <2 outs: comebacker with the runners holding'),
  ('position-p-10', 'position', 'P', 'position', 1, null, 'Runners on second and third, one out. A ground ball single goes into left field, and the runner from second is rounding third. You''re the pitcher.', 'Where do you go?', array['Back up third base', 'Back up home plate', 'Back up second base', 'Cover home plate'], 1, 'The left fielder throws through the cut to the plate to stop the second run. Get behind your catcher in line with that throw.', 'Which runner is the throw trying to stop, and where is she headed?', 2, '{"runners":["second","third"],"outs":1,"you":"P","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.67 · Runners at 2B & 3B, <2 outs: single to left'),
  ('position-p-11', 'position', 'P', 'position', 1, null, 'Runner on second, nobody out. A fly ball goes to medium center field, and the runner on second is tagging up. You''re the pitcher.', 'Where do you go?', array['Back up home plate', 'Back up second base', 'Back up third base', 'Cover third base'], 2, 'After the catch, the center fielder throws through the shortstop to third to stop the tag-up. Get behind third so an overthrow doesn''t let the runner walk home.', 'A runner tagging from second can only reach one base on the catch. Which one?', 2, '{"runners":["second"],"outs":0,"you":"P","ball":{"at":"CF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.27 · Runner at 2B, <2 outs: fly ball to center'),
  ('position-p-12', 'position', 'P', 'position', 1, null, 'Runners on first and second, one out. A fly ball is caught in left field, and the runner on second tags up. You''re the pitcher.', 'Where do you go?', array['Back up home plate', 'Back up first base', 'Stay on the mound and call the throw', 'Back up third base'], 3, 'The left fielder throws through the shortstop to third to beat the tag-up. You belong behind third, in line with that throw.', 'The lead runner can only move up one base on a caught fly; follow the throw that tries to stop her.', 2, '{"runners":["first","second"],"outs":1,"you":"P","ball":{"at":"LF","type":"fly"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.44 · Runners at 1B & 2B, <2 outs: fly ball to left'),
  ('position-p-13', 'position', 'P', 'position', 1, null, 'Bases loaded, one out. The batter bunts it right back to you.', 'Where''s the best throw?', array['Home to the catcher', 'First base', 'Third base', 'Second base'], 0, 'Every runner is forced, so the force at home keeps the run off the board. Your catcher may then turn and throw to first or third for a second out.', 'With every base full, which out also stops a run from scoring?', 2, '{"runners":["first","second","third"],"outs":1,"you":"P","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.45 · Bases loaded, <2 outs: bunt back to the pitcher'),
  ('position-p-14', 'position', 'P', 'position', 1, null, 'Runner on third, nobody out. A fly ball is caught in left field, and the runner on third tags up to score. You''re the pitcher.', 'Where do you go?', array['Back up home plate', 'Back up third base', 'Go out as the cut to home', 'Cover home plate'], 0, 'The left fielder throws through the cut to the plate. Get deep behind your catcher in line with the throw so nothing gets to the backstop.', 'The runner is racing for one base only; follow the throw that''s trying to beat her.', 2, '{"runners":["third"],"outs":0,"you":"P","ball":{"at":"LF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.35 · Runner at 3B, <2 outs: fly ball to left'),
  ('position-p-15', 'position', 'P', 'position', 1, null, 'Runner on first, two outs. A ground ball single goes into right field, and the runner from first is heading for third. You''re the pitcher.', 'Where do you go?', array['Back up third base', 'Back up first base', 'Back up home plate', 'Cover second base'], 2, 'The right fielder throws through the cut to third, and the left fielder already has third backed up. You take home in case a bad throw lets the runner keep coming.', 'The left fielder is already behind third. Where could a bad throw hurt you next?', 2, '{"runners":["first"],"outs":2,"you":"P","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.77 · Runner at 1B, 2 outs: single to right'),
  ('position-p-16', 'position', 'P', 'position', 1, null, 'Runner on first, one out. A fly ball goes to right field, and the runner on first has drifted too far off the bag when the right fielder makes the catch. You''re the pitcher.', 'Where do you go?', array['Back up second base', 'Cover first base', 'Back up first base', 'Back up home plate'], 2, 'After the catch, the right fielder can throw behind the runner to first to double her off. Back up first in line with that throw; the left fielder has second.', 'After the catch, the runner must retouch the bag she left. Where might the right fielder''s throw go?', 2, '{"runners":["first"],"outs":1,"you":"P","ball":{"at":"RF","type":"fly"},"arrows":[]}'::jsonb, 'Defensive Playbook p.19 · Runner at 1B, <2 outs: fly ball to right'),
  ('position-p-17', 'position', 'P', 'position', 1, null, 'Runner on second, two outs. A ground ball splits the left-center gap. You head to back up home, but the runner from second scores standing up and the outfielder''s throw is going to third to stop the batter.', 'What do you do now?', array['Shift over to back up third base', 'Stay behind home plate', 'Back up second base', 'Cover first base'], 0, 'You start behind home because that''s where the first throw could go. Once there''s no play at the plate, adjust to back up the base the throw is headed to.', 'Backups move with the ball. Where is the throw going now?', 2, '{"runners":["second"],"outs":2,"you":"P","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.82 · Runner at 2B, 2 outs: gap single with no play at home'),
  ('position-p-18', 'position', 'P', 'position', 1, null, 'Runner on third, one out. A ground ball single goes into right field, and the runner on third jogs home. You''re the pitcher.', 'Where do you go?', array['Back up home plate', 'Back up second base', 'Back up first base', 'Cover first base'], 2, 'The run scores easily, so there''s no play at home. The right fielder may come up throwing to first, so you back up first while the left fielder backs up second.', 'The run is already in. Look at what the right fielder can still do to the batter.', 2, '{"runners":["third"],"outs":1,"you":"P","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.34 · Runner at 3B, <2 outs: single to right'),
  ('position-p-19', 'position', 'P', 'position', 1, null, 'Runners on first and third, one out. A hard ground ball single goes right at the center fielder, and she comes up throwing to second. You''re the pitcher.', 'Where do you go?', array['Back up second base', 'Back up home plate', 'Back up third base', 'Cover second base'], 0, 'On this play your backup depends on where the center fielder throws. She''s going to second, so get behind that bag in line with her throw.', 'Your spot isn''t fixed on this play; let the outfielder''s throw tell you.', 2, '{"runners":["first","third"],"outs":1,"you":"P","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.59 · Runners at 1B & 3B, <2 outs: hard single right at center'),
  ('position-p-20', 'position', 'P', 'position', 1, null, 'Runners on first and third, two outs. The batter bunts it back to you, and the runner on third breaks for home.', 'Where do you throw?', array['Home to the catcher', 'First base', 'Second base', 'Third base'], 1, 'With two outs, the out at first ends the inning before that run can count. Your catcher should be yelling it: get the batter.', 'Count the outs, then ask which single out makes the runner from third irrelevant.', 2, '{"runners":["first","third"],"outs":2,"you":"P","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.97 · Runners at 1B & 3B, 2 outs: bunt with the runner breaking'),
  ('position-p-21', 'position', 'P', 'position', 1, null, 'Runner on second, nobody out. A sharp ground ball comes right back to you, and the runner on second has broken for third. She''s barely halfway there when you field it cleanly.', 'Where do you throw?', array['First base', 'Second base', 'Third base', 'Home plate'], 2, 'Your routine is to check the runner and take the out at first, but when the lead runner is yours for the taking, you take her. She''s hung out between bases, so go to third.', 'The routine play changes when the lead runner gives you a clear shot at her.', 2, '{"runners":["second"],"outs":0,"you":"P","ball":{"at":"P","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.22 · Runner at 2B, <2 outs: comebacker with the runner caught going'),
  ('position-rf-01', 'position', 'RF', 'position', 1, null, 'Nobody on, nobody out. The batter lays one down a few feet in front of the plate, and the catcher pops out to field it. You''re the right fielder.', 'Where do you go?', array['Back up second base', 'Cover first base', 'Back up first base', 'Stay in right field'], 2, 'The catcher''s throw goes to first. Get in line behind the bag so a throw that gets by doesn''t hand the batter second base.', 'Follow the catcher''s throw and get behind where it''s going.', 2, '{"runners":[],"outs":0,"you":"RF","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.4 · No runners, <2 outs: bunt in front of the plate'),
  ('position-rf-02', 'position', 'RF', 'position', 1, null, 'Runner on first, nobody out. The second baseman gets a ground ball. You''re the right fielder.', 'What''s your move?', array['Back up first base', 'Back up second base', 'Cover first base', 'Charge in behind the second baseman in case it gets through'], 3, 'The ball is hit to your side of the infield. Close in behind the second baseman so a ball through her legs doesn''t turn into first and third.', 'When the ball is hit to the right side, ask what happens if the infielder misses it.', 2, '{"runners":["first"],"outs":0,"you":"RF","ball":{"at":"2B","type":"ground"}}'::jsonb, 'Defensive Playbook p.15 · Runner at 1B, <2 outs: ground ball to 2B'),
  ('position-rf-03', 'position', 'RF', 'position', 1, null, 'Runner on third, two outs. A routine ground ball goes to the third baseman. You''re the right fielder.', 'Where do you go?', array['Back up first base', 'Back up second base', 'Back up the third baseman', 'Back up home plate'], 0, 'With two outs the third baseman throws across to first to end the inning. That long throw is the one most likely to sail, so be behind first base.', 'Think about where the third baseman throws with two outs, and what''s behind that bag.', 2, '{"runners":["third"],"outs":2,"you":"RF","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.85 · Runner at 3B, 2 outs: ground ball to 3B'),
  ('position-rf-04', 'position', 'RF', 'position', 1, null, 'Runners on second and third, nobody out. A fly ball goes to medium left field. You''re the right fielder.', 'Where do you go?', array['Back up the left fielder', 'Back up first base', 'Back up second base', 'Back up home plate'], 2, 'The center fielder backs up the left fielder and the pitcher backs up home. You come in behind second, where a relay or an off-line throw can get loose with runners moving.', 'The catch and the plate already have backups. Fill the next spot in the middle of the field.', 2, '{"runners":["second","third"],"outs":0,"you":"RF","ball":{"at":"LF","type":"fly"}}'::jsonb, 'Defensive Playbook p.69 · Runners at 2B & 3B, <2 outs: fly ball to LF'),
  ('position-rf-05', 'position', 'RF', 'position', 1, null, 'Nobody on, nobody out. A ground ball goes up the middle into center field. You''re the right fielder.', 'What''s your job?', array['Back up second base', 'Back up first base', 'Back up the center fielder', 'Cover second base'], 2, 'On a ball to center, both corner outfielders back up the center fielder. If it gets past her, you''re the one keeping a single from becoming a triple.', 'A teammate is fielding the ball. What happens if it gets by her?', 2, '{"runners":[],"outs":0,"you":"RF","ball":{"at":"CF","type":"ground"}}'::jsonb, 'Defensive Playbook p.8 · No runners, <2 outs: ground-ball single to CF'),
  ('position-rf-06', 'position', 'RF', 'position', 1, null, 'Nobody on, one out. A ground ball single rolls into right field. It isn''t hit hard, and you have to come in to get it. You''re the right fielder.', 'Where does your throw go?', array['First base', 'Second base, through the second baseman', 'Third base', 'Home'], 1, 'The batter is your only runner, so get the ball through your cut to second and keep her from stretching it into a double. First base is the throw only on a hard shot right at you.', 'A softly hit ball gives the batter time to round first. Which bag is she eyeing?', 2, '{"runners":[],"outs":1,"you":"RF","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.8 · No runners, <2 outs: single to RF'),
  ('position-rf-07', 'position', 'RF', 'position', 1, null, 'Runner on first, nobody out. A ground ball single goes into right field, and you have to move to your left to get it. The runner from first is running hard. You''re the right fielder.', 'Where does your throw go?', array['Second base', 'Third base, through the second baseman', 'First base', 'Home'], 1, 'A single to right is the runner from first''s best chance to reach third, so throw through your cut to third to stop her. It''s a long throw from right, which is why you use the cut.', 'Watch the lead runner, not the batter.', 2, '{"runners":["first"],"outs":0,"you":"RF","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.17 · Runner at 1B, <2 outs: single to RF'),
  ('position-rf-08', 'position', 'RF', 'position', 1, null, 'Runner on second, one out. A ground ball single goes into right field. It isn''t hit hard, and the runner from second is rounding third. You''re the right fielder.', 'Where does your throw go?', array['Third base', 'Second base', 'Home, through the cut', 'First base'], 2, 'The runner from second is trying to score, so throw home through the first baseman, who lines up as your cut. First base is only an option on a hard shot right at you, with a slow batter and a lopsided score.', 'The lead runner has already passed third. What''s at stake?', 2, '{"runners":["second"],"outs":1,"you":"RF","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Defensive Playbook p.25 · Runner at 2B, <2 outs: single to RF'),
  ('position-rf-09', 'position', 'RF', 'position', 1, null, 'Runner on third, nobody out. A ground ball single goes into right field. It isn''t hit hard, and the runner from third jogs home. You''re the right fielder.', 'Where does your throw go?', array['Home plate', 'Third base', 'First base', 'Second base, through the cut'], 3, 'The run is in. Throw through the second baseman to second so the batter stays at first.', 'There''s nothing to gain at the plate. Keep the batter where she is.', 2, '{"runners":["third"],"outs":0,"you":"RF","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.34 · Runner at 3B, <2 outs: single to RF'),
  ('position-rf-10', 'position', 'RF', 'position', 1, null, 'Runner on second, two outs, and your team is up 7-1. A hard ground ball comes straight at you in right, and the batter is slow out of the box. You''re the right fielder.', 'Where does your throw go?', array['First base', 'Home, through the cut', 'Third base', 'Second base'], 0, 'A hard shot right at you, a slow batter and a big lead: that''s the time to go to first. Throw her out and the inning is over, and because the third out is the batter before she reaches first, the runner crossing the plate doesn''t count.', 'With two outs, any out ends the inning. Which out is quickest and surest?', 2, '{"runners":["second"],"outs":2,"you":"RF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.82 · Runner at 2B, 2 outs: hard single right at RF'),
  ('position-rf-11', 'position', 'RF', 'position', 1, null, 'Runner on third, nobody out. You settle under a fly ball in right, and the runner on third is tagging. You''re the right fielder.', 'After the catch, where does the ball go?', array['Third base', 'Second base', 'First base', 'Home, through the cut'], 3, 'The tagging runner is the run. Make the catch and throw home through the first baseman, who lines up as your cut.', 'Think about what the tagging runner is trying to do.', 2, '{"runners":["third"],"outs":0,"you":"RF","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Defensive Playbook p.36 · Runner at 3B, <2 outs: fly ball to RF, runner tagging'),
  ('position-rf-12', 'position', 'RF', 'position', 1, null, 'Runner on first, one out. A fly ball goes to shallow right. The runner on first thought it would drop and is halfway to second when you make the catch. You''re the right fielder.', 'Where''s your best throw?', array['Second base, to beat her there', 'Third base', 'Home', 'First base, to double her off'], 3, 'After a catch, she has to get back to first before the ball does, so a quick throw there doubles her off. Normally your throw goes to second, but a runner caught that far off the bag is a free out.', 'After a catch, runners can''t just keep going. What does the rule make her do?', 2, '{"runners":["first"],"outs":1,"you":"RF","ball":{"at":"RF","type":"fly"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.19 · Runner at 1B, <2 outs: fly ball to RF, runner off the bag'),
  ('position-rf-13', 'position', 'RF', 'position', 1, null, 'Runners on first and second, nobody out. You catch a fly ball in right, and the runner on second tags up. You''re the right fielder.', 'Where does your throw go?', array['Second base, through the second baseman', 'Home', 'First base', 'Third base, through the second baseman'], 3, 'The runner tagging from second is going for third. That''s a long throw from right, so hit your cut, the second baseman, lined up to third.', 'Follow the lead runner who''s tagging, and remember how long the throw is from right field.', 2, '{"runners":["first","second"],"outs":0,"you":"RF","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Defensive Playbook p.45 · Runners at 1B & 2B, <2 outs: fly ball to RF'),
  ('position-rf-14', 'position', 'RF', 'position', 1, null, 'Runners on first and third, one out. You catch a fly ball in right, the runner on third tags, and the catcher calls for the throw home. You''re the right fielder.', 'Who''s your cut on the throw home?', array['The second baseman', 'The first baseman', 'The shortstop', 'The pitcher'], 1, 'The first baseman lines up between you and the plate as the cut to home. The second baseman is the cut to third, the shortstop has second, and the pitcher backs up home.', 'Your cut to the plate is the infielder already closest to the line between you and home.', 2, '{"runners":["first","third"],"outs":1,"you":"RF","ball":{"at":"RF","type":"fly"}}'::jsonb, 'Defensive Playbook p.62 · Runners at 1B & 3B, <2 outs: fly ball to RF, the cut to home'),
  ('position-rf-15', 'position', 'RF', 'position', 1, null, 'Runner on second, one out. A ground ball splits the right-center gap. The center fielder gets there a step ahead of you and calls for it. You''re the right fielder.', 'What do you do?', array['Back up the center fielder', 'Set up as the cut toward third', 'Back up first base', 'Cover second base'], 0, 'On a gap ball, the outfielder who doesn''t field it backs up the one who does. If it skips past her, you''re the last one between the ball and the fence.', 'Your teammate has the ball in front of her, but it isn''t in her glove yet.', 2, '{"runners":["second"],"outs":1,"you":"RF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.26 · Runner at 2B, <2 outs: right-center gap, CF gets there first'),
  ('position-rf-16', 'position', 'RF', 'position', 1, null, 'Bases loaded, one out. A ground ball splits the right-center gap and you get to it first. You''re the right fielder.', 'Where does your throw go?', array['Home, through the second baseman', 'Third base, through the second baseman', 'Second base', 'First base'], 0, 'With the bases loaded, runners are scoring on a gap ball and the runner from first will try to score too. Throw home through the second baseman, with the first baseman set as a second cut.', 'Bases full on a ball in the gap: where is the next run trying to cross?', 2, '{"runners":["first","second","third"],"outs":1,"you":"RF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.52 · Bases loaded, <2 outs: right-center gap, you field it'),
  ('position-rf-17', 'position', 'RF', 'position', 1, null, 'Runners on second and third, two outs. A ground ball splits the right-center gap and you get to it first. Both runners were moving on contact and will score easily. You''re the right fielder.', 'Where does your throw go?', array['Home, through the first baseman', 'Through the second baseman to second or third, to hold the batter', 'Home on the fly, skipping the cut', 'First base'], 1, 'Both runs are in, so a throw home is wasted. Hit your cut to second or third, wherever the batter is headed, and keep her from taking an extra base.', 'When both runs are already in, think about the hitter.', 2, '{"runners":["second","third"],"outs":2,"you":"RF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.106 · Runners at 2B & 3B, 2 outs: right-center gap, you field it'),
  ('position-rf-18', 'position', 'RF', 'position', 1, null, 'Runners on first and second, two outs. The first baseman gets a ground ball a few steps off the bag. You''re the right fielder.', 'What''s your move?', array['Charge in behind the first baseman in case it gets through', 'Back up second base', 'Back up third base', 'Cover first base'], 0, 'A ball hit to the right side of the infield is yours to back up. Close in behind the first baseman so a ball that gets by her doesn''t score the runner from second.', 'The ball is on your side of the infield.', 2, '{"runners":["first","second"],"outs":2,"you":"RF","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.88 · Runners at 1B & 2B, 2 outs: ground ball to 1B'),
  ('position-rf-19', 'position', 'RF', 'position', 1, null, 'Runners on first and third, nobody out. A ground ball splits the left-center gap, and the left and center fielders chase it. You''re the right fielder.', 'Where do you go?', array['Back up second base', 'Back up the center fielder', 'Back up first base', 'Back up home plate'], 0, 'The left and center fielders back each other up on the gap ball. Your job is behind second, where the batter is headed and where a throw can get away.', 'The two outfielders in the gap cover each other. Find the spot in the infield that needs someone behind it.', 2, '{"runners":["first","third"],"outs":0,"you":"RF","ball":{"at":"LCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.60 · Runners at 1B & 3B, <2 outs: left-center gap'),
  ('position-rf-20', 'position', 'RF', 'position', 1, null, 'Runners on first and third, two outs. A ground ball single goes into right field. It isn''t hit hard, and both runners are moving on contact. You''re the right fielder.', 'Where does your throw go?', array['Home, through the first baseman', 'Second base', 'Third base, through the second baseman', 'First base'], 2, 'The runner from third scores no matter what, and the runner from first is going for third, so throw through the second baseman to third. With only a runner on second, this same ball would go home.', 'One run is in. The play now is on the runner who started at first.', 2, '{"runners":["first","third"],"outs":2,"you":"RF","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.100 · Runners at 1B & 3B, 2 outs: single to RF'),
  ('position-rf-21', 'position', 'RF', 'position', 1, null, 'Runners on first and third, two outs. The batter bunts toward first, and the first baseman charges in to field it. You''re the right fielder.', 'Where do you go?', array['Back up second base', 'Back up first base', 'Charge in to back up the first baseman', 'Back up home plate'], 1, 'The first baseman fields it and throws to the second baseman covering first. Get behind that bag so a throw that gets by doesn''t let the runner from third score.', 'Follow the throw that has to be made after the bunt is fielded.', 2, '{"runners":["first","third"],"outs":2,"you":"RF","ball":{"at":"bunt-1B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.97 · Runners at 1B & 3B, 2 outs: bunt to 1B'),
  ('position-ss-01', 'position', 'SS', 'position', 1, null, 'Nobody on, one out. The batter bunts down the third-base line, and the third baseman charges in to field it. You''re the shortstop.', 'Where do you go?', array['Cover third base', 'Cover second base', 'Cover first base', 'Back up the third baseman'], 1, 'The second baseman slides over to first and the pitcher swings over to third after charging. You take second in case the throw to first gets away.', 'Your partner on the right side slides over to first, so which base in the middle is open?', 2, '{"runners":[],"outs":1,"you":"SS","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[]}'::jsonb, 'Defensive Playbook p.4 · No runners, <2 outs: bunt to the third baseman'),
  ('position-ss-02', 'position', 'SS', 'position', 1, null, 'Nobody on, two outs. A ground ball gets through the right side for a single. You''re the shortstop.', 'Where do you go?', array['Go out toward right as the cut to second', 'Back up first base in foul territory', 'Cover third base in case she keeps going', 'Cover second base and take the throw'], 3, 'On a ball to right, the second baseman goes out as the cut. You cover second, take the throw, and talk to her so she''s lined up with the bag.', 'The ball is on the far side from you and your partner takes the relay, so where does the batter want to go next?', 2, '{"runners":[],"outs":2,"you":"SS","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.73 · No runners, 2 outs: ground-ball single to right'),
  ('position-ss-03', 'position', 'SS', 'position', 1, null, 'Nobody on, one out. A ground ball is hit to the third baseman. You''re the shortstop.', 'What''s your job?', array['Back her up, then get to third if she leaves it open', 'Cover second base in case of an overthrow', 'Run toward first to back up her throw', 'Charge in to cut the ball off in front of her'], 0, 'Get behind the third baseman in case the ball gets by her. Once she makes her throw, third base is empty, so be ready to cover it.', 'Think about where the ball goes if she misses it, and what''s empty behind her after she throws.', 2, '{"runners":[],"outs":1,"you":"SS","ball":{"at":"3B","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.7 · No runners, <2 outs: ground ball to the third baseman'),
  ('position-ss-04', 'position', 'SS', 'position', 1, null, 'Runner on first, nobody out. The batter bunts back toward the pitcher, and you break to cover second. You''re the shortstop.', 'What else is your job as you get to the bag?', array['Leave the call to the catcher and stay quiet', 'Get ready to cover first base in case she throws there', 'Tell the pitcher if she has the lead out at second', 'Drift toward first to back up her throw'], 2, 'You have the best view of the runner coming into second. Tell the pitcher right away if she has a play there for the lead out; if not, she takes the out at first.', 'You''re the one watching the runner arrive, and someone needs that information before she throws.', 2, '{"runners":["first"],"outs":0,"you":"SS","ball":{"at":"bunt-P","type":"bunt"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.11 · Runner at 1B, <2 outs: bunt to the pitcher'),
  ('position-ss-05', 'position', 'SS', 'position', 1, null, 'Runner on first, one out. A ground ball comes back to the pitcher, and she turns to throw to you covering second. You''re the shortstop.', 'How do you take the throw?', array['Take it in front of the bag, touch second, throw to first', 'Catch it behind the bag, then tag the sliding runner', 'Catch it on the bag and hold it to make sure of one out', 'Take it on the bag, touch second, then throw to third'], 0, 'The runner is forced, so all you need is the bag. Take the throw in front of second, touch it, and get the ball to first quickly for the double play.', 'The runner is forced, so what''s the fastest way to two outs?', 2, '{"runners":["first"],"outs":1,"you":"SS","ball":{"at":"P","type":"ground"},"arrows":[{"from":"P","to":"second","kind":"throw"},{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.13 · Runner at 1B, <2 outs: taking the feed at second on a comebacker'),
  ('position-ss-06', 'position', 'SS', 'position', 1, null, 'Runner on first, nobody out. A slow chopper comes to you, and you have to charge hard to get it. You''re the shortstop.', 'Where''s your throw?', array['Second base', 'First base', 'Third base', 'Home'], 1, 'On a slow ball you won''t beat the runner to second. Take the sure out at first.', 'The runner from first was moving the whole time that ball was rolling, so which out is still there?', 2, '{"runners":["first"],"outs":0,"you":"SS","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.15 · Runner at 1B, <2 outs: slow roller to the shortstop'),
  ('position-ss-07', 'position', 'SS', 'position', 1, null, 'Runner on first, nobody out. A slow ground ball single rolls into left field, the left fielder has to charge it, and the runner from first is rounding second. You''re the shortstop.', 'What''s your job?', array['Cover second base behind the runner', 'Go out and set up as the cut to second', 'Go out and set up as the cut to third', 'Cover third base and take the throw'], 2, 'On a slow single the runner from first can try for third, so the left fielder''s throw goes there through you. Get out toward her and line up with third base.', 'The ball took a while to reach the outfielder, so where is the lead runner trying to go and who can help on that side?', 2, '{"runners":["first"],"outs":0,"you":"SS","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.16 · Runner at 1B, <2 outs: slow single to left, runner going to third'),
  ('position-ss-08', 'position', 'SS', 'position', 1, null, 'Runner on first, one out. A ground ball single goes into right field, and the runner from first is heading for third. You''re the shortstop.', 'Where do you go?', array['Go out toward right as the cut to third', 'Cover third base and take the throw', 'Back up third base in case of an overthrow', 'Cover second base and help direct the throw'], 3, 'On a ball to right, the second baseman is the cut to third and the third baseman has the bag. You cover second, call out where the throw should go, and stay out of the runner''s path.', 'Two other players already handle the play at third, so which bag would be empty?', 2, '{"runners":["first"],"outs":1,"you":"SS","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.17 · Runner at 1B, <2 outs: single to right'),
  ('position-ss-09', 'position', 'SS', 'position', 1, null, 'Runner on second, two outs. A ground ball is hit back to the pitcher. You''re the shortstop.', 'Where do you go?', array['Cover third base', 'Cover second base', 'Back up the pitcher', 'Back up first base'], 1, 'The pitcher''s throw goes to first for the third out. You cover second behind the runner while the third baseman takes third and the second baseman backs up the ball.', 'Look at where the runner started; somebody needs to be there behind her.', 2, '{"runners":["second"],"outs":2,"you":"SS","ball":{"at":"P","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.80 · Runner at 2B, 2 outs: ground ball to the pitcher'),
  ('position-ss-10', 'position', 'SS', 'position', 1, null, 'Runner on second, nobody out. A ground ball single rolls into center field, and the runner from second is rounding third. You''re the shortstop.', 'What''s your job?', array['Go out and line up as the cut to third', 'Go out and line up as the cut to home', 'Cover second base behind the batter', 'Cover third base and take the throw'], 0, 'On this play the first baseman is the cut to home. You go out toward the ball and set up as the cut to third, and the second baseman gets back to cover second.', 'On a single to center with a runner on second, an infielder from the right side takes the relay to the plate.', 2, '{"runners":["second"],"outs":0,"you":"SS","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.25 · Runner at 2B, <2 outs: single to center'),
  ('position-ss-11', 'position', 'SS', 'position', 1, null, 'Runner on third, nobody out. The batter bunts toward the pitcher, and it could be a squeeze. You''re the shortstop.', 'What''s your job?', array['Cover second base in case the batter tries for two', 'Cover first base and take the throw for the out', 'Cover third and yell if the runner breaks or strays', 'Cover home plate so the catcher can field the bunt'], 2, 'The third baseman is crashing on the bunt, so third is yours. From there, yell right away if the runner breaks for home or gets too far off the bag.', 'The third baseman left her base to charge, and someone needs eyes on the runner from that spot.', 2, '{"runners":["third"],"outs":0,"you":"SS","ball":{"at":"bunt-P","type":"bunt"},"arrows":[]}'::jsonb, 'Defensive Playbook p.28 · Runner at 3B, <2 outs: bunt with a runner on third'),
  ('position-ss-12', 'position', 'SS', 'position', 1, null, 'Runner on third, two outs. A ground ball single goes into left field, and the run scores. You''re the shortstop.', 'What''s your job?', array['Cover second base and take the throw', 'Go out and line up as the cut to home', 'Cover third base in case she keeps going', 'Go out and set up as the cut to second'], 3, 'The run is in, so the throw goes to second to keep the batter at first. You''re the cut on a ball to left, and the second baseman covers the bag.', 'There''s no play on the runner who scored, so think about the batter and who''s closest to the ball in left.', 2, '{"runners":["third"],"outs":2,"you":"SS","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"home","to":"first","kind":"run"}]}'::jsonb, 'Defensive Playbook p.85 · Runner at 3B, 2 outs: single to left'),
  ('position-ss-13', 'position', 'SS', 'position', 1, null, 'Runner on third, one out. A fly ball goes to medium center field, and the runner is tagging. You''re the shortstop.', 'What''s your job?', array['Chase it until the center fielder calls you off', 'Line up between center and home as the cut', 'Cover third base to watch the runner tag', 'Cover second base in case of a throw there'], 0, 'Chase it hard until the center fielder takes it. On this play the first baseman is the cut to home and the third baseman covers third.', 'A corner infielder handles the plate relay on this play, so what can you do on a ball in the air?', 2, '{"runners":["third"],"outs":1,"you":"SS","ball":{"at":"CF","type":"fly"},"arrows":[]}'::jsonb, 'Defensive Playbook p.36 · Runner at 3B, <2 outs: fly ball to center'),
  ('position-ss-14', 'position', 'SS', 'position', 1, null, 'Runners on first and second, nobody out. The batter bunts it hard toward the third baseman, who charges in. You''re the shortstop.', 'What''s your job?', array['Cover second base for the force there', 'Cover third and tell her if the lead out is there', 'Cover first base for the sure out', 'Back up third base in case of an overthrow'], 1, 'The third baseman left her bag to field it, so you take third. On a hard bunt she may have the lead runner, so tell her loud and early.', 'She left her base to charge, and the lead runner is headed straight for it.', 2, '{"runners":["first","second"],"outs":0,"you":"SS","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[{"from":"second","to":"third","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.38 · Runners at 1B & 2B, <2 outs: hard bunt to the third baseman'),
  ('position-ss-15', 'position', 'SS', 'position', 1, null, 'Runners on first and second, one out. A hard ground ball is hit right at you, and you field it cleanly at your normal depth. You''re the shortstop.', 'Where''s your first throw?', array['Second base', 'First base', 'Home', 'Third base'], 3, 'A hard ball gives you time to go after the lead runner. Get the force at third.', 'When the ball gets to you quickly, go after the runner closest to scoring.', 2, '{"runners":["first","second"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.40 · Runners at 1B & 2B, <2 outs: hard ground ball to the shortstop'),
  ('position-ss-16', 'position', 'SS', 'position', 1, null, 'Bases loaded, one out, infield in. A ground ball goes to the third baseman, who throws home for the force. You''re the shortstop.', 'What''s your job?', array['Cover second base for a force from the catcher', 'Back up home plate behind the catcher on the throw', 'Back her up, then cover third for the catcher''s throw', 'Cover first base for the catcher''s throw'], 2, 'Back up the third baseman first. Once she throws home, third base is empty and the catcher may throw there to finish a double play, so be on the bag.', 'Think two steps: what if she misses it, and then whose bag is open after she throws?', 2, '{"runners":["first","second","third"],"outs":1,"you":"SS","ball":{"at":"3B","type":"ground"},"arrows":[{"from":"3B","to":"home","kind":"throw"},{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.49 · Bases loaded, <2 outs: ground ball to 3B, throw home'),
  ('position-ss-17', 'position', 'SS', 'position', 1, null, 'Bases loaded, nobody out. A ground ball splits the left-center gap. You''re the shortstop.', 'What''s your job?', array['Cover second base and help direct the throw', 'Go out toward the gap as the cut to home', 'Go out toward the gap as the cut to third', 'Cover third base for the trail runner'], 1, 'With the bases loaded the throw goes home, and the ball is on your side. Go out as the cut to the plate; the first baseman sets up as a second cut behind you.', 'Every runner is moving, so where does the throw need to go first and who''s closest on that side?', 2, '{"runners":["first","second","third"],"outs":0,"you":"SS","ball":{"at":"LCF-gap","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.51 · Bases loaded, <2 outs: ground ball into the left-center gap'),
  ('position-ss-18', 'position', 'SS', 'position', 1, null, 'Runners on first and third, nobody out. The batter bunts back to the pitcher. You''re the shortstop.', 'Where do you go?', array['Cover second base', 'Cover third base', 'Cover first base', 'Back up third base'], 0, 'With a runner on first, second base has to be covered for the force. The third baseman gets back to third after she charges, so second is yours.', 'The runner on first is forced to run, and the third baseman can get back to her own bag after charging.', 2, '{"runners":["first","third"],"outs":0,"you":"SS","ball":{"at":"bunt-P","type":"bunt"},"arrows":[]}'::jsonb, 'Defensive Playbook p.54 · Runners at 1B & 3B, <2 outs: bunt to the pitcher'),
  ('position-ss-19', 'position', 'SS', 'position', 1, null, 'Runners on second and third, one out. A fly ball goes to medium left field, and both runners are ready to tag. You''re the shortstop.', 'What''s your job?', array['Cover second base behind the runner', 'Go out and set up as the cut to second', 'Go out and set up as the cut to home', 'Back up the left fielder in case she misses it'], 2, 'The runner on third is tagging to score, so the throw goes home and you''re the cut on a ball to left. Line up between the left fielder and the plate, and listen for the catcher''s call.', 'The most important runner is the one tagging from third, and the ball is on your side of the field.', 2, '{"runners":["second","third"],"outs":1,"you":"SS","ball":{"at":"LF","type":"fly"},"arrows":[]}'::jsonb, 'Defensive Playbook p.69 · Runners at 2B & 3B, <2 outs: fly ball to left'),
  ('position-ss-20', 'position', 'SS', 'position', 1, null, 'Runner on first, two outs. A ground ball pulls the second baseman toward second base. You''re the shortstop.', 'What''s your job?', array['Back up first base in case of an overthrow', 'Back up the second baseman in case it gets by', 'Cover third base in case the runner keeps going', 'Cover second and tell her if the easier out is there'], 3, 'With two outs you only need one. Get to the bag and let her know if second is the quicker throw; she can feed you for the force.', 'She''s moving toward your bag, so which out is closest to her right now?', 2, '{"runners":["first"],"outs":2,"you":"SS","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.76 · Runner at 1B, 2 outs: ground ball pulls the second baseman toward the bag'),
  ('position-ss-21', 'position', 'SS', 'position', 1, null, 'Bases loaded, two outs. A ground ball takes you deep to your right, close to third base. You''re the shortstop.', 'What''s the best play?', array['Throw to third base', 'Throw to first base', 'Throw to second base', 'Throw home'], 0, 'Any force ends the inning, so take the shortest throw. When the ball takes you toward third, that''s the force at third.', 'Every base is a force, so pick the one you can reach fastest from where you fielded it.', 2, '{"runners":["first","second","third"],"outs":2,"you":"SS","ball":{"at":"SS","type":"ground"},"arrows":[]}'::jsonb, 'Defensive Playbook p.94 · Bases loaded, 2 outs: ground ball takes you toward third'),
  ('extra-baserunning-01', 'general', null, 'extra', 1, 'Baserunning · Vocabulary', 'Your coach tells the runners to read every blooper carefully before they commit.', 'What is a blooper?', array['A hard line drive that one-hops the outfield fence', 'A bunt that gets popped up softly in the air', 'A soft fly ball that drops between the infielders and the outfielders', 'A ground ball that takes a high, bad hop over a fielder'], 2, 'A blooper is a fly ball that comes down in the space between infielders and outfielders. Nobody is sure to get there, which is why you read it before you run.', 'Think about where this ball comes down, not how hard it was hit.', 2, null::jsonb, 'Baserunning Playbook p.2 · Blooper'),
  ('extra-baserunning-02', 'general', null, 'extra', 1, 'Baserunning · Vocabulary', 'One out, runners on first and second. The batter bunts, and the pitcher fields it and fires to third to force the runner coming from second, passing up the sure out at first.', 'What is the defense going for?', array['The lead out', 'The trail-runner out', 'A back pick', 'A rundown'], 0, 'Throwing out the runner furthest ahead instead of taking the easy out is called getting the lead out. It''s why the runner from second runs hard and slides into third on a bunt here.', 'Which runner is the throw chasing: the one in front or the one behind?', 2, null::jsonb, 'Baserunning Playbook p.2 · Lead out'),
  ('extra-baserunning-03', 'general', null, 'extra', 1, 'Baserunning · Vocabulary', 'You''re caught between second and third. The shortstop and third baseman are throwing the ball back and forth and closing in to tag you.', 'What is this called?', array['A back pick', 'A force out', 'Obstruction', 'A rundown'], 3, 'A rundown is any time you''re trapped between two bases trying to avoid a tag. Stay alive as long as you can; every extra throw buys time for your teammates to move up.', 'Which of these terms describes a runner stuck between bags, not a play at one?', 2, null::jsonb, 'Baserunning Playbook p.2 · Rundown'),
  ('extra-baserunning-04', 'general', null, 'extra', 1, 'Baserunning · Vocabulary', 'One out, you''re on first. After the pitch you''re still hanging a few steps off the bag when the second baseman sneaks in behind you and the catcher throws to her.', 'What is this play called?', array['A delayed steal', 'A back pick', 'A lead out', 'A rundown'], 1, 'That''s a back pick: a fielder slips in behind you and takes a throw to catch you off the bag. Beat it by getting back hard the moment the pitch is by.', 'Where did the fielder come from, compared with where you were looking?', 2, null::jsonb, 'Baserunning Playbook p.2 · Back pick'),
  ('extra-baserunning-05', 'general', null, 'extra', 1, 'Baserunning · Rules', 'Two outs, you''re on second and running on contact. The batter pops up toward the shortstop, who drifts onto the baseline between second and third, and you run into her just as she''s about to make the catch.', 'What''s the call?', array['Obstruction on her, and you''re awarded third', 'Interference on you, and you''re out', 'Nothing; contact is part of the game', 'Dead ball, and the pitch is replayed'], 1, 'Interference is an offensive player getting in the way of a fielder who''s making a play, and the runner is out. Running on contact with two outs never gives you the right of way; go around her.', 'Who was making a play on the ball, and who got in the way?', 2, '{"runners":["second"],"outs":2,"you":"runner-second","ball":{"at":"SS","type":"popup"},"arrows":[{"from":"second","to":"SS","kind":"run"}]}'::jsonb, 'Baserunning Playbook p.2 · Interference: colliding with a fielder'),
  ('extra-baserunning-06', 'general', null, 'extra', 1, 'Baserunning · Rules', 'Before every pitch, a smart runner knows whether an infield fly could be called.', 'In which of these can the umpire call infield fly?', array['One out, bases loaded, high pop-up to the second baseman', 'One out, runner on first only, high pop-up to the second baseman', 'One out, runners on second and third, high pop-up to the second baseman', 'One out, runners on first and second, high pop-up well foul behind first'], 0, 'Infield fly needs runners on first and second or the bases loaded, plus a pop-up on the infield in fair territory. The batter is out, so the runners aren''t forced to move.', 'The rule protects runners who would be forced if the ball were dropped. Where are the forces, and is the ball fair?', 2, null::jsonb, 'Baserunning Playbook p.2 · Infield fly rule: when it applies'),
  ('extra-baserunning-07', 'general', null, 'extra', 1, 'Baserunning · Rules', 'One out, runners on first and second. You''re on second. The umpire calls infield fly on a pop-up to the second baseman, she drops it, the ball rolls into shallow right field, and you take off for third.', 'How can the defense get you out at third?', array['Touch third with the ball before you get there', 'Throw to second, since you left without tagging up', 'They have to tag you; there''s no force', 'They can''t; infield fly protects you until the next pitch'], 2, 'The call makes the batter out, so nobody is forced. You''re free to try for the next base on a drop, but it''s a tag play, and since the ball was never caught you didn''t need to tag up.', 'With the batter already out, is anyone behind you pushing you to third?', 2, '{"runners":["first","second"],"outs":1,"you":"runner-second","ball":{"at":"2B","type":"popup"},"arrows":[{"from":"second","to":"third","kind":"run"}]}'::jsonb, 'Baserunning Playbook p.2 · Infield fly: advancing on a drop'),
  ('extra-baserunning-08', 'general', null, 'extra', 1, 'Baserunning · Rules', 'One out, you''re on first and you''ve tagged up on a pop-up behind first base in foul ground. The first baseman and second baseman both chase it, nobody covers second, and the ball drops untouched in foul territory.', 'What do you do?', array['Take second, since nobody is covering it', 'Stay off the bag and see where the ball rolls', 'Run to second, since you were tagged up when it landed', 'Go back to first; the ball is dead once it lands foul'], 3, 'A foul ball that hits the ground is dead and every runner returns. An uncovered base only helps you if the ball is caught, which is exactly why you tag on foul pops.', 'What does the umpire call the moment this ball touches foul ground?', 2, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"1B","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Foul pop-up that drops'),
  ('extra-baserunning-09', 'general', null, 'extra', 1, 'Baserunning · Leads, steals & slides', 'One out, you''re on second with first and third empty. You take your four or five hard steps, the batter takes the pitch, and the catcher fires the ball behind you to the shortstop covering second.', 'What do you do?', array['Dive back into second', 'Freeze between the bases until she has the ball', 'Take off for third as soon as the throw goes to second', 'Head for third only if the throw gets past the shortstop'], 2, 'Once the catcher throws to second, the ball is behind you and third is open. Go: the shortstop now needs a catch, a turn and a strong throw to beat you. You only do this when third is empty.', 'Count how many throws the defense needs to get you at each base.', 2, '{"runners":["second"],"outs":1,"you":"runner-second","arrows":[{"from":"C","to":"second","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.30 · Second-base lead: throw behind you'),
  ('extra-baserunning-10', 'general', null, 'extra', 1, 'Baserunning · Leads, steals & slides', 'Your steal tips say that reading the defense tells you whether to go straight in or slide off to one side of the bag.', 'Which of these slides is built to take you to the side of the bag, away from the tag?', array['Hook slide', 'Feet-first slide', 'Head-first slide', 'Pop-up slide'], 0, 'The hook slide carries you to one side of the bag and catches a corner of it as you go by, giving the fielder less of you to tag. Feet-first, head-first and pop-up slides usually go straight at the bag.', 'Three of these go straight at the bag. Which one doesn''t?', 2, null::jsonb, 'Baserunning Playbook p.31 · Hook slide'),
  ('extra-baserunning-11', 'general', null, 'extra', 1, 'Baserunning · Reading the play', 'One out, you''re on first. A ground ball is headed for the right-center gap and you''re running hard, thinking third. The right fielder dives, knocks it down short of the gap, and pops up ready to throw.', 'What now?', array['Keep going to third; it was a gap hit off the bat', 'Pick up your third-base coach as you reach second', 'Turn around and hustle back to first', 'Stop halfway between second and third and wait'], 1, 'A plan built on the ball reaching the gap changes when a fielder makes a great play. Find your coach as you get to second and be ready to stop there if the dive took third away.', 'The ball didn''t do what you expected. Who has the best view of what''s left for you?', 2, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"RF","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.1 · Adjusting to a diving stop'),
  ('extra-baserunning-12', 'general', null, 'extra', 1, 'Baserunning · Reading the play', 'One out, you''re on first. The batter singles into right field. As you near second and look ahead, you see the right fielder picking up the ball with nobody lined up as a cutoff between her and third base.', 'How does that affect your read?', array['It doesn''t matter; only her arm strength counts', 'It''s a reason to hold at second', 'It''s a reason to push for third', 'It means she''ll throw behind you to first'], 2, 'When the defense isn''t lined up for the cut, the throw is longer and less accurate. That''s when an extra base opens up, so be ready to push for it and pick up your coach.', 'What happens to a long throw with nobody on line to relay it?', 2, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"RF","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Reading the cutoff'),
  ('extra-baserunning-13', 'general', null, 'extra', 1, 'Baserunning · Reading the play', 'One out, you''re on first. The batter hits a ground ball to the first baseman, who fields it a few steps behind you and turns to throw to the shortstop covering second.', 'How do you run to second?', array['Stay on your straight line to the bag so she has to throw around you', 'Veer toward the outfield grass to give her a clear throw', 'Stop and get back to first, since she''s behind you', 'Wave your arms as you run to block her view'], 0, 'Your normal line from first to second runs right through her throwing lane. Stay on it, make her throw around you, and slide; that''s how bad throws happen. Never wave at or reach for the ball, which is interference.', 'Where is the ball coming from, and where does your normal path put you?', 2, '{"runners":["first"],"outs":1,"you":"runner-first","ball":{"at":"1B","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.29 · Getting in the throwing lane'),
  ('extra-baserunning-14', 'general', null, 'extra', 1, 'Baserunning · Reading the play', 'One out, you''re on third and the other bases are empty. The infield is playing in, and the batter hits a hard ground ball right at the shortstop.', 'What do you do?', array['Hold until she throws to first, then break for home', 'Run home as soon as it''s hit, like with the infield back', 'Stay at third no matter where she throws', 'Tag up at third and go once she fields it'], 0, 'With the infield in, a hard ball right at a fielder gives her a play at the plate. Judge how hard it was hit: when it gets to her fast, wait for her throw to first and then go.', 'How far is a drawn-in shortstop from home, and how fast did this ball reach her?', 2, '{"runners":["third"],"outs":1,"you":"runner-third","ball":{"at":"SS","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.7 · Runner at 3B: infield playing in'),
  ('extra-baserunning-15', 'general', null, 'extra', 1, 'Baserunning · Reading the play', 'No outs, you''re on first. The batter hits a ground-ball single into left field.', 'How do you handle second base?', array['Stop right on second; it''s only a single', 'Round second hard and keep going to third no matter what', 'Slide into second to be safe', 'Take a slight turn at second and look to your third-base coach'], 3, 'A small turn at second keeps the pressure on, so you''re ready if the left fielder bobbles it or makes a lazy throw. Your third-base coach tells you whether third is there.', 'Who is standing ahead of you with a clear view of the ball and the base?', 2, '{"runners":["first"],"outs":0,"you":"runner-first","ball":{"at":"LF","type":"ground"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.4 · Runner at 1B: single to left'),
  ('extra-baserunning-16', 'general', null, 'extra', 1, 'Baserunning · Batter-runner', 'Nobody on, one out. You pop the ball up high over the second baseman, who settles under it on the infield.', 'How do you run it out?', array['Round first hard, ready for second if she drops it', 'Jog to first, since it''s an easy out', 'Run hard straight through first base', 'Stop halfway and watch the catch'], 2, 'On an infield pop-up, even a drop leaves the ball a few steps from second, so there''s no extra base to set up. Run hard through first and make her catch it.', 'If she drops it, how far is the ball from second base?', 2, '{"runners":[],"outs":1,"you":"batter","ball":{"at":"2B","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.3 · Pop-up on the infield'),
  ('extra-baserunning-17', 'general', null, 'extra', 1, 'Baserunning · Batter-runner', 'Nobody on, one out. You hit a ground ball to the shortstop, and as you run through first her throw sails past the first baseman and rolls toward the fence in foul ground, still in play.', 'What do you do?', array['Stay on first; you already ran through the bag', 'Stop and wait for the umpire to award you a base', 'Walk back to first and ask for time', 'Find the ball as you cross the bag and take second if it''s getting away'], 3, 'The playbook''s reads assume a clean play, and an error changes them. Run through first, find the ball right away, and if it''s rolling away, take second.', 'A throw just got away from the defense. What could that be worth to you if you''re alert?', 2, '{"runners":[],"outs":1,"you":"batter","ball":{"at":"SS","type":"ground"},"arrows":[{"from":"SS","to":"first","kind":"throw"}]}'::jsonb, 'Baserunning Playbook p.1 · Throw gets past first'),
  ('extra-baserunning-18', 'general', null, 'extra', 1, 'Baserunning · Two-out running', 'Two outs, you''re on first. The batter pops up to the first baseman on the infield, and you''re running on contact.', 'What do you do at second?', array['Stop on the bag; the ball is on the infield', 'Take a slight turn past second, ready for third if she drops it', 'Slide into second in case of a throw', 'Keep running to third no matter what'], 1, 'With two outs you run on contact. A drop on the right side happens behind you, far from third, so a slight turn at second sets you up to take it. On the left side, just run to second.', 'Where would the ball be if it hit the ground, and how far is that from third?', 2, '{"runners":["first"],"outs":2,"you":"runner-first","ball":{"at":"1B","type":"popup"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.17 · Pop-up on the right side'),
  ('extra-baserunning-19', 'general', null, 'extra', 1, 'Baserunning · Two-out running', 'Two outs, you''re on third and the other bases are empty. The batter drops a bunt toward third base.', 'What''s your approach?', array['Sprint home on contact, like on any two-out grounder', 'Stay on third no matter what; she''ll throw to first', 'Tag up at third and go once the ball is fielded', 'Read the bunt and the defense; be ready to score, but don''t run into an out'], 3, 'Two outs usually means run on contact, but a bunt stays close to you and the plate. Read where it goes, be ready to go if they throw to first or it gets away, and don''t hand them the third out at home.', 'On a bunt, how close is the fielder to the plate compared with a grounder to short?', 2, '{"runners":["third"],"outs":2,"you":"runner-third","ball":{"at":"bunt-3B","type":"bunt"},"arrows":[]}'::jsonb, 'Baserunning Playbook p.20 · Bunt with a runner on third'),
  ('extra-baserunning-20', 'general', null, 'extra', 1, 'Baserunning · Batter-runner', 'Two outs, runner on first. You swing and miss at strike three, and the pitch bounces in the dirt past the catcher.', 'What do you do?', array['Walk back to the dugout: first base is taken', 'Stay in the box until the umpire says something', 'Run only if the ball rolls all the way to the backstop', 'Run to first: with two outs, you can run even with first base taken'], 3, 'On a dropped third strike you can run when first base is open, or any time there are two outs. With two outs the runner on first is forced to second, so the catcher has to get one of you out. Never assume you''re out: sprint until you are.', 'Does the number of outs change whether first base has to be empty?', 2, '{"runners":["first"],"outs":2,"you":"batter"}'::jsonb, 'GGG.Cafe Softball IQ · Dropped third strike with two outs'),
  ('extra-baserunning-21', 'general', null, 'extra', 1, 'Baserunning · Reading the play', 'One out, you''re on third. The pitch hits the dirt in front of the plate and bounces a few feet to the catcher''s left, still close to her.', 'Do you go?', array['Yes: any ball in the dirt means go', 'No: it stayed close, so take a hard step and get back', 'Yes, but only if the batter swung', 'No: a runner on third never goes on a ball in the dirt'], 1, 'Read where the ball ends up, not the bounce. A ball a step or two from the catcher is an easy out at the plate. Go when it kicks well away from her or gets past her; otherwise take a hard step and get back to the bag.', 'How far does the ball have to get from the catcher to give you time?', 2, '{"runners":["third"],"outs":1,"you":"runner-third"}'::jsonb, 'GGG.Cafe Softball IQ · Ball in the dirt from third'),
  ('extra-baserunning-22', 'general', null, 'extra', 1, 'Baserunning · Batter-runner', 'One out, nobody on. You hit a ground ball to the shortstop and beat the throw by running hard through first. You end up a few steps past the bag in foul territory, and the first baseman tags you.', 'Are you out?', array['Yes: you have to stay on the base', 'Yes: you turned toward second', 'No: you can overrun first, as long as you come straight back and don''t try for second', 'Only if she tagged you before you stopped running'], 2, 'Overrunning first is allowed, so run through the bag at full speed. You can''t be tagged out while you come straight back. You''re only in danger if you try to go to second; which way you turn doesn''t decide it, trying to advance does.', 'What''s the one thing that puts you in danger after you run through the bag?', 2, '{"outs":1,"you":"batter","ball":{"at":"SS","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Running through first'),
  ('extra-defense-01', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Runner on first, one out. The card in your wristband reads "MIF: double-play depth." You''re the catcher, relaying the alignment to your infield.', 'Which two players does that note apply to?', array['The first and third basemen', 'The pitcher and the catcher', 'The second baseman and the shortstop', 'The left and center fielders'], 2, 'MIF stands for middle infield: the second baseman and the shortstop. They''re the pair who turn two at second, so they set up at that depth.', 'Picture the infield from home plate. Which two spots sit in the middle of it?', 2, '{"runners":["first"],"outs":1,"you":"C"}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: MIF'),
  ('extra-defense-02', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Runner on first, nobody out, and the batter squares early to bunt. Your coach yells, "Corners, crash!" You''re the pitcher.', 'Who is she sending in?', array['The first and third basemen', 'The second baseman and the shortstop', 'The catcher and you', 'The left and right fielders'], 0, 'The corners are the first and third basemen, the two infielders at the outside corners of the diamond. On a bunt they charge hard and try to take the ball away from you.', 'Think about the shape of the diamond and which two infielders play out at its edges.', 2, '{"runners":["first"],"outs":0,"you":"P"}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: corners'),
  ('extra-defense-03', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Runner on first, one out. The batter loops a soft fly ball that''s going to drop between the shortstop and you in shallow left. You''re the left fielder.', 'What''s this kind of hit called?', array['A line drive', 'A chopper', 'A gapper', 'A blooper'], 3, 'A blooper is a soft fly that drops past the infielders but short of the outfielders. Call it early: you''re coming in, the shortstop is going out, and one of you has to own it.', 'Where is this ball going to come down: in the infield, in the outfield, or somewhere in between?', 2, '{"runners":["first"],"outs":1,"you":"LF","ball":{"at":"blooper-LF","type":"fly"}}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: blooper'),
  ('extra-defense-04', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Runners on first and third, one out. Your coach tells the infield to know where the trail runner is before every pitch. You''re the shortstop.', 'Which runner is the trail runner?', array['The runner on third', 'The runner on first', 'Both runners', 'Neither runner, until the ball is hit'], 1, 'A trail runner has another runner ahead of her. The runner on third is the lead runner, so the runner on first is the one trailing.', 'Look for the runner who has a teammate somewhere in front of her on the bases.', 2, '{"runners":["first","third"],"outs":1,"you":"SS"}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: trail runner'),
  ('extra-defense-05', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Runner on first, nobody out. Before the pitch, your shortstop calls to the infield, "Lead out if we can get it!" You''re the second baseman.', 'What is she asking for?', array['The first out of the inning, any way you can get it', 'An out on the batter at first, every time', 'Holding the runner close so she can''t take a big lead', 'An out on the runner from first, before she reaches second'], 3, 'A lead out means retiring the lead runner. With only a runner on first, that''s her, at second base, whenever the ball gives you time.', 'The word "lead" here describes a runner, not the order of the outs.', 2, '{"runners":["first"],"outs":0,"you":"2B"}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: lead out'),
  ('extra-defense-06', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Nobody on, nobody out. Your coach warns the outfield that this hitter drives the ball into the right-center gap. You''re the right fielder.', 'Where are those balls going to land?', array['Between you and the center fielder', 'Between you and the right-field foul line', 'Between the first and second basemen', 'Over your head toward the fence'], 0, 'The right-center gap is the space between the center fielder and the right fielder. When a ball goes there, one of you fields it and the other backs her up.', 'A gap is named for the two outfield spots on either side of it.', 2, '{"runners":[],"outs":0,"you":"RF"}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: right-center gap'),
  ('extra-defense-07', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Nobody on, nobody out. Your coach writes the defense on the dugout whiteboard using position numbers only. You''re the catcher, and you need to find who''s playing 6.', 'Which position is number 6?', array['Second baseman', 'Third baseman', 'Shortstop', 'Left fielder'], 2, 'The numbers go pitcher 1, catcher 2, first 3, second 4, third 5, shortstop 6, then left, center and right are 7, 8 and 9. The shortstop is 6, not 5, even though she plays between second and third.', 'First base is 3. Number the infielders who guard a bag before you get to the one who doesn''t.', 2, '{"runners":[],"outs":0,"you":"C"}'::jsonb, 'Defensive Playbook p.3 · Positions by number'),
  ('extra-defense-08', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Runner on third, one out. On a ground ball to the pitcher, the runner breaks for home, stops halfway, and gets stuck between third and home, darting back and forth so nobody can tag her. You''re the catcher.', 'What is this play called?', array['A force play', 'A rundown', 'A squeeze', 'An appeal play'], 1, 'A rundown is a runner trapped between two bases trying to dodge the tag. Set up on the same side of the base path as your teammate so every throw has a clear lane.', 'She isn''t forced anywhere, and she''s caught between two bags.', 2, '{"runners":["third"],"outs":1,"you":"C","ball":{"at":"P","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: rundown'),
  ('extra-defense-09', 'general', null, 'extra', 1, 'Defense · Vocabulary', 'Nobody on, nobody out. The scouting card on the next batter reads: "GB, left side. OF shade left." You''re the center fielder.', 'What is the card telling you?', array['She hits fly balls to left, so the infield moves left', 'She bunts to the left side, so the outfield plays in', 'She hits ground balls to the right side, so the outfield shades right', 'She hits ground balls to the left side, so the outfield shades left'], 3, 'GB is short for ground ball and OF means the outfield (IF is the infield). This hitter rolls the ball to the left side, so you and the other outfielders cheat a few steps that way.', 'Spell out the two abbreviations first: one describes the hit, the other names a group of players.', 2, '{"runners":[],"outs":0,"you":"CF"}'::jsonb, 'Defensive Playbook p.2 · Vocabulary: GB and OF'),
  ('extra-defense-10', 'general', null, 'extra', 1, 'Defense · Communication', 'Nobody on, one out. The batter bunts between the mound and the third-base line. You, the pitcher and the catcher all charge, and you''re the one in position to field it. You''re the third baseman.', 'What do you do as you close in on the ball?', array['Stay quiet so the batter can''t hear the play', 'Call for it loudly so the others peel off', 'Wait for the catcher to tell you it''s yours', 'Let the pitcher take it because she started closer'], 1, 'Whoever fields the bunt claims it, loud and early. That clears the pitcher and catcher out of your way and sends them to their next jobs.', 'Three fielders are converging on one ball. How does everyone know who has it?', 2, '{"runners":[],"outs":1,"you":"3B","ball":{"at":"bunt-3B","type":"bunt"}}'::jsonb, 'Defensive Playbook p.3 · Fielding a bunt: call for it'),
  ('extra-defense-11', 'general', null, 'extra', 1, 'Defense · Communication', 'Nobody on, one out. A ground ball single goes into left field, and you''re the shortstop running out to be the cut to second.', 'Besides lining up, what''s your job as the left fielder picks up the ball?', array['Stay quiet so she can focus on the catch', 'Turn and watch the batter round first', 'Yell loudly so she knows where the throw has to go', 'Point toward home so she looks at the catcher'], 2, 'A cut has to be loud. Give your outfielder a big target and your voice, so she knows exactly where the ball is going before she lets it go.', 'Your outfielder needs a target and a call before she throws. How do you give her both?', 2, '{"runners":[],"outs":1,"you":"SS","ball":{"at":"LF","type":"ground"}}'::jsonb, 'Defensive Playbook p.5 · The cut: talk to the outfielder'),
  ('extra-defense-12', 'general', null, 'extra', 1, 'Defense · Communication', 'Nobody on, one out. A ground ball single rolls into right field. You''re the second baseman going out to be the cut on the throw to second.', 'How do you make sure you''re lined up correctly?', array['Peek back at second base as you set up', 'Line up with the batter-runner instead of the bag', 'Stand wherever the right fielder points', 'Always stop on the edge of the infield dirt'], 0, 'Your line runs from the ball to the bag, so take a quick look at second while you set up. Teammates can also steer you left or right if you drift.', 'A straight line needs two points. You can see the ball; what else do you need to see?', 2, '{"runners":[],"outs":1,"you":"2B","ball":{"at":"RF","type":"ground"}}'::jsonb, 'Defensive Playbook p.5 · The cut: check your line'),
  ('extra-defense-13', 'general', null, 'extra', 1, 'Defense · Communication', 'Runner on third, one out. A ground ball single goes into left field, the runner from third scores easily, and the batter stops at first. You''re the pitcher.', 'What''s your job on this play?', array['Back up home plate', 'Back up third base', 'Cover first base', 'Help call where the left fielder should throw'], 3, 'The run is already in, and the throw is headed to second to keep the batter at first. The right fielder backs up second, so you help the outfield with where the ball goes.', 'No play is coming at the plate, and someone else already has the backup behind second.', 2, '{"runners":["third"],"outs":1,"you":"P","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.33 · Runner at 3B: pitcher on a single to left'),
  ('extra-defense-14', 'general', null, 'extra', 1, 'Defense · Communication', 'Runner on third, one out. A ground ball single goes into center field, on the right-field side of the center fielder. The run will score, and the throw is going to second to hold the batter. You''re the second baseman, and you and the shortstop both broke toward the ball.', 'How should the two of you split the jobs?', array['You cover second and she''s the cut, no matter where the ball is', 'You go out as the cut and she covers second, and you both say it out loud', 'You both go out to the ball and the pitcher covers second', 'You cover first and she handles the throw alone'], 1, 'On a ball to center, the middle infielder on the side it''s hit becomes the cut and the other takes the bag. Talk it out so you don''t both end up in the outfield or both on second.', 'Which of you is closer to the ball, and which of you can get back to the bag faster?', 2, '{"runners":["third"],"outs":1,"you":"2B","ball":{"at":"CF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.33 · Ball to CF on the 2B side: who cuts'),
  ('extra-defense-15', 'general', null, 'extra', 1, 'Defense · Score and speed', 'Runner on first, one out, and your team leads 9-1. A ground ball splits the left-center gap. You get to it first, and the runner from first is already rounding second. You''re the left fielder.', 'With that lead, where does your throw go?', array['Through the cut to home', 'Through the cut to third', 'Through the cut to second', 'Straight to first base'], 2, 'On a gap ball you normally set up for the lead runner. Up by a lot, one run doesn''t matter, so keep the batter out of scoring position and get the ball to second.', 'When the score isn''t close, think about which runner you can still keep from reaching scoring position.', 2, '{"runners":["first"],"outs":1,"you":"LF","ball":{"at":"LCF-gap","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.5 · Gap ball, big lead: play the trail runner'),
  ('extra-defense-16', 'general', null, 'extra', 1, 'Defense · Score and speed', 'Runner on first, one out, tie game. A ground ball splits the right-center gap and you''re the first one to it. Normally you''d play for the lead runner. You''re the center fielder.', 'Which of these would switch your play to the trail runner?', array['The runner from first is one of the fastest players in the league', 'The runner from first is slow and just rounding second', 'The batter is the fastest player on her team', 'It''s the last inning and the game is tied'], 0, 'If the lead runner has the speed to beat any throw, don''t waste it on her. Go after the trail runner and keep her from taking extra bases.', 'Ask yourself whether a throw ahead of the lead runner can realistically beat her.', 2, '{"runners":["first"],"outs":1,"you":"CF","ball":{"at":"RCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.5 · Gap ball: when to play the trail runner'),
  ('extra-defense-17', 'general', null, 'extra', 1, 'Defense · Score and speed', 'Runner on second, one out. The batter is the fastest player in the conference. A ground ball comes to you at shortstop, a couple of steps to your left.', 'What does her speed change about your play?', array['Nothing; always take as long as you need to check the runner', 'Throw to third, since she''ll beat any throw to first', 'Hold the ball until the runner at second commits', 'A long look at the runner can cost you the out at first'], 3, 'With a fast batter you may not have time to check the runner and still get the out at first. Keep the look quick, or skip it if the ball took you too long to field.', 'Count how many steps she''ll take while your eyes are on second base.', 2, '{"runners":["second"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.1 · Fast batter: checking the runner'),
  ('extra-defense-18', 'general', null, 'extra', 1, 'Defense · Score and speed', 'Runner on third, one out, and your team leads 10-1 in the last inning. A routine ground ball comes to you at second base, and the runner on third breaks for home with a good jump.', 'With that lead, what''s the smart play?', array['Take the sure out at first and let the run score', 'Throw home and try to cut down the run', 'Fake to first, then throw home', 'Run the ball toward third to freeze her'], 0, 'The score changes how much one runner matters. Up nine in the last inning, a run can''t hurt you, so get the out you know you''ll get.', 'Which matters more in this game right now: one more run for them, or one more out for you?', 2, '{"runners":["third"],"outs":1,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"}]}'::jsonb, 'Defensive Playbook p.1 · Big lead: take the sure out'),
  ('extra-defense-19', 'general', null, 'extra', 1, 'Defense · Score and speed', 'Runners on first and third, one out, and your team leads 6-1. The runner on third is one of the slowest on her team. You''re the shortstop, setting up before the pitch.', 'Where should the middle infielders play?', array['In on the grass to cut off the run at home', 'Both shaded toward first to hold the runner', 'Back at double-play depth', 'Shortstop in and second baseman back'], 2, 'With a slow runner at third and a comfortable lead, that run isn''t your biggest worry. Play the middle infield back so one ground ball can become two outs.', 'Weigh what one run costs you against what two outs on one swing would do.', 2, '{"runners":["first","third"],"outs":1,"you":"SS"}'::jsonb, 'Defensive Playbook p.56 · First and third: middle infield back'),
  ('extra-defense-20', 'general', null, 'extra', 1, 'Defense · Score and speed', 'Runners on first and third, one out, and your team leads 8-2. You catch a fly ball in medium center. The runner on third, the fastest player on her team, tags and will score easily, and the runner on first tags to go to second. You''re the center fielder.', 'Where should your throw go?', array['Home, through the first baseman', 'Second base', 'Third base', 'First base'], 1, 'The throw usually goes home, but a lopsided score and a fast runner at third can change that. She''s scoring anyway and the run doesn''t matter, so get the ball to second and keep the other runner out of scoring position.', 'If that run is going to score no matter what, which runner can you still stop?', 2, '{"runners":["first","third"],"outs":1,"you":"CF","ball":{"at":"CF","type":"fly"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.61 · First and third, fly ball: throw to 2B'),
  ('extra-defense-21', 'general', null, 'extra', 1, 'Defense · Bases loaded', 'Bases loaded, one out, close game. Before the pitch your coach yells, "IF in!" You''re the third baseman.', 'What does she want?', array['The outfield moves in to play shallow', 'The middle infielders drop back to turn two', 'Every infielder stands on her base', 'The infield moves in to cut down the lead runner at home'], 3, 'IF is the infield. Playing in shortens your throw to the plate, so a ground ball can cut down the lead runner there; the other option is to keep the middle infielders back and play for two.', 'Decode the two letters first, then think about which runner a shorter throw is meant to stop.', 2, '{"runners":["first","second","third"],"outs":1,"you":"3B"}'::jsonb, 'Defensive Playbook p.47 · Bases loaded: IF in'),
  ('extra-defense-22', 'general', null, 'extra', 1, 'Defense · Bases loaded', 'Bases loaded, one out. A hard ground ball single comes right at you in left, and you field it fast. The runner from third will score easily, and the runner from second got a slow start. The catcher yells, "Three!" You''re the left fielder.', 'What can a throw to third get you here?', array['A force out on the runner from second, or at least the runners held at first and second', 'A tag out on the runner from third before she scores', 'An automatic out on the batter if third is covered', 'A double play, because the runner from third has to go back and tag up'], 0, 'On a base hit with the bases loaded, every runner has to move up. The runner from second must reach third, so a quick throw there is a force out, and even if she beats it, the runners behind her stay at first and second.', 'The batter became a runner, so think about what that does to every runner ahead of her.', 2, '{"runners":["first","second","third"],"outs":1,"you":"LF","ball":{"at":"LF","type":"ground"},"arrows":[{"from":"third","to":"home","kind":"run"},{"from":"second","to":"third","kind":"run"},{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.50 · Bases loaded, single to LF: throw to 3B'),
  ('extra-defense-23', 'general', null, 'extra', 1, 'Defense · Bases loaded', 'Bases loaded, two outs. A high chopper bounces just in front of the plate, and you charge in and field it a few steps from home. The catcher is on the plate. You''re the pitcher.', 'Where''s your best play?', array['First base', 'Second base', 'Home to the catcher', 'Third base'], 2, 'With two outs you usually take the out at first. When the ball pulls you toward the plate, the catcher is a short toss away and the force is on at home, so give it to her.', 'Compare the length of each throw from where you''re standing.', 2, '{"runners":["first","second","third"],"outs":2,"you":"P","ball":{"at":"P","type":"ground"}}'::jsonb, 'Defensive Playbook p.93 · Bases loaded, 2 outs: ball takes you home'),
  ('extra-defense-24', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Runner on second, one out. Ground ball to you at shortstop. You field it and look the runner back before you throw.', 'What tells you to go after her instead of throwing to first?', array['She takes a short lead off the bag', 'She turns her hips or commits toward a base', 'The third-base coach starts yelling', 'She looks over at you'], 1, 'A runner standing a step off the bag hasn''t committed to anything. Once her hips turn or she commits toward a base, she''s yours: go after her instead of throwing.', 'Watch the part of her body that shows which way she''s really going.', 2, '{"runners":["second"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'Defensive Playbook p.2 · Check the lead runner: when to go after her'),
  ('extra-defense-25', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Runner on first, one out. A medium-speed ground ball comes to you at second base, right in the base path. The runner from first is a step away from you as you field it, and the shortstop is still a few strides from the bag.', 'What''s your best play?', array['Wait for the shortstop to reach second, then throw there', 'Throw to first and let the runner go', 'Chase the runner back toward first', 'Tag the runner, then throw to first'], 3, 'When the lead runner is right on top of you, the tag is your quickest out. Put it on her, then throw to first for the double play.', 'She''s within arm''s reach. Why throw anywhere for that out?', 2, '{"runners":["first"],"outs":1,"you":"2B","ball":{"at":"2B","type":"ground"},"arrows":[{"from":"first","to":"second","kind":"run"}]}'::jsonb, 'Defensive Playbook p.14 · Runner at 1B: tag her, then throw to 1B'),
  ('extra-defense-26', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Runners on first and second, one out. A ground ball to your left pulls you several steps off the bag toward second base. The shortstop is covering second. You''re the first baseman.', 'Where''s your play?', array['Throw to second base', 'Race back and step on first', 'Throw across to third', 'Throw home'], 0, 'Near the bag you''d step on first, but this ball took you toward second. The force there is the short, easy throw, and the shortstop can try to finish two.', 'You''ve moved away from your own bag. Which base is now closest to you?', 2, '{"runners":["first","second"],"outs":1,"you":"1B","ball":{"at":"1B","type":"ground"}}'::jsonb, 'Defensive Playbook p.39 · 1st & 2nd: grounder pulls 1B toward second'),
  ('extra-defense-27', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Runner on first, nobody out. The bunt rolls about ten feet up the third-base line, and you have to chase it toward the line to pick it up. You''re the catcher.', 'Where do you throw?', array['Second base', 'Third base', 'First base', 'Hold it and check the runner'], 2, 'A bunt right at you lets you turn and fire to second. When you have to chase it off to the side, take the sure out at first, where the second baseman is covering.', 'Think about your angle and footwork after chasing a ball away from the plate.', 2, '{"runners":["first"],"outs":0,"you":"C","ball":{"at":"bunt-C","type":"bunt"}}'::jsonb, 'Defensive Playbook p.12 · Runner at 1B: bunt off to the side'),
  ('extra-defense-28', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Runners on first and second, two outs. A slow roller dies on the grass, and you charge in several steps from your bag to field it. You''re the third baseman.', 'Where''s your throw?', array['Race back and step on third', 'First base', 'Second base', 'Home'], 1, 'On a ball hit hard right at you, stepping on third ends the inning. When the ball pulls you in or comes slowly, the bag is behind you, so take the out at first.', 'Your momentum is carrying you toward the plate, and the bag you''d normally step on is behind you.', 2, '{"runners":["first","second"],"outs":2,"you":"3B","ball":{"at":"3B","type":"ground"}}'::jsonb, 'Defensive Playbook p.89 · 1st & 2nd, 2 outs: slow roller to 3B'),
  ('extra-defense-29', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Runner on first, one out. A hard ground ball pulls the first baseman well off her bag, and she throws to the shortstop at second for the force. You were moving behind the first baseman to back up the ball. You''re the second baseman.', 'Where do you go now?', array['Back up the shortstop at second', 'Stay behind the first baseman', 'Cover second base yourself', 'Get to first base for the return throw'], 3, 'When the first baseman fields away from her bag, first is empty. Get there so the shortstop has a target to finish the double play.', 'After the force at second, someone has to take the next throw. Which bag has nobody on it?', 2, '{"runners":["first"],"outs":1,"you":"2B","ball":{"at":"1B","type":"ground"},"arrows":[{"from":"1B","to":"second","kind":"throw"}]}'::jsonb, 'Defensive Playbook p.14 · Runner at 1B: covering first on a 3-6-3'),
  ('extra-defense-30', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Nobody on, one out. A ground ball splits the left-center gap, and the batter is digging for extra bases. The right fielder is coming in behind second. You''re the pitcher.', 'Where do you go?', array['Back up third base', 'Back up second base', 'Back up home plate', 'Cover first base'], 0, 'On a gap ball the batter may try for third, and the shortstop''s relay could go there. Get behind third so an overthrow doesn''t hand her home.', 'The right fielder already has one bag covered. Which base is the batter''s next target after that?', 2, '{"runners":[],"outs":1,"you":"P","ball":{"at":"LCF-gap","type":"ground"}}'::jsonb, 'Defensive Playbook p.9 · No runners: pitcher on a left-center gap ball'),
  ('extra-defense-31', 'general', null, 'extra', 1, 'Defense · Situations', 'A fly ball drops between you in center and the left fielder. You both call for it.', 'Who takes it?', array['The left fielder, because she called it first', 'You, the center fielder: center has priority over the corners', 'Whoever is closer to the infield', 'Let it drop and play it on a hop'], 1, 'The center fielder has priority over the corner outfielders. Call it loud and take it; the left fielder peels off and backs you up.', 'Who is the captain of the outfield?', 2, '{"runners":[],"outs":1,"you":"CF","ball":{"at":"LCF-gap","type":"fly"}}'::jsonb, 'GGG.Cafe Softball IQ · Outfield priority'),
  ('extra-defense-32', 'general', null, 'extra', 1, 'Defense · Situations', 'A short fly ball between you at shortstop and the left fielder. You''re going back, she''s coming in.', 'Who takes it?', array['You, the shortstop', 'The left fielder: she''s coming in and has the easier catch', 'Whoever is taller', 'Neither: let it drop'], 1, 'An outfielder coming in has priority over an infielder going back. Coming in, she sees the ball and the play in front of her.', 'Which way is each of you moving?', 2, '{"runners":[],"outs":0,"you":"SS","ball":{"at":"blooper-LF","type":"blooper"}}'::jsonb, 'GGG.Cafe Softball IQ · Outfielder over infielder'),
  ('extra-defense-33', 'general', null, 'extra', 1, 'Defense · Situations', 'Tie game, bottom of the 7th, one out, runner on third. A foul fly drifts toward the line in right and you can catch it moving toward the fence.', 'What do you do?', array['Catch it: an out is an out', 'Let it drop foul: catching it lets the winning run tag and score', 'Catch it and throw home', 'Catch it, then drop it on purpose'], 1, 'Late in a tie game with the winning run on third, a catch moving away from home lets her tag up and score. Let the foul ball drop and get another pitch.', 'What can the runner on third do after a catch?', 2, '{"runners":["third"],"outs":1,"you":"RF","ball":{"at":"RF-line","type":"fly"}}'::jsonb, 'GGG.Cafe Softball IQ · Foul fly, winning run on third'),
  ('extra-defense-34', 'general', null, 'extra', 1, 'Defense · Situations', 'Runner on second, two outs. A ground ball comes to you at shortstop.', 'Where''s your throw?', array['To third, to stop the runner', 'First base: the sure out ends the inning', 'Home', 'Hold the ball'], 1, 'With two outs, any out ends the inning. Take the sure out at first instead of a harder throw for the lead runner.', 'How many outs do you need?', 2, '{"runners":["second"],"outs":2,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Just get the out'),
  ('extra-defense-35', 'general', null, 'extra', 1, 'Defense · Situations', 'A fast left-handed slapper chops a ground ball toward you at shortstop.', 'What do you have to do?', array['Stay back and wait for a good hop', 'Charge it and throw on the run', 'Let the third baseman take it', 'Throw to second'], 1, 'A fast slapper is halfway to first before the ball reaches you. Waiting on the hop gives her the base: charge hard and make the throw on the run.', 'How far up the line is she already?', 2, '{"runners":[],"outs":0,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Slapper on the ground'),
  ('extra-defense-36', 'general', null, 'extra', 1, 'Defense · Pickoffs and rundowns', 'Runner on third, one out. She takes a long walking lead down the line after every pitch and jogs back. You''re the catcher, and your third baseman is playing a few steps off the bag.', 'When is it safe to throw behind the runner?', array['Any time she''s more than two steps off', 'Right after a ball, never after a strike', 'Never: throws to third are too risky', 'Only when your third baseman has broken back to the bag on your sign'], 3, 'A throw to an empty base rolls into left field and the run scores. A pickoff at third is a set play: give the sign, your third baseman breaks to the bag as the pitch arrives, and you throw only when she''s there.', 'Where does the ball end up if nobody is at the base?', 2, '{"runners":["third"],"outs":1,"you":"C","arrows":[{"from":"C","to":"third","kind":"throw"}]}'::jsonb, 'GGG.Cafe Softball IQ · Catcher''s pickoff at third'),
  ('extra-defense-37', 'general', null, 'extra', 1, 'Defense · Pickoffs and rundowns', 'Runner on first, one out. She''s caught too far off the base and is trapped between first and second. You''re the shortstop with the ball near second, and the first baseman is at her bag.', 'What do you do?', array['Run hard at her and drive her back toward first', 'Stay on second and wait for her to come to you', 'Throw to first as soon as she moves', 'Let her go and hold the batter'], 0, 'Always run a trapped runner back toward the base she came from, so she''s no better off if the play goes wrong. Sprint at her with the ball up where your partner can see it, make her commit, then make one firm throw for the tag.', 'If the rundown goes wrong, where would you rather she end up?', 2, '{"runners":["first"],"outs":1,"you":"SS"}'::jsonb, 'GGG.Cafe Softball IQ · Rundown between first and second'),
  ('extra-defense-38', 'general', null, 'extra', 1, 'Defense · Pickoffs and rundowns', 'Runner on third, nobody out. A pitch bounces off your shin guards and stays close. The runner breaks for home, then stops, and she''s trapped between third and home. You''re the catcher with the ball.', 'What do you do?', array['Run her back toward third, then throw to the third baseman for the tag', 'Throw to third right away', 'Stand on the plate and wait for her', 'Throw to first to get the batter'], 0, 'Run her back toward third, the base she came from, so the run can''t score if something goes wrong. Run at her hard with the ball showing, make her commit, and give one throw to your third baseman.', 'Which mistake costs your team a run?', 2, '{"runners":["third"],"outs":0,"you":"C"}'::jsonb, 'GGG.Cafe Softball IQ · Rundown between third and home'),
  ('extra-defense-39', 'general', null, 'extra', 1, 'Defense · Situations', 'Runners on second and third, nobody out. A pitch skips past the catcher to the backstop. The runner on third scores, and the runner from second rounds third. You''re the pitcher covering home.', 'What do you do?', array['Stay on the plate, call for the ball and be ready to tag the second runner', 'Leave home and back up third', 'Head back to the circle', 'Run toward the backstop to get the ball yourself'], 0, 'Covering home on a passed ball doesn''t end when the first run scores. The trail runner may try to score too. Stay on the plate, give the catcher a target, and be ready for the tag.', 'Is anyone else still running?', 2, '{"runners":["second","third"],"outs":0,"you":"P","arrows":[{"from":"third","to":"home","kind":"run"},{"from":"second","to":"third","kind":"run"},{"from":"P","to":"home","kind":"run"}]}'::jsonb, 'GGG.Cafe Softball IQ · Passed ball with two runners in scoring position'),
  ('extra-defense-40', 'general', null, 'extra', 1, 'Defense · Cutoffs and backups', 'Runner on first, one out. A line drive lands fair down the left-field line and rolls into the corner. You''re the shortstop.', 'Where do you go?', array['Out toward the corner as the relay, lined up with the base the throw is going to', 'Cover second base', 'Cover third base', 'Back up home'], 0, 'On a ball down the left-field line, the shortstop is the relay. Get out toward the corner, line up between the left fielder and the target, and give her a big target with both arms up. The third baseman stays at third and the second baseman covers second.', 'Which infielder can leave her base and get closest to the left-field corner?', 2, '{"runners":["first"],"outs":1,"you":"SS","ball":{"at":"LF-line","type":"line"}}'::jsonb, 'GGG.Cafe Softball IQ · Ball down the left-field line'),
  ('extra-defense-41', 'general', null, 'extra', 1, 'Defense · Cutoffs and backups', 'Nobody on, nobody out. A ground ball rolls into the right-field corner, and the batter is thinking two. The second baseman sprints out toward the corner as the relay. You''re the shortstop.', 'Where do you go?', array['Back up the relay in shallow right', 'Cover third base', 'Back up first base', 'Cover second base'], 3, 'When the second baseman goes out as the relay, second base is empty. The shortstop covers it for the play on the batter.', 'The second baseman just left her base. Who fills it?', 2, '{"outs":0,"you":"SS","ball":{"at":"RF-line","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Ball down the right-field line'),
  ('extra-defense-42', 'general', null, 'extra', 1, 'Defense · Cutoffs and backups', 'Runner on first, nobody out. The runner steals on the pitch, and the catcher throws to the shortstop covering second. You''re the center fielder.', 'Where should you be?', array['Stay in your spot in case the ball is hit', 'Behind first base', 'Behind second base, in line with the throw', 'Moving toward left field'], 2, 'Every throw needs a backup. On a steal of second, the center fielder charges in behind the bag in line with the throw, so a ball that gets past the shortstop doesn''t roll into the outfield and send the runner to third.', 'If the throw gets past the shortstop, where does it roll?', 2, '{"runners":["first"],"outs":0,"you":"CF","arrows":[{"from":"first","to":"second","kind":"steal"},{"from":"C","to":"SS","kind":"throw"}]}'::jsonb, 'GGG.Cafe Softball IQ · Backing up a steal'),
  ('extra-defense-43', 'general', null, 'extra', 1, 'Defense · Reading the play', 'Runner on first, nobody out. The batter squares early to bunt, and you charge in from third. As the pitcher releases, the batter pulls the bat back to swing away. You''re the third baseman.', 'What do you do?', array['Keep charging: the bunt is still coming', 'Stop your feet, get square to the hitter and be ready to react', 'Turn and sprint back to third', 'Wave the shortstop over to cover third'], 1, 'When the bat pulls back, the slash is on. Keep charging and you''re too close to react to a full swing; sprint back and your back is to the ball. Stop, get square and low, and react to whatever comes off the bat.', 'What do the hitter''s hands tell you, and how much time will you have to react up close?', 2, '{"runners":["first"],"outs":0,"you":"3B"}'::jsonb, 'GGG.Cafe Softball IQ · Fake bunt and slash'),
  ('extra-defense-44', 'general', null, 'extra', 1, 'Defense · Cutoffs and backups', 'Runner on first, one out. Single to right field, and the runner from first is heading for third. You''re the pitcher.', 'Where do you go?', array['Stay in the circle', 'Cover home', 'Back up third, in line with the throw from right', 'Cover second base'], 2, 'When the throw is going to third, the pitcher backs it up. Get well behind third base, in line with the throw, so an overthrow doesn''t roll away and send the runner home.', 'Which base is the throw going to, and who''s free to get behind it?', 2, '{"runners":["first"],"outs":1,"you":"P","ball":{"at":"RF","type":"ground"},"arrows":[{"from":"first","to":"third","kind":"run"},{"from":"RF","to":"third","kind":"throw"}]}'::jsonb, 'GGG.Cafe Softball IQ · Pitcher backs up third'),
  ('extra-defense-45', 'general', null, 'extra', 1, 'Defense · Pickoffs and rundowns', 'Runner on second, one out. On a ground ball to you at shortstop, the runner breaks for third, then stops, and she''s trapped between second and third. You have the ball, and the batter is running to first.', 'Which way do you chase her?', array['Back toward second, the base she came from', 'Toward third, so you can tag her at the bag', 'Toss it to the third baseman right away', 'Nowhere: hold the ball and wait for her to move'], 0, 'Run her back toward second. If the rundown goes wrong, she''s back where she started instead of on third. Keep the ball up where your teammates can see it, and watch the batter: she''ll try to sneak into second while everyone is busy.', 'Which base did she start from?', 2, '{"runners":["second"],"outs":1,"you":"SS","ball":{"at":"SS","type":"ground"}}'::jsonb, 'GGG.Cafe Softball IQ · Rundown between second and third'),
  ('scorebook-1-01', 'general', null, 'scorebook', 1, null, 'Your coach hands you the batting order before the game.', 'Where does it go?', array['The lineup column on your team''s page', 'The top of the 1st inning column', 'The totals along the bottom', 'On the other team''s page'], 0, 'The lineup column down the left side of your team''s page holds the batting order: spot, jersey number and name.', 'One column lists every batter in the order they hit.', 1, '{"kind":"sheet","innings":3,"names":false}'::jsonb, 'How to Keep the Book · Chapter 1 · scorekeeping guide p.8'),
  ('scorebook-1-02', 'general', null, 'scorebook', 1, null, 'It''s the 4th inning and you want to check every play from the 3rd, in the order they happened.', 'Where do you look?', array['Across the leadoff batter''s row', 'Down the 3rd inning column', 'In the stat columns on the right', 'In the lineup column'], 1, 'Each inning has its own column. Reading down it shows the inning batter by batter.', 'Innings run one direction on the page and batters run the other.', 1, null::jsonb, 'How to Keep the Book · Chapter 1 · scorekeeping guide p.9'),
  ('scorebook-1-03', 'general', null, 'scorebook', 1, null, 'A parent asks how #11 did at the plate today.', 'Where''s the fastest place to find all of her at-bats?', array['Down the 1st inning column', 'Across #11''s row', 'Along the bottom of the page', 'On the other team''s page'], 1, 'Every batter has her own row. Reading across it shows each trip she made to the plate, inning by inning.', 'You want one batter, not one inning.', 1, null::jsonb, 'How to Keep the Book · Chapter 1 · scorekeeping guide p.10'),
  ('scorebook-1-04', 'general', null, 'scorebook', 1, null, 'Three outs end the top of the 1st, and the other team comes up to bat.', 'What do you do?', array['Keep writing in the same column', 'Turn to the other team''s page and score their at-bats there', 'Start a new column on your team''s page', 'Stop until your team bats again'], 1, 'Each team has its own page. When the half-inning flips, so do you.', 'How many pages does one game use?', 1, null::jsonb, 'How to Keep the Book · Chapter 1 · scorekeeping guide p.11'),
  ('scorebook-1-05', 'general', null, 'scorebook', 1, null, 'You''re new to keeping the book and the game is moving fast.', 'Which part can wait until after the game?', array['Writing each batter''s result in her box', 'Marking the outs', 'Adding up the at-bats, runs and hits columns', 'Following the batting order'], 2, 'The stat columns and totals are counted once the game is over. During the game, focus on the lineup and the boxes.', 'Which part is math you can do from the boxes later?', 1, '{"kind":"sheet","innings":2,"stats":true}'::jsonb, 'How to Keep the Book · Chapter 1 · scorekeeping guide p.7'),
  ('scorebook-2-01', 'general', null, 'scorebook', 2, null, 'The game starts before you get the other team''s lineup.', 'What do you write as each batter steps in?', array['Her jersey number', 'Nothing until the lineup arrives', 'Her fielding position', 'The pitcher''s number'], 0, 'Write the number as she comes up and fill in the names later. Numbers are what you track all game.', 'What can you read off a player from the stands?', 1, null::jsonb, 'How to Keep the Book · Chapter 2 · scorekeeping guide p.14'),
  ('scorebook-2-02', 'general', null, 'scorebook', 2, null, 'Here''s your page. The last out of the 2nd inning was made by your 9th batter.', 'Who leads off the 3rd, and where does her at-bat go?', array['The 9th batter, in the 3rd inning column', 'The 1st batter, in the 3rd inning column', 'The 1st batter, in the 2nd inning column', 'The 2nd batter, in the 3rd inning column'], 1, 'The order picks up right after the batter who made the last out, so the 1st batter leads off, in the next inning''s column.', 'Two steps: who''s next in the order, then which column.', 1, '{"kind":"sheet","innings":3,"cells":{"1-1":{"hit":1,"path":1},"2-1":{"play":"F8","out":1},"3-1":{"play":"6-3","out":2},"4-1":{"play":"K","out":3,"lastOut":true},"5-2":{"play":"4-3","out":1},"6-2":{"hit":2,"path":2},"7-2":{"play":"F7","out":2},"8-2":{"reached":"BB","path":1},"9-2":{"play":"5-3","out":3,"lastOut":true}},"squiggle":{"inning":1,"fromRow":5}}'::jsonb, 'How to Keep the Book · Chapter 2 · scorekeeping guide p.17'),
  ('scorebook-2-03', 'general', null, 'scorebook', 2, null, 'The third out of the inning is a fly ball caught in center field.', 'After writing F8 and the 3 in her box, what else marks the end of the inning?', array['Circle her row number', 'A slash across the lower-right corner of her box', 'Shade her diamond', 'Write the score in her box'], 1, 'A short slash across the corner of the last batter''s box shows exactly where the inning ended.', 'It''s a quick mark in the out corner.', 1, null::jsonb, 'How to Keep the Book · Chapter 2 · scorekeeping guide p.16'),
  ('scorebook-2-04', 'general', null, 'scorebook', 2, null, 'Your leadoff batter grounds out to start the game.', 'Which box does her at-bat go in?', array['The top box of the inning 1 column', 'The bottom box of the inning 1 column', 'Any open box in her row', 'The space next to her name'], 0, 'The first batter of the game takes the first box: her row, inning 1. Each batter after her takes the next box down.', 'Her row, and the first inning.', 1, '{"kind":"sheet","innings":3}'::jsonb, 'How to Keep the Book · Chapter 2 · scorekeeping guide p.15'),
  ('scorebook-2-05', 'general', null, 'scorebook', 2, null, 'In the 4th inning your whole lineup bats, and your leadoff batter comes up again before the third out.', 'Where does her second at-bat of the inning go?', array['In the same box, over her first at-bat', 'In the next column over, with the inning number written above it', 'In the totals at the bottom', 'Nowhere, it isn''t recorded'], 1, 'Her 4th inning box is already used, so her second trip goes in the next column, marked with the inning so the story stays in order.', 'Every trip to the plate needs a box of its own.', 1, null::jsonb, 'How to Keep the Book · Chapter 2'),
  ('scorebook-3-01', 'general', null, 'scorebook', 3, null, 'Here''s the count marked in a batter''s box.', 'What''s the count?', array['3 balls, 2 strikes', '2 balls, 3 strikes', '3 balls, 1 strike', 'Ball four: she walked'], 0, 'The top row is balls and the bottom row is strikes. Three and two filled is a full count.', 'Which row is for balls?', 1, '{"kind":"box","balls":3,"strikes":2}'::jsonb, 'How to Keep the Book · Chapter 3 · scorekeeping guide p.21'),
  ('scorebook-3-02', 'general', null, 'scorebook', 3, null, 'Here''s a batter''s box after her at-bat.', 'How did she get to first?', array['A single', 'A walk', 'She was hit by a pitch', 'A sacrifice'], 2, 'HP is circled: hit by pitch. A single would circle the 1, and a walk would circle BB.', 'Look at what''s circled in the lower-left corner.', 1, '{"kind":"box","balls":1,"reached":"HP","path":1}'::jsonb, 'How to Keep the Book · Chapter 3 · scorekeeping guide p.22'),
  ('scorebook-3-03', 'general', null, 'scorebook', 3, null, 'Here''s another batter''s box.', 'What did she do?', array['Hit a single', 'Hit a double', 'Walked', 'Reached on an error'], 1, 'The 2 is circled and her line runs from home to first to second: a double.', 'Check the numbers across the top and how far her line goes.', 1, '{"kind":"box","hit":2,"path":2}'::jsonb, 'How to Keep the Book · Chapter 3 · scorekeeping guide p.25'),
  ('scorebook-3-04', 'general', null, 'scorebook', 3, null, 'Jordan, #21, singles and drives in Avery from second. This is Avery''s box.', 'What goes in the triangle under home plate?', array['A 2, for the base Avery scored from', '21', 'A 1, for the single', 'Avery''s own number'], 1, 'The triangle credits the RBI, so it gets the jersey number of the batter who drove her in: 21.', 'Who gets credit for driving her in?', 1, '{"kind":"box","hit":1,"path":4}'::jsonb, 'How to Keep the Book · Chapter 3 · scorekeeping guide p.23'),
  ('scorebook-3-05', 'general', null, 'scorebook', 3, null, 'The first batter of the inning grounds out.', 'What number goes in the out corner of her box?', array['0', '1', '3', 'Nothing: the corner is for runs'], 1, 'The corner shows which out of the inning she made. She made the first one.', 'Count the outs so far, including hers.', 1, null::jsonb, 'How to Keep the Book · Chapter 3 · scorekeeping guide p.26'),
  ('scorebook-4-01', 'general', null, 'scorebook', 4, null, 'A ground ball to the third baseman, who throws to first for the out.', 'How do you score it?', array['3-5', '5-3', '6-3', 'F5'], 1, 'Fielder first, then the fielder who caught the throw: third base is 5 and first base is 3, so 5-3.', 'Write the fielders in the order they handled the ball.', 1, '{"kind":"field","labels":"letters","ball":{"to":5,"type":"ground"}}'::jsonb, 'How to Keep the Book · Chapter 4 · scorekeeping guide p.34'),
  ('scorebook-4-02', 'general', null, 'scorebook', 4, null, 'The left fielder catches a fly ball for the out.', 'How do you score it?', array['F9', 'F7', '7-3', 'L8'], 1, 'Caught in the air is F, and left field is 7: F7.', 'The outfield is numbered left to right.', 1, '{"kind":"field","labels":"letters","ball":{"to":7,"type":"fly"}}'::jsonb, 'How to Keep the Book · Chapter 4 · scorekeeping guide p.32'),
  ('scorebook-4-03', 'general', null, 'scorebook', 4, null, 'The first baseman fields a ground ball and runs to the bag herself for the out.', 'How do you score it?', array['3-1', '1-3', '3U', 'F3'], 2, 'One fielder made the out alone, so it''s her number with a U for unassisted: 3U.', 'Nobody else touched the ball.', 1, '{"kind":"field","labels":"letters","ball":{"to":3,"type":"ground"}}'::jsonb, 'How to Keep the Book · Chapter 4 · scorekeeping guide p.32'),
  ('scorebook-4-04', 'general', null, 'scorebook', 4, null, 'You''re writing down a play made by the shortstop.', 'What number is the shortstop?', array['4', '5', '6', '7'], 2, 'The shortstop is 6, even though she plays between third base (5) and second base (4).', 'It''s the number that seems out of order.', 1, null::jsonb, 'How to Keep the Book · Chapter 4 · scorekeeping guide p.32'),
  ('scorebook-4-05', 'general', null, 'scorebook', 4, null, 'The second baseman snags a line drive for the out.', 'How do you score it?', array['F4', 'L4', '4-3', 'L6'], 1, 'A line drive caught is L plus the fielder''s number. Second base is 4: L4.', 'A liner gets its own letter, and the second baseman isn''t 6.', 1, '{"kind":"field","labels":"letters","ball":{"to":4,"type":"line"}}'::jsonb, 'How to Keep the Book · Chapter 4 · scorekeeping guide p.32'),
  ('scorebook-5-01', 'general', null, 'scorebook', 5, null, 'Lena is on first. Rory, #9, doubles and Lena scores. This is Lena''s box.', 'What goes in the triangle?', array['15', '9', '2', 'Nothing: a double doesn''t earn an RBI'], 1, 'Rory drove Lena in, so Rory''s number, 9, goes in Lena''s triangle. Lena''s diamond gets shaded too.', 'Whose hit brought her home?', 1, '{"kind":"box","reached":"BB","path":4}'::jsonb, 'How to Keep the Book · Chapter 5 · scorekeeping guide p.39'),
  ('scorebook-5-02', 'general', null, 'scorebook', 5, null, 'Runner on third, one out. The batter flies out to right field and the runner tags up and scores.', 'What goes in the batter''s box?', array['F9 with a 2 in the out corner, and SAC circled', '9-2 with a 1 in the out corner', 'A circled 1 and a line to first', 'F9 and a shaded diamond'], 0, 'The catch in right is F9. There was one out already, so this is the second. It scored a run, so it''s a sacrifice fly: circle SAC.', 'How many outs were there before the catch, and what did the fly ball do for the runner?', 1, null::jsonb, 'How to Keep the Book · Chapter 5 · scorekeeping guide p.40'),
  ('scorebook-5-03', 'general', null, 'scorebook', 5, null, 'Here''s the top of the 1st on your team''s page.', 'How many runs scored?', array['1', '2', '3', '4'], 2, 'Count the shaded diamonds: three runners made it all the way around.', 'Runs are the diamonds that are filled in.', 1, '{"kind":"sheet","innings":2,"rows":7,"cells":{"1-1":{"hit":1,"path":4,"rbi":"7"},"2-1":{"reached":"BB","path":4,"rbi":"7"},"3-1":{"hit":3,"path":4,"rbi":"22"},"4-1":{"play":"F8","out":1,"reached":"SAC"},"5-1":{"hit":1,"path":2},"6-1":{"play":"6-3","out":2},"7-1":{"play":"K","out":3,"lastOut":true}}}'::jsonb, 'How to Keep the Book · Chapter 5 · scorekeeping guide p.39'),
  ('scorebook-5-04', 'general', null, 'scorebook', 5, null, 'Runners on first and second. The batter singles and both runners move up one base.', 'Whose boxes do you write in?', array['Only the batter''s', 'The batter''s and both runners''', 'Only the runners''', 'The pitcher''s'], 1, 'The batter gets her single, and each runner''s line is extended in her own box to the base she reached.', 'Everyone who moved needs her line updated.', 1, null::jsonb, 'How to Keep the Book · Chapter 5 · scorekeeping guide p.38'),
  ('scorebook-5-05', 'general', null, 'scorebook', 5, null, 'Your 4th batter strikes out swinging for the third out.', 'What''s in her box when you''re done?', array['K, a 3 in the out corner and a slash across the corner', 'SO and a 3', 'K and a shaded diamond', 'F2 and a 3'], 0, 'K for the strikeout, 3 for the third out, and the slash marks the end of the inning.', 'Three things: the play, the out number, and the end-of-inning mark.', 1, null::jsonb, 'How to Keep the Book · Chapter 5 · scorekeeping guide p.42'),
  ('scorebook-6-01', 'general', null, 'scorebook', 6, null, 'She takes ball four.', 'What do you mark?', array['Circle 1 and draw a line to first', 'Circle BB and draw a line to first', 'Write E2', 'Write FC'], 1, 'A walk is BB, base on balls. It isn''t a hit, so the 1 stays uncircled.', 'A walk has its own letters in the corner.', 1, null::jsonb, 'How to Keep the Book · Chapter 6'),
  ('scorebook-6-02', 'general', null, 'scorebook', 6, null, 'The shortstop bobbles a routine ground ball and the batter is safe at first.', 'How do you score it?', array['Circle 1: it''s a single', 'E6, with a line to first', '6-3', 'FC'], 1, 'She reached on the shortstop''s error: E plus the fielder''s number. An error is never a hit.', 'Did she earn first base, or did the defense give it to her?', 1, '{"kind":"field","labels":"letters","ball":{"to":6,"type":"ground"}}'::jsonb, 'How to Keep the Book · Chapter 6'),
  ('scorebook-6-03', 'general', null, 'scorebook', 6, null, 'She watches a called third strike go by.', 'What goes in her box?', array['K', 'A backwards K', 'F2', 'SO'], 1, 'A called third strike is a backwards K. A forward K means she struck out swinging.', 'Swinging and looking are written differently.', 1, null::jsonb, 'How to Keep the Book · Chapter 6'),
  ('scorebook-6-04', 'general', null, 'scorebook', 6, null, 'Runner on first. A ground ball to short, who throws to second for the force, and the throw goes on to first to get the batter too.', 'What goes in the batter''s box?', array['6-4-3 DP with the out number', 'FC', '6-3', 'E4'], 0, 'Two outs on one play: the batter''s box gets the whole play, shortstop to second to first, and DP.', 'List every fielder who handled the ball, then note that two outs were made.', 1, '{"kind":"field","labels":"letters","ball":{"to":6,"type":"ground"}}'::jsonb, 'How to Keep the Book · Chapter 6'),
  ('scorebook-6-05', 'general', null, 'scorebook', 6, null, 'The runner on first steals second.', 'How do you show it in the runner''s box?', array['Circle the 2', 'Extend her line to second and write SB beside it', 'Write SB in the batter''s box', 'Shade her diamond'], 1, 'Her line goes to second in her own box, labeled SB so it''s clear how she got there.', 'Runner moves go in the runner''s box, not the batter''s.', 1, '{"kind":"box","hit":1,"path":1}'::jsonb, 'How to Keep the Book · Chapter 6')
on conflict (slug) do update set
  topic = excluded.topic, position = excluded.position, track = excluded.track, level = excluded.level, section = excluded.section,
  scenario = excluded.scenario, question = excluded.question, choices = excluded.choices,
  correct_index = excluded.correct_index, explanation = excluded.explanation, hint = excluded.hint,
  difficulty = excluded.difficulty, diagram = excluded.diagram, playbook_ref = excluded.playbook_ref;

